window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0101", [{"word":"geological formation","ipa_uk":"/ˌdʒiəˈlɒdʒɪkl fɔːˈmeɪʃn/","ipa_us":"/ˌdʒiəˈlɑːdʒɪkl fɔːrˈmeɪʃn/","definition_zh":"地质构造；地层；由地质作用形成并具有共同成因的一组岩层","definition_en":"a body or arrangement of rocks that shares a common origin and history, or the process that produced it","core_image":"崖壁上一层层平行叠起的岩层，像被切开的书页","scene":"公路切开的崖壁上，一层层砂岩与页岩平行延伸，地质队员用锤子敲下样品： The road cut exposes a geological formation laid down in a shallow sea.","sceneCN":"这里 geological formation 指「由同一成因沉积形成的一套岩层」（第 1 个义项：具有共同成因与历史的一套岩体）；句意为公路切面露出一套在浅海中沉积形成的岩层。","pos":[{"tag":"n.","zh":"地质构造；地层（可数，复数为 geological formations）"}],"collocations":[{"phrase":"a geological formation","zh":"一处地质构造"},{"phrase":"sedimentary formation","zh":"沉积地层"},{"phrase":"map a formation","zh":"测绘一套地层"},{"phrase":"the formation of the earth's crust","zh":"地壳的形成"},{"phrase":"formation processes","zh":"形成过程"},{"phrase":"a fossil-bearing formation","zh":"含化石地层"}],"forms":[{"label":"复数","form":"geological formations"},{"label":"美式拼写变体","form":"geologic formation"},{"label":"核心名词","form":"formation"},{"label":"形容词","form":"geological"},{"label":"动词（形成）","form":"form"}],"derivatives":[{"word":"formation","pos":"n.","zh":"形成；构造；编队"},{"word":"form","pos":"v./n.","zh":"形成 / 形状、形式"},{"word":"formative","pos":"adj.","zh":"起形成作用的；成长期的"},{"word":"geology","pos":"n.","zh":"地质学"},{"word":"geologist","pos":"n.","zh":"地质学家"},{"word":"geologically","pos":"adv.","zh":"从地质角度；在地质上"}],"senses":[{"no":"01","title":"A rock body with one shared origin","titleCN":"具有共同成因的一套岩层","definition":"a body of rock, often layered, whose parts were produced by the same set of geological processes","definitionCN":"由同一组地质作用形成、通常呈层状的一块或一套岩体","example":"The cliff exposes a geological formation of alternating limestone and shale.","exampleCN":"崖壁露出一套石灰岩与页岩交互叠置的地层。","why":"Formation is from Latin formatio 'a shaping'. Applied to rock, it names a body that one process shaped into a recognizable whole.","whyCN":"formation 来自拉丁语 formatio「塑形」。用于岩石时，它指被同一过程塑造成可识别整体的一套岩体。"},{"no":"02","title":"The process that builds rock","titleCN":"岩石的形成过程","definition":"the set of processes by which rock is deposited, compacted, or crystallized over time","definitionCN":"岩石经沉积、压实或结晶而在时间中生成的一系列过程","example":"The geological formation of the basin took millions of years.","exampleCN":"这个盆地的地质形成过程历时数百万年。","why":"The word can name the making as well as the made thing, because Latin formatio covers both the act of shaping and its result.","whyCN":"这个词既能指「做成的东西」，也能指「做的过程」，因为拉丁语 formatio 同时涵盖塑形动作与其结果。"},{"no":"03","title":"A named stratigraphic unit","titleCN":"地质图上命名的地层单位","definition":"a formal rock unit that geologists name and trace across a region on maps","definitionCN":"地质学家正式命名并在地图上追索其分布范围的岩石单位","example":"Geologists mapped the formation across three counties.","exampleCN":"地质学家在三个县范围内测绘了这套地层。","why":"Once a body is traced and named, the phrase becomes a label on a map rather than a patch of stone you can touch.","whyCN":"当一套岩体被追索并命名后，这个短语就成了地图上的标签，而不只是能触摸的一片石头。"},{"no":"04","title":"A visible structure made by erosion","titleCN":"侵蚀与沉积留下的可见构造","definition":"a distinctive shape in the landscape produced by erosion, deposition, or weathering","definitionCN":"由侵蚀、沉积或风化在地貌上留下的独特形状","example":"Wind erosion gave the formation its arched shape.","exampleCN":"风蚀把这处构造削成了拱形。","why":"The same layered body looks different from every angle; the phrase also names the silhouette that weathering leaves behind.","whyCN":"同一套层状岩体从不同角度看形状各异，因此这个短语也指风化留下的轮廓。"},{"no":"05","title":"A mineral deposit inside rock","titleCN":"岩层中的矿产富集","definition":"a concentration of ore, salt, coal, or other useful minerals within a rock sequence","definitionCN":"岩层序列中矿石、盐、煤或其他有用矿物的富集","example":"The formation contains thin seams of copper.","exampleCN":"这套地层中含有薄薄的铜矿层。","why":"Because minerals are laid down with the rock, a formation is also the natural container in which economic deposits are found.","whyCN":"矿物随岩石一同沉积，因此地层也是经济矿床所在的天然容器。"},{"no":"06","title":"A layer that preserves fossils","titleCN":"保存化石的层位","definition":"a rock layer that holds the remains or traces of ancient organisms","definitionCN":"保存古生物遗体或遗迹的岩层","example":"This formation preserves shells from an ancient reef.","exampleCN":"这套地层保存着古珊瑚礁的贝壳。","why":"Fossils are trapped where sediment buried them, so a formation is also a page of the fossil record.","whyCN":"化石被困在沉积物掩埋之处，因此地层也是化石记录的一页。"},{"no":"07","title":"A landform standing above the plain","titleCN":"高出周围地面的地貌体","definition":"a rock mass that stands out as a hill, wall, or ridge in the surrounding landscape","definitionCN":"在周围地貌中突出为山丘、岩壁或山脊的岩体","example":"The formation rises above the plain like a wall.","exampleCN":"这处岩体像一堵墙一样耸立在平原之上。","why":"When a resistant layer erodes more slowly than its neighbours, it is left standing, and the body becomes a landmark.","whyCN":"当抗蚀性强的岩层比邻近岩层侵蚀得慢时，它就被留下挺立，岩体因而成为地标。"},{"no":"08","title":"The angle and order of the layers","titleCN":"岩层的排列与倾角","definition":"the arrangement, order, and tilt of rock layers relative to one another","definitionCN":"各岩层之间的排列、顺序与倾斜关系","example":"The formation dips steeply toward the valley.","exampleCN":"这套岩层向谷地方向陡倾。","why":"Geologists read a formation as a sentence: the order of layers and their tilt record what happened after deposition.","whyCN":"地质学家把地层当作一句话来读：层的顺序与倾角记录了沉积之后发生的事。"},{"no":"09","title":"Abstract: a pattern built by slow layers","titleCN":"抽象义：由缓慢累积形成的格局","definition":"any pattern or structure that has grown in visible layers over a long period","definitionCN":"任何在长时间中一层层累积而成的格局或结构","example":"Habits form in layers, much like a geological formation.","exampleCN":"习惯一层层地形成，很像一套地质构造。","why":"The metaphor borrows the image of strata: what looks solid was once added piece by piece, and its history is readable in its layers.","whyCN":"这一比喻借用了层理的意象：看似坚固的东西曾一层层添上，其历史可从层中读出。"}],"etymology":{"intro":{"en":"Geological formation joins a Greek-derived word for earth-study to a Latin word for shaping. The parts are well documented; the geological sense is modern. Dates are approximate.","cn":"geological formation 把希腊语来源的「研究地球」与拉丁语的「塑形」组合起来。各部分书证充分，地质义则是现代用法。年代均为约数。"},"items":[{"era":"GREEK GE","en":"Greek ge meant 'earth'. Its deeper origin is not settled; it is often treated as a pre-Greek word, so any Indo-European root proposed for it is a reconstruction.","cn":"希腊语 ge 意为「大地」。其更深来源尚无定论，通常被视为前希腊语词，因此为它提出的任何印欧词根都属重构形式。"},{"era":"GREEK -LOGIA","en":"The suffix -logia 'study, discourse' comes from logos 'word, reason'. Geologia, a Latinized form, was used for earth-study before English adopted it.","cn":"后缀 -logia「研究、论述」来自 logos「言说、理性」。拉丁化的 geologia 在英语借用之前已用于指研究大地。"},{"era":"LATIN FORMA","en":"Latin forma meant 'form, mould, shape'. Its own origin is uncertain; a link with Greek morphe has been suggested but not proved.","cn":"拉丁语 forma 意为「形状、模子、外形」。它自身的来源不确定；有人提出与希腊语 morphe 有关，但未获证明。"},{"era":"LATIN FORMATIO","en":"Formatio 'a forming, a shape' was built on formare 'to shape'. English formation keeps the noun directly from this Latin word.","cn":"formatio「形成、形状」由 formare「塑形」构成。英语 formation 直接承自这个拉丁名词。"},{"era":"EIGHTEENTH CENTURY","en":"Geology became an English science in the eighteenth century, and formation was applied to rock bodies as stratigraphy developed.","cn":"地质学在 18 世纪成为英语世界的学科，随着地层学发展，formation 被用于指岩体。"},{"era":"NINETEENTH CENTURY","en":"Nineteenth-century survey geologists fixed formations as named map units. The exact date when the phrase became standard is not certain.","cn":"19 世纪的测量地质学家把地层固定为地图上的命名单位。这一短语成为标准术语的确切年代已难确考，属来源不确定。"}]},"similar":{"note":{"en":"Group one holds near-identical geological labels that are often swapped; group two holds plain rock words with a narrower everyday meaning.","cn":"第一组是极易互换的近似地质标签；第二组是日常含义更窄的普通岩石词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geologic formation","ipa":"/ˌdʒiəˈlɒdʒɪk fɔːˈmeɪʃn/","tag":"spelling variant","definition":"The American spelling of the same term. Geologic is the adjective used in US usage where British usage prefers geological.","definitionCN":"同一术语的美式拼写。美式用法用 geologic，英式用法多用 geological。"},{"word":"rock formation","ipa":"/rɒk fɔːˈmeɪʃn/","tag":"physical mass","definition":"A visible mass or shape of rock; it need not be a formally named stratigraphic unit.","definitionCN":"肉眼可见的一块岩体或岩石形状，不一定是正式命名的地层单位。"},{"word":"stratigraphic unit","ipa":"/ˌstrætɪˈɡræfɪk ˈjuːnɪt/","tag":"classification term","definition":"The formal category to which a named formation belongs; a formation is one kind of stratigraphic unit.","definitionCN":"命名地层所属的正式分类类别；地层是地层单位的一种。"},{"word":"formulation","ipa":"/ˌfɔːmjuˈleɪʃn/","tag":"spelling trap","definition":"From Latin formula, meaning the way something is expressed or prepared; it has no rock sense and is not related to formation.","definitionCN":"来自拉丁语 formula，指表达或配制的方式；没有岩石义，与 formation 不同源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"stratum","ipa":"/ˈstrɑːtəm/","tag":"single layer","definition":"One layer within a sequence; a formation may contain many strata.","definitionCN":"层序中的单独一层；一套地层可以包含许多层。"},{"word":"bed","ipa":"/bed/","tag":"smallest layer","definition":"A single distinct layer of sediment or rock, usually thinner than a formation.","definitionCN":"单层明显的沉积物或岩石，通常比地层薄。"},{"word":"deposit","ipa":"/dɪˈpɒzɪt/","tag":"material laid down","definition":"Material that has been laid down by water, wind, or chemical action, without implying a named unit.","definitionCN":"由水、风或化学作用堆积下来的物质，不暗示正式命名的单位。"},{"word":"outcrop","ipa":"/ˈaʊtkrɒp/","tag":"exposed part","definition":"The part of a formation that can be seen at the surface; the formation itself may continue underground.","definitionCN":"地层在地表可见的部分；地层本身可继续延伸至地下。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek and Latin morphemes, real geological terms and real collocations, not invented rhymes.","cn":"正常联想：真实的希腊与拉丁语素、真实地质术语与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Ge- is the Greek word for earth, and -logy is the study of it; geology is literally earth-study.","cn":"ge- 是希腊语「大地」，-logy 是「研究」，geology 字面就是「研究大地」。"},{"en":"Formation comes from Latin formare 'to shape', so a formation is a shaped thing.","cn":"formation 来自拉丁语 formare「塑形」，因此一套地层就是被塑造成形之物。"},{"en":"Stratigraphy reads formations layer by layer; the same body can be a cliff, a map unit, or a reservoir.","cn":"地层学逐层阅读地层；同一套岩体可以是崖壁、地图单位或储层。"},{"en":"The phrase usually takes a singular article: a formation, the formation, not formations in general.","cn":"这个短语通常带单数冠词：a formation、the formation，而泛指时用复数。"},{"en":"Geologists name formations after places, as the Burgess Shale and the Morrison Formation show.","cn":"地质学家用地名命名地层，如伯吉斯页岩与莫里森地层。"}],"abstract":[{"en":"Picture a stack of old letters, each written in a different year, still held in one bundle.","cn":"想象一叠旧信，每封写于不同年份，却仍捆成同一束。"},{"en":"Picture a cake cut open so that every layer is visible at once.","cn":"想象一个被切开的蛋糕，每一层都同时露出来。"},{"en":"Picture a habit built one small repetition at a time until it looks like solid rock.","cn":"想象一个习惯由一次次小重复堆成，最后看起来像坚硬的岩石。"}]},"examples":[{"en":"The road cut exposes a geological formation laid down in a shallow sea.","cn":"公路切面露出一套在浅海中沉积形成的地层。"},{"en":"Geologists named the formation after the village where its layers are best seen.","cn":"地质学家以最能看清层理的村庄为这套地层命名。"},{"en":"The formation dips to the east, which tells us the crust was later tilted.","cn":"这套地层向东倾斜，说明地壳后来被掀动过。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「geological（地质的）+ formation（形成物）」——地质作用做出来的一层叠一层的东西 → 地质构造、地层","word":"geological formation"},"root":"希腊语 ge「大地」+ -logia「研究」构成 geological；拉丁语 forma「形状」经 formare「塑形」与 formatio「形成」构成 formation。forma 的更深来源不确定。","sensesIntro":{"en":"Nine senses follow one object through its history: a layered body is made, named, exposed, mined, read for fossils, tilted, and finally borrowed as an image of any slow accumulation.","cn":"九个义项让同一个对象走完它的历史：层状岩体先被形成，再被命名、露出、开采、读出化石、量出倾角，最后被借作一切缓慢累积的意象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cliff face cut open, its parallel layers readable like the pages of a book.","cn":"核心意象：被切开的崖面，平行的层理像书页一样可读。"},"chain":["LAYERED BODY","DEEP TIME","NAMED UNIT","VISIBLE STRUCTURE","MINERAL DEPOSIT","ACCUMULATED PATTERN"],"branches":[{"senses":"S1 · S3","en":"BODY AND LABEL: the same rock mass is first a physical whole, then a name printed on a map.","cn":"岩体与标签：同一块岩体先是有形的整体，再成为印在地图上的名字。"},{"senses":"S2 · S9","en":"SLOW MAKING: the process that built the rock becomes an image for any pattern that grows by layers.","cn":"缓慢成形：造岩过程成为一切逐层生长格局的意象。"},{"senses":"S4 · S7","en":"VISIBLE SHAPE: erosion cuts the body into an arch, wall, or ridge that can be seen from far away.","cn":"可见形状：侵蚀把岩体削成远处可见的拱、墙或脊。"},{"senses":"S5 · S6","en":"WHAT IS INSIDE: seams of ore and shells of fossils are both contents read from the same layers.","cn":"层中之物：矿脉与化石贝壳都是从同一层理中读出的内容。"},{"senses":"S8","en":"TILT AND ORDER: the angle of the layers records the forces that acted after deposition.","cn":"倾角与顺序：层的倾角记录了沉积之后施加的力。"}]},"affixes":{"intro":{"en":"Both halves of the phrase are built from transparent morphemes, so the word can be read part by part.","cn":"短语的两半都由透明的语素构成，因此可以逐部分读出。"},"latinIntro":{"en":"Greek ge and logos supply the first half; Latin forma, formare and formatio supply the second.","cn":"希腊语 ge 与 logos 提供前半部分；拉丁语 forma、formare 与 formatio 提供后半部分。"},"items":[{"word":"ge-","structure":"Greek ge (earth)","meaning":"earth","meaningCN":"大地","example":"Ge- begins geography, geology and geometry.","exampleCN":"ge- 出现在 geography、geology 与 geometry 的开头。"},{"word":"-logy","structure":"Greek -logia (study, discourse)","meaning":"the study of","meaningCN":"……学；对……的研究","example":"Geology is the study of the earth and its rocks.","exampleCN":"geology 是研究地球及其岩石的学科。"},{"word":"formation","structure":"Latin formatio (a shaping)","meaning":"the act or result of shaping","meaningCN":"塑形动作或其结果","example":"The formation of the delta took centuries.","exampleCN":"这片三角洲的形成历经数百年。"},{"word":"form","structure":"Latin forma (shape, mould)","meaning":"shape or structure","meaningCN":"形状；结构","example":"The rock keeps the form of the original shell.","exampleCN":"这块岩石保留了原贝壳的形状。"},{"word":"formative","structure":"form + -ative (tending to)","meaning":"tending to shape something","meaningCN":"有塑形作用的；形成性的","example":"The formative years of the basin were long and quiet.","exampleCN":"这个盆地的形成期漫长而平静。"},{"word":"geology","structure":"geo- + -logy","meaning":"the study of the earth","meaningCN":"地质学","example":"Geology explains how the layers were folded.","exampleCN":"地质学解释了这些层理如何被褶皱。"},{"word":"geologist","structure":"geology + -ist (person who)","meaning":"a person who studies rocks","meaningCN":"研究岩石的人；地质学家","example":"The geologist measured the dip of the formation.","exampleCN":"地质学家测量了地层的倾角。"},{"word":"geological","structure":"geology + -ical (relating to)","meaning":"relating to the study of the earth","meaningCN":"地质的；地质学的","example":"Geological maps show the formation in colour.","exampleCN":"地质图用颜色标出这套地层。"},{"word":"reform","structure":"re- (again) + formare (to shape)","meaning":"to shape again","meaningCN":"重新塑造；改革","example":"The word reform also goes back to Latin formare.","exampleCN":"reform 同样可追溯到拉丁语 formare。"}],"latinEntries":[{"word":"forma","structure":"Latin forma (f., first declension)","meaning":"form, shape, mould","meaningCN":"形状；外形；模子"},{"word":"formare","structure":"formare, formavi, formatum (verb, first conjugation)","meaning":"to shape, mould, form","meaningCN":"塑形；塑造；形成"},{"word":"formatio","structure":"formatio, formationis (f., third declension)","meaning":"a forming, a shape","meaningCN":"形成；形状"},{"word":"geologia","structure":"Medieval Latin geologia, from Greek ge + -logia","meaning":"study of the earth","meaningCN":"研究大地的学问"}]}},{"word":"rock formation","ipa_uk":"/rɒk fɔːˈmeɪʃn/","ipa_us":"/rɑːk fɔːrˈmeɪʃn/","definition_zh":"岩体；岩石构造（地表上可辨认形状或层序的一块岩石）","definition_en":"a recognizable mass, shape, or layered body of rock, especially one seen at the earth's surface","core_image":"荒漠中一座被风削成拱门的独立岩体","scene":"沙漠公路旁，风把砂岩削成一座孤立的拱门，游客在拱下拍照： Wind and sand had carved the rock formation into a freestanding arch.","sceneCN":"这里 rock formation 指「一块形状可辨认的独立岩体」（第 1 个义项：地表上可辨认形状的一块岩体）；句意为风与沙把这处岩体雕成一座独立的拱门。","pos":[{"tag":"n.","zh":"岩体；岩石构造（可数，复数为 rock formations）"}],"collocations":[{"phrase":"a famous rock formation","zh":"著名的岩体"},{"phrase":"sandstone rock formation","zh":"砂岩岩体"},{"phrase":"eroded rock formation","zh":"被侵蚀的岩体"},{"phrase":"rock formation process","zh":"岩石形成过程"},{"phrase":"a cluster of rock formations","zh":"一群岩体"},{"phrase":"protect a rock formation","zh":"保护岩体"}],"forms":[{"label":"复数","form":"rock formations"},{"label":"核心名词（岩石）","form":"rock"},{"label":"核心名词（形成）","form":"formation"},{"label":"动词（形成）","form":"form"},{"label":"形容词（岩质的）","form":"rocky"}],"derivatives":[{"word":"rocky","pos":"adj.","zh":"多岩石的；像岩石般坚硬的"},{"word":"bedrock","pos":"n.","zh":"基岩；根本原则"},{"word":"rockfall","pos":"n.","zh":"落石"},{"word":"formation","pos":"n.","zh":"形成；构造"},{"word":"form","pos":"v./n.","zh":"形成 / 形状"}],"senses":[{"no":"01","title":"A recognizable mass of rock","titleCN":"形状可辨认的一块岩体","definition":"a body of rock with a shape or outline distinct enough to be seen and named as one thing","definitionCN":"形状或轮廓足够分明、可被视为一个整体并加以命名的一块岩石","example":"Wind and sand had carved the rock formation into a freestanding arch.","exampleCN":"风与沙把这处岩体雕成一座独立的拱门。","why":"Formation here does not mean the process but the shaped result: a mass whose outline has become recognizable.","whyCN":"这里的 formation 不指过程，而指塑形后的结果：轮廓已变得可辨认的一块岩体。"},{"no":"02","title":"A conspicuous feature in a landscape","titleCN":"地貌中突出的岩体景观","definition":"a rock mass that stands out as a landmark against the surrounding land","definitionCN":"在周围地形中作为地标突出的岩体","example":"The rock formation dominated the valley for miles around.","exampleCN":"这处岩体在数英里内俯瞰整个山谷。","why":"What makes it a formation rather than rubble is contrast: it resists erosion and therefore rises above its surroundings.","whyCN":"使它成为岩体而非碎石的，是对比：它抗蚀而高出周围地面。"},{"no":"03","title":"A layered sequence of rock","titleCN":"层状叠置的岩体","definition":"a stack of visible layers that records successive episodes of deposition","definitionCN":"记录一次次沉积事件的可见层状叠置体","example":"The rock formation shows a hundred thin bands of shale.","exampleCN":"这处岩体显出一百条薄薄的页岩层带。","why":"The word formation keeps its Latin sense of shaping, and layers are the visible trace of that shaping.","whyCN":"formation 保留了拉丁语「塑形」之义，而层理正是这一塑形过程的可见痕迹。"},{"no":"04","title":"The process of rock being made","titleCN":"岩石的形成过程","definition":"the natural process by which sediment, lava, or magma becomes solid rock","definitionCN":"沉积物、熔岩或岩浆变为坚固岩石的自然过程","example":"The rock formation process began with ash falling into a lake.","exampleCN":"岩石形成过程始于火山灰落入湖中。","why":"English allows both readings, so context alone decides whether the phrase names the thing or the making of it.","whyCN":"英语容许两种读法，因此只能靠上下文判断短语指成品还是指制造过程。"},{"no":"05","title":"A mapped rock unit","titleCN":"图上标出的岩石单位","definition":"a body of rock drawn and labelled on a geological map for study","definitionCN":"为研究而在地质图上绘出并标注的岩体","example":"Each rock formation on the map has its own colour.","exampleCN":"图上的每一处岩体都有自己的颜色。","why":"Survey geologists reduce a three-dimensional body to a coloured shape, and the phrase follows the map.","whyCN":"测量地质学家把三维岩体压缩为彩色图形，这个短语也随之上了地图。"},{"no":"06","title":"An erosional remnant","titleCN":"侵蚀残留体","definition":"an isolated pillar, arch, or knob left standing after the softer rock around it has worn away","definitionCN":"周围较软岩石被蚀去后孤立残留的石柱、拱门或石丘","example":"The isolated rock formation is all that remains of a former plateau.","exampleCN":"这处孤立岩体是昔日高原仅存的部分。","why":"Erosion removes the weak and leaves the strong, so a formation can be read as a negative image of what has been lost.","whyCN":"侵蚀带走软弱部分、留下坚硬部分，因此岩体可读作「已失去之物」的反像。"},{"no":"07","title":"A climbing or visitor attraction","titleCN":"攀岩或观光对象","definition":"a rock mass used for climbing, photography, or tourism because of its shape","definitionCN":"因其形状而被用于攀岩、摄影或旅游的岩体","example":"Climbers travel to the rock formation for its long crack.","exampleCN":"攀岩者为那条长裂缝专程来到这处岩体。","why":"Once a shape becomes famous, the phrase shifts from geology to recreation without changing its referent.","whyCN":"一旦某形状出了名，这个短语就从地质学转向休闲用途，而所指对象并未改变。"},{"no":"08","title":"Abstract: a structure slowly assembled","titleCN":"抽象义：缓慢拼合而成的结构","definition":"any structure that appears solid but was assembled piece by piece over time","definitionCN":"任何看似坚固、实则由时间中逐块拼合而成的结构","example":"The organization grew like a rock formation, one layer of rules at a time.","exampleCN":"这个组织像岩体一样生长，一次添一层规则。","why":"The metaphor keeps the key contrast: hard and permanent on the outside, gradual and layered in its history.","whyCN":"这一比喻保留了关键对比：外表坚硬恒久，历史却渐进且分层。"}],"etymology":{"intro":{"en":"Rock formation joins a word of uncertain origin to a Latin-derived noun. The geological use is nineteenth-century. Dates are approximate.","cn":"rock formation 把一个来源不确定的词与一个拉丁语来源的名词组合起来。地质用法形成于 19 世纪。年代均为约数。"},"items":[{"era":"OLD ENGLISH ROCK","en":"Source uncertain: rock appears in Middle English, probably through Old North French roque from Vulgar Latin rocca. The deeper origin of rocca is unknown, so any further root is a reconstruction.","cn":"来源不确定：rock 见于中古英语，可能经古北部法语 roque 来自通俗拉丁语 rocca。rocca 的更深来源不明，凡再往上推的词根均属重构形式。"},{"era":"LATIN FORMA","en":"Formation rests on Latin forma 'shape' and formare 'to shape'. Forma itself is of uncertain origin; a Greek connection has been suggested but not demonstrated.","cn":"formation 依托拉丁语 forma「形状」与 formare「塑形」。forma 本身来源不确定；与希腊语的关联只是提出过，未获证明。"},{"era":"LATIN FORMATIO","en":"Formatio named a shaping or a shape in Latin, and English took the noun through Old French formation.","cn":"formatio 在拉丁语中指塑形或形状，英语经古法语 formation 借入这个名词。"},{"era":"EARLY GEOLOGY","en":"In the eighteenth century naturalists described 'rocks' and their 'formations' separately, the first as material and the second as arrangement.","cn":"18 世纪博物学家把「岩石」与「其构造」分开描述，前者指材料，后者指排列。"},{"era":"NINETEENTH CENTURY","en":"By the nineteenth century rock formation was common in survey reports for a conspicuous mass, while geological formation served as the formal stratigraphic label.","cn":"到 19 世纪，rock formation 在测量报告中常指显眼的岩体，而 geological formation 则用作正式地层标签。"},{"era":"TOURISM SENSE","en":"The tourist sense is twentieth-century and its first recorded use is not pinned down, so the date is uncertain.","cn":"旅游义产生于 20 世纪，其最早书证尚未确定，因此年代存疑。"}]},"similar":{"note":{"en":"Group one holds labels from geology and tourism that are often confused with the phrase; group two holds ordinary words for rock masses.","cn":"第一组是常与该短语混淆的地质与旅游标签；第二组是普通岩石体的日常用词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geological formation","ipa":"/ˌdʒiəˈlɒdʒɪkl fɔːˈmeɪʃn/","tag":"formal unit","definition":"The formal stratigraphic term for a named body of rock; rock formation is looser and often visual.","definitionCN":"命名岩体的正式地层术语；rock formation 更宽松，常偏重视觉形状。"},{"word":"rock outcrop","ipa":"/rɒk ˈaʊtkrɒp/","tag":"exposed part","definition":"The visible part of bedrock at the surface; it may be small and need not form a landmark.","definitionCN":"基岩在地表的可见部分，可以很小，也不必形成地标。"},{"word":"rock unit","ipa":"/rɒk ˈjuːnɪt/","tag":"mapping term","definition":"A body of rock treated as one item on a map, whether or not it has a dramatic shape.","definitionCN":"在地图上作为一个项目处理的岩体，不论其形状是否醒目。"},{"word":"bedrock","ipa":"/ˈbedrɒk/","tag":"solid base","definition":"The solid rock beneath soil and loose material; it is a position in the stack, not a shape.","definitionCN":"土壤与松散物之下的坚固岩石；它指层序中的位置，而非形状。"}]},{"heading":"NEAR MEANING","entries":[{"word":"boulder","ipa":"/ˈbəʊldə/","tag":"single loose block","definition":"One large detached block of rock; a formation is still attached and usually much larger.","definitionCN":"一块脱离母岩的大石；岩体仍与原岩相连，且通常大得多。"},{"word":"cliff","ipa":"/klɪf/","tag":"steep face","definition":"A steep rock face, especially at a coast; it describes the surface, not the whole body.","definitionCN":"陡峭岩面，尤指海岸处；它描述表面，而非整个岩体。"},{"word":"monolith","ipa":"/ˈmɒnəlɪθ/","tag":"single stone","definition":"A single massive stone or a structure cut from one; a formation may consist of many layers.","definitionCN":"单块巨石或由单石凿成的构筑物；岩体可由许多层组成。"},{"word":"landform","ipa":"/ˈlændfɔːm/","tag":"surface shape","definition":"Any natural shape of the land surface, including valleys and dunes, not only rock.","definitionCN":"地表任何自然形状，包括谷地与沙丘，不限于岩石。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real geological labels and real collocations, not invented rhymes.","cn":"正常联想：真实语素、真实地质标签与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Rock is the material; formation is the shape. The phrase names a shape made of material.","cn":"rock 是材料，formation 是形状；短语指由材料构成的形状。"},{"en":"Compare geological formation: there the stress is on stratigraphic classification, here on the visible mass.","cn":"与 geological formation 比较：后者强调地层分类，这里强调可见岩体。"},{"en":"Famous examples are named shapes: Delicate Arch, Old Harry Rocks, the Pillars of Hercules.","cn":"著名例子都是命名的形状：精致拱门、老哈里岩、海格力斯之柱。"},{"en":"A formation can be an arch, a pillar, a wall, or a stack of layers; all are outlines.","cn":"岩体可以是拱门、石柱、岩壁或层叠体，共同点都是轮廓。"},{"en":"The phrase takes a plural for a group: a cluster of rock formations.","cn":"指一组时用复数：a cluster of rock formations。"}],"abstract":[{"en":"Picture a sandcastle that survives the tide because one tower was packed harder than the rest.","cn":"想象一座沙堡，因为一座塔拍得比别处更实，退潮后仍立着。"},{"en":"Picture a wall built one stone per year, still standing after a lifetime.","cn":"想象一堵墙每年只添一块石，一辈子后仍然立着。"},{"en":"Picture a reputation that looks like one solid block but was layered by many small acts.","cn":"想象一个名声看似整块实心，实由许多小事层层堆成。"}]},"examples":[{"en":"Wind and sand had carved the rock formation into a freestanding arch.","cn":"风与沙把这处岩体雕成一座独立的拱门。"},{"en":"The ranger warned visitors not to climb the fragile rock formation.","cn":"巡护员提醒游客不要攀爬这处易损岩体。"},{"en":"Each rock formation on the map is coloured by its age.","cn":"地图上每一处岩体都按年代着色。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「rock（岩石）+ formation（形成物）」——岩石被自然做成的一个有形的东西 → 岩体、岩石构造","word":"rock formation"},"root":"rock 来源不确定，可能经古北部法语 roque 来自通俗拉丁语 rocca，rocca 更深来源不明；formation 来自拉丁语 formatio「形成」，源自 forma「形状」与 formare「塑形」，forma 亦来源不确定。","sensesIntro":{"en":"Eight senses move from a visible mass to its making, its mapping, its erosion, its fame, and finally to any slowly assembled structure.","cn":"八个义项从可见岩体出发，依次涉及它的形成、测绘、侵蚀、名声，最后落到一切缓慢拼合的结构。"},"semanticMap":{"core":{"en":"CORE IMAGE: a single mass of rock whose outline can be recognized from a distance.","cn":"核心意象：一块从远处就能认出轮廓的岩体。"},"chain":["VISIBLE MASS","LANDMARK","LAYER STACK","MAKING PROCESS","MAPPED UNIT","EROSIONAL REMNANT"],"branches":[{"senses":"S1 · S2","en":"SHAPE AND CONTRAST: an outline becomes a landmark only because it differs from what surrounds it.","cn":"形状与对比：轮廓之所以成为地标，只因它与周围不同。"},{"senses":"S3 · S4","en":"STACK AND PROCESS: the visible layers and the making that produced them are two readings of one phrase.","cn":"层叠与过程：可见层理与造成它的过程，是同一短语的两种读法。"},{"senses":"S5","en":"MAP LABEL: survey geology turns the mass into a coloured shape with a name.","cn":"地图标签：测量地质学把岩体变成有名字的彩色图形。"},{"senses":"S6","en":"REMNANT: erosion leaves the hard part standing as a negative record of what vanished.","cn":"残体：侵蚀留下坚硬部分，作为消失之物的反向记录。"},{"senses":"S7 · S8","en":"PUBLIC AND METAPHOR: a famous shape becomes a destination, and any slow-built structure can borrow the image.","cn":"公众与比喻：著名形状成为目的地，任何缓慢建成的结构都可借用这一意象。"}]},"affixes":{"intro":{"en":"The phrase is an English noun plus a Latin-derived noun, so each half can be read on its own.","cn":"这个短语是英语名词加拉丁语来源名词，两半都可单独读出。"},"latinIntro":{"en":"Latin forma and formatio stand behind formation; rock itself has no settled Latin source.","cn":"拉丁语 forma 与 formatio 支撑 formation；rock 本身没有确定的拉丁语来源。"},"items":[{"word":"rock","structure":"Middle English rock, probably from Old North French roque","meaning":"stone; a mass of stone","meaningCN":"岩石；石块","example":"The rock split along a straight crack.","exampleCN":"岩石沿一条直裂缝裂开。"},{"word":"rocky","structure":"rock + -y (full of, like)","meaning":"full of rocks or as hard as rock","meaningCN":"多岩石的；坚硬如石的","example":"The rocky slope slowed the climbers.","exampleCN":"多石的坡面拖慢了攀登者。"},{"word":"bedrock","structure":"bed (layer) + rock","meaning":"solid rock under soil","meaningCN":"土壤之下的基岩","example":"The drill reached bedrock at ten metres.","exampleCN":"钻头在十米处触及基岩。"},{"word":"formation","structure":"Latin formatio (a shaping)","meaning":"the act or result of shaping","meaningCN":"形成；构造","example":"The formation of the arch took ages of wind.","exampleCN":"拱门的形成历经漫长风蚀。"},{"word":"form","structure":"Latin forma (shape)","meaning":"to give shape to something","meaningCN":"使成形；构成","example":"The layers form a stepped wall.","exampleCN":"这些层构成一堵阶梯状的墙。"},{"word":"formative","structure":"form + -ative (tending to)","meaning":"shaping, developmental","meaningCN":"塑形的；形成期的","example":"The formative stage of the arch was slow.","exampleCN":"这座拱门的形成阶段很缓慢。"},{"word":"landform","structure":"land + form","meaning":"a natural shape of the land","meaningCN":"地貌；地表形态","example":"The arch is a striking landform.","exampleCN":"这座拱门是醒目的地貌。"},{"word":"outcrop","structure":"out + crop (top of a plant)","meaning":"rock appearing at the surface","meaningCN":"露出地表的岩石","example":"An outcrop showed where the layer began.","exampleCN":"一处露头显示该层从哪里开始。"}],"latinEntries":[{"word":"forma","structure":"Latin forma (f., first declension)","meaning":"shape, mould","meaningCN":"形状；模子"},{"word":"formare","structure":"formare, formavi, formatum (verb, first conjugation)","meaning":"to shape, form","meaningCN":"塑形；形成"},{"word":"formatio","structure":"formatio, formationis (f., third declension)","meaning":"a forming, a shape","meaningCN":"形成；形状"}]}},{"word":"outcrop","ipa_uk":"/ˈaʊtkrɒp/","ipa_us":"/ˈaʊtkrɑːp/","definition_zh":"露头；岩层露出地表的部分；露出地表","definition_en":"the part of a rock layer that can be seen at the surface, or to appear at the surface in this way","core_image":"草坡被雨水冲开一块，灰白色岩层断面从土里露出一角","scene":"山坡上的草被雨水冲开一块，露出灰白色的岩层断面： A small outcrop of limestone appeared where the soil had washed away.","sceneCN":"这里 outcrop 指「岩层在地表露出的部分」（第 1 个义项：基岩或岩层在地表可见的一块）；句意为土壤被冲走的地方露出一小片石灰岩露头。","pos":[{"tag":"n.","zh":"露头；岩层出露部分（可数，复数为 outcrops）"},{"tag":"vi.","zh":"出露；露出地表（outcrops, outcropped, outcropping）"}],"collocations":[{"phrase":"a rock outcrop","zh":"岩石露头"},{"phrase":"a limestone outcrop","zh":"石灰岩露头"},{"phrase":"outcrop of bedrock","zh":"基岩露头"},{"phrase":"the outcrop appears","zh":"露头出现"},{"phrase":"map the outcrops","zh":"标绘露头"},{"phrase":"a coastal outcrop","zh":"海岸露头"}],"forms":[{"label":"复数","form":"outcrops"},{"label":"三单（he/she/it）","form":"outcrops"},{"label":"过去式","form":"outcropped"},{"label":"过去分词","form":"outcropped"},{"label":"现在分词","form":"outcropping"}],"derivatives":[{"word":"outcropping","pos":"n./adj.","zh":"露头；出露的"},{"word":"crop","pos":"n./v.","zh":"作物；剪短、收割"},{"word":"cropland","pos":"n.","zh":"耕地"},{"word":"rocky","pos":"adj.","zh":"多岩石的"},{"word":"exposure","pos":"n.","zh":"出露；暴露"}],"senses":[{"no":"01","title":"Rock visible at the surface","titleCN":"岩层在地表露出的部分","definition":"a place where rock that is normally buried can be seen at the earth's surface","definitionCN":"原本埋在地下的岩石在地表可见的地方","example":"A small outcrop of limestone appeared where the soil had washed away.","exampleCN":"土壤被冲走的地方露出一小片石灰岩露头。","why":"Out plus crop pictures something breaking through the surface, like a plant top pushing out of the ground.","whyCN":"out 加 crop 描绘某物破土而出，像植物的顶端从地面钻出。"},{"no":"02","title":"To appear at the surface","titleCN":"动词义：出露地表","definition":"of rock, to reach the surface and become visible there","definitionCN":"指岩层到达地表并在那里可见","example":"The granite outcrops along the ridge.","exampleCN":"花岗岩沿山脊出露。","why":"The verb keeps the same image but focuses on the event of breaking through rather than the patch left behind.","whyCN":"动词保留同一意象，但聚焦于破土这一事件，而非留下的那片露头。"},{"no":"03","title":"A patch seen in a field","titleCN":"野外可见的一小片露头","definition":"a limited patch of bedrock visible between soil, grass, or snow","definitionCN":"土壤、草或雪之间可见的一小片基岩","example":"The shepherd knew every outcrop on the hillside.","exampleCN":"牧羊人熟悉山坡上每一处露头。","why":"In fieldwork an outcrop is what you can actually put your hand on; everything else is inference.","whyCN":"在野外工作中，露头是你真正能摸到的部分，其余都靠推断。"},{"no":"04","title":"An isolated exposure of one layer","titleCN":"单一层位的孤立露头","definition":"a small isolated place where one particular stratum can be examined","definitionCN":"可对某一特定层位进行观察的一小块孤立出露处","example":"The sandstone outcrop is the only place where the lower layer can be studied.","exampleCN":"这处砂岩露头是研究下层的唯一地点。","why":"A single window into a buried layer is enough to measure its thickness and dip.","whyCN":"观察埋藏层位的一扇小窗，就足以测量其厚度与倾角。"},{"no":"05","title":"The edge of a coal or ore seam","titleCN":"煤层或矿脉的露头","definition":"the surface end of a mineral seam where it meets the ground","definitionCN":"矿层与地面相接的地表端","example":"Miners followed the coal outcrop into the hillside.","exampleCN":"矿工沿着煤层露头掘进山体。","why":"Prospectors begin where a seam shows itself, because the visible end points toward the buried body.","whyCN":"勘探者从矿层自己显露的一端开始，因为可见的端头指向埋藏的主体。"},{"no":"06","title":"A projecting rock on a slope","titleCN":"坡面上突起的岩块","definition":"a rock mass that sticks out from a slope or cliff face","definitionCN":"从坡面或崖面突出来的岩体","example":"A grey outcrop barred the path along the cliff.","exampleCN":"一处灰色露头挡住崖边小路。","why":"The word also describes the shape that stands out, not only the fact that it is visible.","whyCN":"这个词也描述突出来的形状，而不只是「可见」这一事实。"},{"no":"07","title":"A coral or reef exposure","titleCN":"珊瑚或礁体的出露","definition":"a mass of reef rock that rises above the surrounding sediment or water","definitionCN":"高出周围沉积物或水面的礁岩体","example":"A coral outcrop broke the surface at low tide.","exampleCN":"退潮时一处珊瑚礁体露出水面。","why":"The same geometry applies underwater: whatever rises above its surroundings becomes visible.","whyCN":"同一几何关系适用于水下：高出周围的部分就会显露出来。"},{"no":"08","title":"Figurative: something surfacing","titleCN":"抽象义：隐藏之物显现","definition":"a visible sign of something that was previously hidden or unspoken","definitionCN":"先前隐藏或未被言明之物显露出来的可见迹象","example":"The protest was an outcrop of years of quiet resentment.","exampleCN":"这场抗议是多年沉默怨气的一次显露。","why":"The metaphor treats feelings as strata: most stay buried, and what shows at the surface is only a patch.","whyCN":"这一比喻把情绪当作地层：大部分仍埋着，露出地表的只是一小块。"},{"no":"09","title":"A visible portion of a larger whole","titleCN":"整体中可见的一小部分","definition":"the small part of a larger body that can be observed directly","definitionCN":"较大整体中可直接观察到的一小部分","example":"The visible outcrop is a tiny sample of the granite below.","exampleCN":"可见的露头只是下方花岗岩的一小份样本。","why":"Field geology reasons from windows: the outcrop is evidence, and the formation is the hidden whole.","whyCN":"野外地质学从窗口推理：露头是证据，地层是隐藏的整体。"}],"etymology":{"intro":{"en":"Outcrop is an English compound of out and crop, coined for geology in the nineteenth century. Its parts are clear, but the exact first date is uncertain.","cn":"outcrop 是 out 与 crop 的英语复合词，19 世纪为地质学而造。各部分清楚，但确切首见年代不确定。"},"items":[{"era":"OLD ENGLISH CROP","en":"Crop meant the top of a plant or an ear of grain, from Proto-Germanic kruppaz. The idea is a rounded head standing above the ground.","cn":"crop 原指植物顶端或谷穗，来自原始日耳曼语 kruppaz。其意象是高出地面的圆头。"},{"era":"OUT + CROP","en":"To crop out meant to show itself at the surface, as a stratum does where soil has worn away.","cn":"crop out 原指在地表显露出来，正如土壤被蚀去处的地层。"},{"era":"GEOLOGICAL COINAGE","en":"Geologists turned the verb phrase into the noun outcrop in the nineteenth century; the earliest citation is not fixed, so the date is uncertain.","cn":"地质学家在 19 世纪把动词短语转为名词 outcrop；最早书证未固定，因此年代存疑。"},{"era":"FIELD METHOD","en":"Because buried rock can only be sampled where it crops out, the word became basic vocabulary of field mapping.","cn":"由于埋藏岩石只能在出露处采样，这个词成了野外填图的基本词汇。"},{"era":"EXTENDED USE","en":"The figurative sense of anything surfacing is modern and informal; no single first use is recorded.","cn":"任何事物显露的比喻义属现代口语用法，没有单一的最早书证。"}]},"similar":{"note":{"en":"Group one holds field and mapping words that are routinely interchanged with outcrop; group two holds words for exposed rock or bare ground.","cn":"第一组是常与 outcrop 互换的野外与填图用词；第二组是裸露岩石或裸地的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"outcropping","ipa":"/ˈaʊtkrɒpɪŋ/","tag":"same family","definition":"A variant noun or adjective meaning the same exposure; it often describes a mass that projects from a slope.","definitionCN":"同义的变体名词或形容词，指同一出露；常描述从坡面突出的岩体。"},{"word":"crop out","ipa":"/krɒp aʊt/","tag":"verb phrase","definition":"The verb phrase behind the noun: a layer crops out where it reaches the surface.","definitionCN":"名词背后的动词短语：岩层到达地表处就出露。"},{"word":"exposure","ipa":"/ɪkˈspəʊʒə/","tag":"general term","definition":"Any place where a rock body is open to view, including quarries and road cuts; outcrop is the natural surface case.","definitionCN":"岩体可供观察的任何地点，包括采石场与路堑；outcrop 特指自然地表的情形。"},{"word":"outerop","ipa":"/ˈaʊtərɒp/","tag":"non-word trap","definition":"Not an English word. The vowel in the second syllable is o, not e, so outcrop should not be written outerop.","definitionCN":"并非英语词。第二音节的元音是 o 而非 e，因此不能写成 outerop。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bedrock","ipa":"/ˈbedrɒk/","tag":"solid base rock","definition":"The solid rock beneath soil; it may be exposed as an outcrop or remain covered.","definitionCN":"土壤之下的坚固岩石；它可作为露头露出，也可仍被覆盖。"},{"word":"boulder","ipa":"/ˈbəʊldə/","tag":"loose block","definition":"A detached block of rock; unlike an outcrop, it is not attached to the parent body.","definitionCN":"脱离母岩的石块；与露头不同，它不与母体相连。"},{"word":"cliff","ipa":"/klɪf/","tag":"vertical face","definition":"A steep face of rock; an outcrop may form part of a cliff but need not be vertical.","definitionCN":"陡峭岩面；露头可以是崖壁的一部分，但不必垂直。"},{"word":"bare ground","ipa":"/beə ɡraʊnd/","tag":"everyday phrase","definition":"Ground with no vegetation or soil cover; it may be soil or gravel, not necessarily rock.","definitionCN":"没有植被或土壤覆盖的地面，可能是土或砾石，不一定是岩石。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real English morphemes, real field terms and real collocations, not invented rhymes.","cn":"正常联想：真实英语语素、真实野外术语与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Out + crop: the rock crops out of the ground like a plant top.","cn":"out 加 crop：岩石像植物顶端一样从地里长出来。"},{"en":"A formation is the whole body; an outcrop is only the window onto it.","cn":"formation 是整体岩体，outcrop 只是观察它的窗口。"},{"en":"Field geologists say the layer crops out in the stream bed.","cn":"野外地质学家说岩层在河床出露。"},{"en":"Outcrops are mapped as lines or patches, because they are edges of buried bodies.","cn":"露头在地图上被画成线或斑块，因为它们是埋藏岩体的边缘。"},{"en":"Coal seams are traced from their outcrop inward.","cn":"煤层从露头向内部追索。"}],"abstract":[{"en":"Picture a buried pipe with one joint poking through the paving.","cn":"想象一根埋在地下的管道，只有一个接头从路面探出。"},{"en":"Picture an iceberg showing only its tip above the water.","cn":"想象一座冰山只把尖端露在水面。"},{"en":"Picture an old argument surfacing years later in a single sharp remark.","cn":"想象多年前的争执，多年后因一句尖刻的话而浮出水面。"}]},"examples":[{"en":"A small outcrop of limestone appeared where the soil had washed away.","cn":"土壤被冲走的地方露出一小片石灰岩露头。"},{"en":"The geologist measured the dip at the only outcrop in the valley.","cn":"地质学家在山谷中唯一的露头处测量了倾角。"},{"en":"Granite outcrops all along the ridge, so the bedrock is easy to sample.","cn":"花岗岩沿山脊到处出露，因此基岩易于采样。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「奥特克罗普」——一块从土里探出头的岩石 → 露头、出露","word":"outcrop"},"root":"英语 out「向外」+ crop「植物顶端、谷穗」（原始日耳曼语 kruppaz）；19 世纪地质学用作「岩层出露」，属英语本族复合词，无拉丁同族。","sensesIntro":{"en":"Nine senses start from a patch of surfaced rock and extend to seams, reefs, slopes, and finally to anything hidden that becomes briefly visible.","cn":"九个义项从一片露出地表的岩石出发，延伸到矿层、礁体、坡面，最后落到一切短暂显露的隐藏之物。"},"semanticMap":{"core":{"en":"CORE IMAGE: a grey rock face breaking through grass where the soil has worn away.","cn":"核心意象：土壤被蚀去处，灰白岩面从草地里破出。"},"chain":["SURFACED PATCH","BREAKING OUT","FIELD WINDOW","SEAM EDGE","PROJECTING MASS","SURFACING SIGN"],"branches":[{"senses":"S1 · S3","en":"PATCH AND WINDOW: the visible patch is also the only place where the buried body can be examined.","cn":"露出的一片与窗口：可见的一片，也是检查埋藏岩体的唯一地点。"},{"senses":"S2","en":"EVENT: the verb turns the patch into an act of reaching the surface.","cn":"事件：动词把这片露头转为到达地表的行为。"},{"senses":"S4 · S9","en":"SAMPLE OF A WHOLE: one exposure stands for a body far larger than what is seen.","cn":"整体的样本：一处露头代表远比所见更大的岩体。"},{"senses":"S5 · S7","en":"EDGE AND RISE: seams and reefs both show where a mass meets the surface.","cn":"边缘与隆起：矿层与礁体都显示岩体与地表相接之处。"},{"senses":"S6 · S8","en":"PROJECTION AND METAPHOR: what sticks out is what gets noticed, in rock and in feeling alike.","cn":"突出与比喻：无论是岩石还是情绪，突出来的部分才被注意到。"}]},"affixes":{"intro":{"en":"Outcrop is a transparent English compound, so its two halves can be read directly.","cn":"outcrop 是透明的英语复合词，两半可直接读出。"},"latinIntro":{"en":"The word is native English in both parts, so no Latin source form stands behind it; the table below therefore records no Latin relatives.","cn":"这个词的两部分都是英语本族语，背后没有拉丁语源形式，因此下表不列拉丁同族词。"},"items":[{"word":"out-","structure":"Old English ut (out, outward)","meaning":"outward, beyond the surface","meaningCN":"向外；超出表面","example":"Out- marks something moving into view.","exampleCN":"out- 标记某物进入视野。"},{"word":"crop","structure":"Old English crop (top of a plant, ear of grain)","meaning":"the visible top of a growing thing","meaningCN":"生长之物可见的顶端","example":"The wheat crop stood above the soil.","exampleCN":"小麦的穗高出地面。"},{"word":"outcrop","structure":"out + crop","meaning":"rock showing at the surface","meaningCN":"在地表显露的岩石","example":"The outcrop is the only exposure for miles.","exampleCN":"这处露头是数英里内唯一的出露。"},{"word":"outcropping","structure":"outcrop + -ing (noun or participle)","meaning":"an exposure; projecting","meaningCN":"出露；突出的","example":"An outcropping of schist blocked the trail.","exampleCN":"一片片岩露头挡住了小径。"},{"word":"crop out","structure":"verb phrase","meaning":"to reach the surface","meaningCN":"出露地表","example":"The seam crops out beside the road.","exampleCN":"矿层在路边出露。"},{"word":"cropland","structure":"crop + land","meaning":"land used for crops","meaningCN":"耕地","example":"The cropland lies on deep soil, not on rock.","exampleCN":"耕地位于深厚土壤上，而非岩石上。"},{"word":"exposure","structure":"ex- (out) + ponere (to place)","meaning":"a placing out; a place open to view","meaningCN":"显露；可供观察之处","example":"The road cut provides a fresh exposure.","exampleCN":"路堑提供了一处新鲜剖面。"},{"word":"bedrock","structure":"bed + rock","meaning":"solid rock under soil","meaningCN":"土壤下的基岩","example":"Bedrock shows through the thin soil.","exampleCN":"基岩从薄土中露出。"}],"latinEntries":[]}},{"word":"limestone","ipa_uk":"/ˈlaɪmstəʊn/","ipa_us":"/ˈlaɪmstoʊn/","definition_zh":"石灰岩；以碳酸钙为主要成分的沉积岩","definition_en":"a sedimentary rock made mainly of calcium carbonate, often formed from the shells and skeletons of marine organisms","core_image":"溶洞壁上被水溶出沟槽的灰白色层状岩石","scene":"溶洞入口的岩壁上留着水滴溶出的沟槽，导游用手电照出层理： The cave walls are made of limestone that rainwater has slowly dissolved.","sceneCN":"这里 limestone 指「以碳酸钙为主的沉积岩」（第 1 个义项：主要由碳酸钙构成的沉积岩）；句意为洞壁由雨水缓慢溶蚀的石灰岩构成。","pos":[{"tag":"n.","zh":"石灰岩（物质名词；指不同种类时复数为 limestones）"}],"collocations":[{"phrase":"a limestone cave","zh":"石灰岩溶洞"},{"phrase":"limestone cliffs","zh":"石灰岩崖壁"},{"phrase":"limestone quarry","zh":"石灰岩采石场"},{"phrase":"limestone pavement","zh":"石灰岩溶蚀台地"},{"phrase":"limestone deposits","zh":"石灰岩沉积"},{"phrase":"crushed limestone","zh":"碎石灰岩"}],"forms":[{"label":"复数（指多种石灰岩）","form":"limestones"},{"label":"核心名词（石灰）","form":"lime"},{"label":"核心名词（石头）","form":"stone"},{"label":"形容词（石灰质的）","form":"calcareous"},{"label":"相关岩石","form":"chalk"}],"derivatives":[{"word":"lime","pos":"n./v.","zh":"石灰；用石灰处理"},{"word":"limy","pos":"adj.","zh":"含石灰的；黏性的"},{"word":"limestone pavement","pos":"n.","zh":"石灰岩溶蚀台地"},{"word":"calcium","pos":"n.","zh":"钙"},{"word":"calcareous","pos":"adj.","zh":"钙质的；石灰质的"}],"senses":[{"no":"01","title":"A sedimentary rock of calcium carbonate","titleCN":"以碳酸钙为主的沉积岩","definition":"a sedimentary rock composed chiefly of calcium carbonate, usually built up from shell debris or chemical precipitation","definitionCN":"主要由碳酸钙组成、通常由贝壳碎屑或化学沉淀堆积而成的沉积岩","example":"The cave walls are made of limestone that rainwater has slowly dissolved.","exampleCN":"洞壁由雨水缓慢溶蚀的石灰岩构成。","why":"Lime plus stone names the rock by its chief product: burn it and you get lime, the binder of mortar.","whyCN":"lime 加 stone 以主要产物给岩石命名：烧炼它便得到石灰，也就是灰浆的胶结料。"},{"no":"02","title":"Building stone cut from beds","titleCN":"作为建筑石材的石灰岩","definition":"the rock used as dimension stone for walls, floors, and monuments","definitionCN":"用作墙体、地面与纪念碑块材的该种岩石","example":"The old church was built of pale limestone blocks.","exampleCN":"这座老教堂用浅色石灰岩块砌成。","why":"Because it cuts easily and hardens on exposure, limestone became a standard building stone wherever beds were thick.","whyCN":"由于易于切割且暴露后会变硬，只要层厚足够，石灰岩就成了标准建筑石材。"},{"no":"03","title":"A bed or formation of the rock","titleCN":"作为层位或地层的石灰岩","definition":"a distinct layer or body of limestone within a rock sequence","definitionCN":"岩层序列中一层或一套明确的石灰岩体","example":"A thick limestone bed separates the two shale units.","exampleCN":"一层厚石灰岩把两套页岩隔开。","why":"As a mass noun it names material; as a count noun it names one bed of that material.","whyCN":"作物质名词时指材料，作可数名词时指该材料的一个层位。"},{"no":"04","title":"Karst terrain shaped by solution","titleCN":"溶蚀形成的喀斯特地貌","definition":"the landscape of caves, sinkholes, and pavements produced when the rock is dissolved by acidic water","definitionCN":"酸性水溶蚀该岩石后形成的洞穴、落水洞与溶蚀台地景观","example":"Limestone country is full of sinkholes and dry valleys.","exampleCN":"石灰岩地区遍布落水洞与干谷。","why":"The rock's weakness is also its signature: it dissolves, so its landscape is a map of water paths.","whyCN":"这种岩石的弱点也是它的标志：它会溶解，因此其地貌就是水路的地图。"},{"no":"05","title":"Raw material for cement and lime","titleCN":"水泥与石灰的原料","definition":"the rock quarried and heated to make cement, mortar, and agricultural lime","definitionCN":"经开采与煅烧以制造水泥、灰浆与农用石灰的岩石","example":"The plant grinds limestone into raw meal for cement.","exampleCN":"工厂把石灰岩磨成水泥生料。","why":"Industry names the rock by what it yields: calcium carbonate becomes quicklime when heated.","whyCN":"工业按产出物命名岩石：碳酸钙受热即变为生石灰。"},{"no":"06","title":"Fossil-rich limestone","titleCN":"富含化石的石灰岩","definition":"limestone that preserves shells, corals, or other hard parts of marine life","definitionCN":"保存贝壳、珊瑚或其他海洋生物硬体的石灰岩","example":"The flagstones are full of fossil shells.","exampleCN":"这些铺石上满是化石贝壳。","why":"Much limestone is literally accumulated skeletons, so the rock doubles as a record of ancient seas.","whyCN":"许多石灰岩实际上就是堆积的骨骼，因此这种岩石同时是古海洋的记录。"},{"no":"07","title":"Chalk as a soft variety","titleCN":"作为软质变种的白垩","definition":"a soft, fine-grained, white variety of limestone made of microscopic shell plates","definitionCN":"由微小壳体片堆积而成、柔软细粒的白色石灰岩变种","example":"The white cliffs are chalk, a very pure limestone.","exampleCN":"白色崖壁是白垩，一种很纯的石灰岩。","why":"Chalk is limestone written in miniature: the same chemistry, built from far smaller skeletons.","whyCN":"白垩是缩小版的石灰岩：化学成分相同，只是由小得多的骨骼堆成。"},{"no":"08","title":"A soil-forming parent material","titleCN":"成土母质","definition":"limestone bedrock that weathering turns into thin, alkaline soils","definitionCN":"经风化变为薄层碱性土壤的石灰岩基岩","example":"The thin soil over limestone supports dry grassland.","exampleCN":"石灰岩上的薄土养育着干性草地。","why":"Rock becomes soil; because this rock is alkaline, its soils are basic and often thin.","whyCN":"岩石化为土壤；由于这种岩石偏碱性，其土壤呈碱性且往往很薄。"},{"no":"09","title":"Abstract: a archive of ancient life","titleCN":"抽象义：远古生命的档案","definition":"something that preserves a readable record of past conditions in layered form","definitionCN":"以层状形式保存过去状况、可供解读的记录物","example":"The reef limestone is an archive written by living things.","exampleCN":"这座礁石灰岩是一部由生物写成的档案。","why":"The metaphor uses the rock's origin: layer upon layer of shells is a record accumulated by living bodies, not by ink.","whyCN":"这一比喻利用岩石的成因：一层层贝壳是由生物体而非墨水累积成的记录。"}],"etymology":{"intro":{"en":"Limestone is an English compound of lime and stone. Its parts are native, while the geological sense is early modern. Dates are approximate.","cn":"limestone 是 lime 与 stone 的英语复合词。两部分均为本族语，地质义形成于近代早期。年代均为约数。"},"items":[{"era":"OLD ENGLISH LIM","en":"Lim meant a sticky substance, mortar, or birdlime, from Proto-Germanic limaz. The same root is behind Latin limus 'mud', which is related rather than directly ancestral.","cn":"lim 原指黏性物质、灰浆或粘鸟胶，来自原始日耳曼语 limaz。同一词根也见于拉丁语 limus「泥」，二者是旁系关系而非直接祖孙。"},{"era":"LIME FROM BURNING","en":"Heating limestone produces quicklime, so lime came to name both the product and the rock that yields it.","cn":"煅烧石灰岩可得到生石灰，因此 lime 既指产物，也指产出它的岩石。"},{"era":"LIME + STONE","en":"The compound limestone appears in Middle English for the rock, distinguishing it from lime the substance.","cn":"复合词 limestone 见于中古英语，用来指这种岩石，以区别于物质性的 lime。"},{"era":"CALCIUM CARBONATE","en":"Chemistry later identified the rock as calcium carbonate, and the adjective calcareous was borrowed from Latin calx 'lime'.","cn":"化学后来确认这种岩石是碳酸钙，形容词 calcareous 借自拉丁语 calx「石灰」。"},{"era":"KARST STUDIES","en":"Nineteenth-century study of the Kras region made limestone the type rock of solution landscapes; the term karst dates from that work.","cn":"19 世纪对喀斯特地区的研究使石灰岩成为溶蚀地貌的典型岩石，karst 一词即源于这项工作。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first citation): the earliest written use of the compound in English is not precisely dated, and the deeper origin of lim is reconstructed.","cn":"来源不确定（首见书证）：该复合词在英语中的最早书面使用没有精确年代，lim 的更深来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds rock names that are constantly mistaken for limestone; group two holds materials and products that share its chemistry.","cn":"第一组是常被误认为石灰岩的岩石名称；第二组是化学成分相关的材料与产物。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"lime","ipa":"/laɪm/","tag":"product, not rock","definition":"The burnt product calcium oxide or the sticky substance; in geology it is not the rock itself.","definitionCN":"指煅烧产物氧化钙或黏性物质；在地质语境中并不是岩石本身。"},{"word":"limestone","ipa":"/ˈlaɪmstəʊn/","tag":"the rock","definition":"The sedimentary rock; the compound is needed whenever the material rather than the product is meant.","definitionCN":"指沉积岩本身；凡指材料而非产物时须用这个复合词。"},{"word":"sandstone","ipa":"/ˈsændstəʊn/","tag":"different grains","definition":"Rock made of sand grains, usually quartz; it is clastic, not built from shells or chemical precipitate.","definitionCN":"由砂粒、通常为石英构成的岩石；属碎屑岩，不由贝壳或化学沉淀构成。"},{"word":"dolomite","ipa":"/ˈdɒləmaɪt/","tag":"magnesium cousin","definition":"A carbonate rock in which magnesium partly replaces calcium; it looks like limestone but reacts more slowly with acid.","definitionCN":"镁部分取代钙的碳酸盐岩；外观似石灰岩，但与酸反应更慢。"}]},{"heading":"NEAR MEANING","entries":[{"word":"chalk","ipa":"/tʃɔːk/","tag":"soft variety","definition":"A soft white limestone of microscopic shell plates; it is a kind of limestone, not a separate chemistry.","definitionCN":"由微小壳板构成的软白石灰岩；它是石灰岩的一种，化学成分并非另一类。"},{"word":"marble","ipa":"/ˈmɑːbl/","tag":"metamorphic form","definition":"Limestone recrystallized by heat and pressure; it is the metamorphic product, not the sediment.","definitionCN":"经热与压力重结晶的石灰岩；它是变质产物，而非沉积物。"},{"word":"calcium carbonate","ipa":"/ˈkælsiəm ˈkɑːbəneɪt/","tag":"chemical name","definition":"The compound that makes up the rock; the mineral name calcite is used for its crystalline form.","definitionCN":"构成该岩石的化合物；其结晶形态的矿物名为方解石。"},{"word":"gypsum","ipa":"/ˈdʒɪpsəm/","tag":"sulfate look-alike","definition":"Calcium sulfate, a softer mineral that also forms white beds; it is not a carbonate.","definitionCN":"硫酸钙，一种较软的矿物，也形成白色层位；它不是碳酸盐。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real rock names and real collocations, not invented rhymes.","cn":"正常联想：真实语素、真实岩石名称与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Lime + stone: burn the stone and you get lime, the oldest clue to its identity.","cn":"lime 加 stone：烧这种石头就得到石灰，这是识别它最古老的线索。"},{"en":"Limestone is mostly calcium carbonate, so acid makes it bubble.","cn":"石灰岩主要是碳酸钙，因此遇酸会起泡。"},{"en":"Its family runs limestone, lime, limy, calcareous and calcium.","cn":"同族词包括 limestone、lime、limy、calcareous 与 calcium。"},{"en":"Karst landscapes are the signature of limestone: caves, sinkholes, dry valleys.","cn":"喀斯特地貌是石灰岩的标志：洞穴、落水洞、干谷。"},{"en":"Chalk and marble are limestone's soft and hardened cousins.","cn":"白垩与大理岩是石灰岩的软、硬两位表亲。"}],"abstract":[{"en":"Picture a library whose shelves are made of old seashells.","cn":"想象一座图书馆，书架都由古老贝壳做成。"},{"en":"Picture a stone that answers acid with a fizz, like a cough.","cn":"想象一块石头遇酸以气泡作答，像一声咳嗽。"},{"en":"Picture a landscape drained by hidden pipes, all of them dissolved by rain.","cn":"想象一片由隐蔽管道排水的土地，所有管道都是雨水溶出来的。"}]},"examples":[{"en":"The cave walls are made of limestone that rainwater has slowly dissolved.","cn":"洞壁由雨水缓慢溶蚀的石灰岩构成。"},{"en":"Builders cut limestone blocks from the bed beside the river.","cn":"工匠从河边岩层中切出石灰岩块。"},{"en":"Because limestone neutralizes acid, farmers spread crushed rock on sour fields.","cn":"由于石灰岩能中和酸，农民把碎石撒在酸性田里。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「莱姆斯通」——烧一烧就变成石灰的石头 → 石灰岩","word":"limestone"},"root":"英语 lime「石灰、黏性物质」（古英语 lim，原始日耳曼语 limaz）+ stone「石头」；属英语本族复合词。化学上主要成分为碳酸钙，拉丁语 calx「石灰」给出 calcareous。","sensesIntro":{"en":"Nine senses follow one rock from its chemistry to its beds, its caves, its quarries, its fossils, its soils, and finally to its use as an image of a layered archive.","cn":"九个义项让同一种岩石从化学成分走到层位、洞穴、采石场、化石、土壤，最后成为层层档案的意象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pale layered rock with water-cut grooves, soft enough for rain to hollow it out.","cn":"核心意象：浅色层状岩石上有水溶出的沟槽，软得能被雨水掏空。"},"chain":["CARBONATE ROCK","BUILDING STONE","BED OR UNIT","DISSOLVED LANDSCAPE","RAW MATERIAL","FOSSIL ARCHIVE"],"branches":[{"senses":"S1 · S3","en":"MATERIAL AND BED: the same substance is both a mass noun and a countable layer.","cn":"材料与层位：同一物质既可作物质名词，也可作可数的一层。"},{"senses":"S2 · S5","en":"STONE AND PRODUCT: it is cut for walls and burned for cement, two uses of one chemistry.","cn":"石材与产物：既被切作墙体，也被烧作水泥，是同一化学的两种用途。"},{"senses":"S4 · S7","en":"SOFTNESS: solubility and fine shell plates make caves, pavements and chalk cliffs.","cn":"软质：可溶性与细壳板共同造出洞穴、台地与白垩崖。"},{"senses":"S6 · S9","en":"RECORD: shells become rock, and the rock becomes a readable archive.","cn":"记录：贝壳变成岩石，岩石又成为可读的档案。"},{"senses":"S8","en":"PARENT MATERIAL: weathering turns the rock into thin alkaline soil.","cn":"母质：风化把岩石变成薄层碱性土壤。"}]},"affixes":{"intro":{"en":"The compound is made of two native English nouns, but its chemistry adds a Latin adjective.","cn":"这个复合词由两个英语本族名词构成，但其化学性质带来一个拉丁语形容词。"},"latinIntro":{"en":"Latin calx 'lime' supplies calcareous and calcium; the English compound itself has no Latin source.","cn":"拉丁语 calx「石灰」提供 calcareous 与 calcium；英语复合词本身没有拉丁语源。"},"items":[{"word":"lime","structure":"Old English lim (sticky substance, mortar)","meaning":"lime; a sticky binder","meaningCN":"石灰；黏性胶结物","example":"Lime mortar holds the old bricks together.","exampleCN":"石灰砂浆把旧砖粘在一起。"},{"word":"stone","structure":"Old English stan (rock, stone)","meaning":"rock; a piece of rock","meaningCN":"岩石；石块","example":"The wall is built of local stone.","exampleCN":"这堵墙用本地石材砌成。"},{"word":"limestone","structure":"lime + stone","meaning":"the carbonate rock","meaningCN":"石灰岩","example":"The quarry yields a hard grey limestone.","exampleCN":"这座采石场出产坚硬的灰色石灰岩。"},{"word":"limy","structure":"lime + -y (full of, like)","meaning":"containing lime","meaningCN":"含石灰的","example":"The limy soil supports chalk grassland.","exampleCN":"含石灰的土壤养育白垩草地。"},{"word":"calcareous","structure":"Latin calcarius (of lime) + -eous","meaning":"made of or containing calcium carbonate","meaningCN":"钙质的；含碳酸钙的","example":"Calcareous mud becomes limestone.","exampleCN":"钙质泥会变成石灰岩。"},{"word":"calcium","structure":"Latin calx (lime) + -ium (element suffix)","meaning":"the metallic element in lime","meaningCN":"石灰中的金属元素钙","example":"Calcium carbonate is the main mineral.","exampleCN":"碳酸钙是主要矿物。"},{"word":"chalk","structure":"Old English cealc, from Latin calx","meaning":"a soft white limestone","meaningCN":"白垩；软白石灰岩","example":"Chalk is a pure form of limestone.","exampleCN":"白垩是石灰岩的一种纯净形态。"},{"word":"marble","structure":"Greek marmaros (shining stone), through Latin","meaning":"metamorphosed limestone","meaningCN":"变质石灰岩；大理岩","example":"Marble is limestone recrystallized by heat.","exampleCN":"大理岩是受热重结晶的石灰岩。"},{"word":"karst","structure":"German Karst, from the Kras plateau","meaning":"solution landscape on limestone","meaningCN":"石灰岩溶蚀地貌","example":"Karst forms where limestone dissolves.","exampleCN":"喀斯特在石灰岩溶解处形成。"}],"latinEntries":[{"word":"calx","structure":"calx, calcis (f., third declension)","meaning":"lime, limestone","meaningCN":"石灰；石灰岩"},{"word":"calcarius","structure":"calcarius, calcaria, calcarium (adj.)","meaning":"of lime","meaningCN":"石灰的"},{"word":"calcium","structure":"Modern Latin calcium, from calx","meaning":"the element calcium","meaningCN":"元素钙"}]}},{"word":"sandstone","ipa_uk":"/ˈsændstəʊn/","ipa_us":"/ˈsændstoʊn/","definition_zh":"砂岩；由砂粒胶结而成的碎屑沉积岩","definition_en":"a clastic sedimentary rock made of sand grains cemented together, usually mostly quartz","core_image":"峡谷里被风蚀成弧面的暖红色岩壁，表面能看出细砂粒","scene":"峡谷两侧的岩壁呈暖红色，表面还能看出细砂粒的颗粒感： The canyon walls are sandstone laid down as dunes long ago.","sceneCN":"这里 sandstone 指「由砂粒胶结成的碎屑沉积岩」（第 1 个义项：砂粒经胶结形成的沉积岩）；句意为峡谷岩壁是远古沙丘堆积形成的砂岩。","pos":[{"tag":"n.","zh":"砂岩（物质名词；指多种砂岩时复数为 sandstones）"}],"collocations":[{"phrase":"red sandstone","zh":"红色砂岩"},{"phrase":"sandstone cliff","zh":"砂岩崖壁"},{"phrase":"sandstone quarry","zh":"砂岩采石场"},{"phrase":"sandstone reservoir","zh":"砂岩储层"},{"phrase":"layers of sandstone","zh":"砂岩层"},{"phrase":"carved sandstone","zh":"雕凿过的砂岩"}],"forms":[{"label":"复数（指多种砂岩）","form":"sandstones"},{"label":"核心名词（砂）","form":"sand"},{"label":"核心名词（石头）","form":"stone"},{"label":"形容词（砂质的）","form":"arenaceous"},{"label":"相关岩石（粉砂岩）","form":"siltstone"}],"derivatives":[{"word":"sand","pos":"n./v.","zh":"沙；用砂纸打磨"},{"word":"sandy","pos":"adj.","zh":"含沙的；沙色的"},{"word":"siltstone","pos":"n.","zh":"粉砂岩"},{"word":"arenaceous","pos":"adj.","zh":"砂质的"},{"word":"sandstone quarry","pos":"n.","zh":"砂岩采石场"}],"senses":[{"no":"01","title":"Clastic rock made of cemented sand","titleCN":"砂粒胶结成的碎屑岩","definition":"a sedimentary rock formed when sand grains are compacted and cemented by minerals","definitionCN":"砂粒经压实并被矿物胶结后形成的沉积岩","example":"The canyon walls are sandstone laid down as dunes long ago.","exampleCN":"峡谷岩壁是远古沙丘堆积形成的砂岩。","why":"Sand plus stone says exactly how it is made: loose grains first, stone later.","whyCN":"sand 加 stone 正好说明成因：先有松散砂粒，后有石头。"},{"no":"02","title":"A building and carving stone","titleCN":"建筑与雕刻用石材","definition":"the rock cut into blocks or carved because it is soft enough to work","definitionCN":"因足够柔软而可切块或雕凿的该种岩石","example":"The temple was carved directly into sandstone.","exampleCN":"这座庙宇直接在砂岩中凿成。","why":"Sandstone is soft when freshly cut and hardens with exposure, a combination that invites carving.","whyCN":"砂岩新切时柔软，暴露后变硬，这一组合正适合雕刻。"},{"no":"03","title":"A bed within a sequence","titleCN":"层序中的一层砂岩","definition":"one distinct layer or member of sandstone among other sedimentary layers","definitionCN":"沉积层序中一层或一个明确的砂岩成员","example":"A white sandstone bed lies above the red shale.","exampleCN":"一层白色砂岩位于红色页岩之上。","why":"Count usage turns the material into one stratigraphic item among neighbours.","whyCN":"可数用法把材料变成相邻层位中的一个地层项目。"},{"no":"04","title":"A reservoir rock for water or oil","titleCN":"水或石油的储层","definition":"porous sandstone that holds and transmits groundwater, oil, or gas","definitionCN":"储存并输送地下水、石油或天然气的多孔砂岩","example":"The well draws water from a deep sandstone.","exampleCN":"这口井从深层砂岩取水。","why":"Grains leave pore space, so sandstone is where fluids live underground; industry calls it a reservoir.","whyCN":"砂粒之间留下孔隙，因此砂岩是地下流体所在之处，工业上称之为储层。"},{"no":"05","title":"An aquifer and filter","titleCN":"含水层与过滤介质","definition":"a sandstone body that stores and slowly filters groundwater","definitionCN":"储存并缓慢过滤地下水的砂岩体","example":"The town depends on a sandstone aquifer.","exampleCN":"这个镇依赖一处砂岩含水层。","why":"The same pores that hold water also slow it, so the rock doubles as a natural filter.","whyCN":"储水的孔隙也会拖慢水流，因此这种岩石同时充当天然滤器。"},{"no":"06","title":"A record of ancient dunes or rivers","titleCN":"古沙丘或古河流的记录","definition":"sandstone whose grain size, sorting, and cross-bedding reveal the environment that deposited it","definitionCN":"其粒度、分选与交错层理能揭示沉积环境的砂岩","example":"Slanted layers in the sandstone record an old desert dune.","exampleCN":"砂岩中的倾斜层理记录了一座古沙漠沙丘。","why":"Each transport agent sorts sand differently, so the rock preserves a fingerprint of wind or water.","whyCN":"不同搬运介质对砂的分选方式不同，因此岩石保存了风或水的指纹。"},{"no":"07","title":"Coloured beds and red beds","titleCN":"彩色层与红层","definition":"sandstone coloured by iron oxides, ranging from white and yellow to deep red","definitionCN":"由铁氧化物染色的砂岩，从白、黄到深红不等","example":"The red sandstone glows at sunset.","exampleCN":"红色砂岩在日落时泛光。","why":"Iron minerals oxidize differently under different conditions, so colour is a clue to ancient chemistry.","whyCN":"铁矿物在不同条件下氧化程度不同，因此颜色是古化学环境的线索。"},{"no":"08","title":"A weak rock that erodes into arches","titleCN":"易蚀成拱的软弱岩体","definition":"sandstone that weathers into arches, alcoves, and hoodoos because cementation is uneven","definitionCN":"因胶结不均而风化成拱门、壁龛与石柱的砂岩","example":"The sandstone arch collapsed after a wet winter.","exampleCN":"这座砂岩拱门在潮湿的冬季后坍塌。","why":"Where cement is weak, grains wash away faster, and the difference carves the shape.","whyCN":"胶结较弱处砂粒流失更快，差异本身就在雕刻形状。"},{"no":"09","title":"Abstract: many small units loosely joined","titleCN":"抽象义：松散联合的许多小单元","definition":"a whole held together by many small parts rather than one solid mass","definitionCN":"由许多小部分而非单一整块维持在一起的整体","example":"The team was sandstone, not granite: many grains, lightly cemented.","exampleCN":"这个团队像砂岩而非花岗岩：颗粒众多，胶结松散。","why":"The metaphor contrasts grain size and cement: cohesion can come from many small members as well as from one mass.","whyCN":"这一比喻对比粒径与胶结：凝聚力既可来自单一整块，也可来自许多小成员。"}],"etymology":{"intro":{"en":"Sandstone is a native English compound. Sand has a long Germanic history, and stone is one of the oldest English words. Dates are approximate.","cn":"sandstone 是英语本族复合词。sand 有悠久的日耳曼语历史，stone 是英语最古老的词之一。年代均为约数。"},"items":[{"era":"OLD ENGLISH SAND","en":"Sand comes from Old English sand, from Proto-Germanic sandam, from a Proto-Indo-European form usually reconstructed as samh2dhos 'that which is ground'.","cn":"sand 来自古英语 sand，源于原始日耳曼语 sandam，其原始印欧语形式通常重构为 samh2dhos，意为「被磨碎之物」。"},{"era":"OLD ENGLISH STAN","en":"Stone is one of the oldest recorded English words, from Proto-Germanic stainaz; its further origin is not established.","cn":"stone 是英语最早有记录的词之一，来自原始日耳曼语 stainaz；其更深来源尚未确定。"},{"era":"THE COMPOUND","en":"Sandstone names the rock by its visible grains, a compound pattern shared with limestone and mudstone.","cn":"sandstone 按肉眼可见的颗粒给岩石命名，这种复合方式也见于 limestone 与 mudstone。"},{"era":"GEOLOGICAL DEFINITION","en":"Nineteenth-century geology fixed sandstone as a clastic rock with grains between about 0.06 and 2 millimetres.","cn":"19 世纪地质学把砂岩定为碎屑岩，粒径约在 0.06 至 2 毫米之间。"},{"era":"ECONOMIC SENSE","en":"The reservoir sense grew with the oil industry in the twentieth century; its first use is not precisely dated.","cn":"储层义随 20 世纪石油工业而扩展，其最早使用年代没有精确记载。"}]},"similar":{"note":{"en":"Group one holds clastic rock names that differ mainly by grain size; group two holds rocks and materials often mistaken for sandstone.","cn":"第一组是主要按粒径区分的碎屑岩名称；第二组是常被误认为砂岩的岩石与材料。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"siltstone","ipa":"/ˈsɪltstəʊn/","tag":"finer grains","definition":"A clastic rock of silt grains, finer than sand but coarser than clay; it feels smoother than sandstone.","definitionCN":"由粉砂颗粒构成的碎屑岩，比砂细、比黏土粗；手感比砂岩光滑。"},{"word":"mudstone","ipa":"/ˈmʌdstəʊn/","tag":"mud, not sand","definition":"A fine-grained rock of clay and silt; it lacks the visible sand grains that define sandstone.","definitionCN":"由黏土与粉砂构成的细粒岩石，缺少定义砂岩所需的可见砂粒。"},{"word":"quartzite","ipa":"/ˈkwɔːtsaɪt/","tag":"metamorphic","definition":"Sandstone recrystallized by heat and pressure; the grains fuse, so it breaks across them rather than between them.","definitionCN":"受热与压力重结晶的砂岩；颗粒融合，因此断裂穿过颗粒而非沿颗粒之间。"},{"word":"gritstone","ipa":"/ˈɡrɪtstəʊn/","tag":"coarse sandstone","definition":"A coarse, sharp-grained sandstone, traditionally used for millstones; it is sandstone with a grain-size label.","definitionCN":"粗粒、棱角明显的砂岩，传统上用于磨石；它是带粒径标签的砂岩。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sand","ipa":"/sænd/","tag":"loose material","definition":"Loose grains before they are cemented; sandstone is sand that has become rock.","definitionCN":"胶结之前的松散颗粒；砂岩就是变成岩石的砂。"},{"word":"arenite","ipa":"/ˈærənaɪt/","tag":"technical synonym","definition":"A clean sandstone with little fine matrix; the term is used in petrography rather than everyday speech.","definitionCN":"基质很少的洁净砂岩；该词用于岩相学而非日常表达。"},{"word":"limestone","ipa":"/ˈlaɪmstəʊn/","tag":"carbonate rock","definition":"A rock of calcium carbonate rather than sand grains; it reacts with acid, which sandstone does not.","definitionCN":"由碳酸钙而非砂粒构成的岩石；遇酸反应，而砂岩不反应。"},{"word":"conglomerate","ipa":"/kənˈɡlɒmərət/","tag":"rounded pebbles","definition":"A clastic rock of rounded gravel, coarser than sandstone, cemented in a matrix.","definitionCN":"由磨圆砾石构成的碎屑岩，比砂岩粗，胶结在基质中。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real rock names and real collocations, not invented rhymes.","cn":"正常联想：真实语素、真实岩石名称与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Sand + stone: the name records the recipe, grains first and cement later.","cn":"sand 加 stone：名字记录了配方，先有颗粒，后有胶结。"},{"en":"Grain size separates the family: conglomerate, sandstone, siltstone, mudstone.","cn":"粒径区分这一族：砾岩、砂岩、粉砂岩、泥岩。"},{"en":"Sandstone is porous, so it holds water and oil.","cn":"砂岩多孔，因此能储水与储油。"},{"en":"Red beds are sandstone coloured by iron oxide.","cn":"红层是被铁氧化物染色的砂岩。"},{"en":"The same rock carved the temples of Petra and the arches of Utah.","cn":"同一类岩石凿出了佩特拉神庙与犹他拱门。"}],"abstract":[{"en":"Picture a wall made of a million grains, each too small to hold the wall alone.","cn":"想象一堵由百万颗沙粒砌成的墙，每颗都小得无法独自支撑。"},{"en":"Picture a stone that crumbles where its glue is thin.","cn":"想象一块石头，胶薄之处便崩落。"},{"en":"Picture a group held together by many weak ties rather than one strong beam.","cn":"想象一个群体由许多弱联系而非一根强梁维系。"}]},"examples":[{"en":"The canyon walls are sandstone laid down as dunes long ago.","cn":"峡谷岩壁是远古沙丘堆积形成的砂岩。"},{"en":"Workers quarried sandstone for the steps of the old library.","cn":"工人开采砂岩，用于旧图书馆的台阶。"},{"en":"Water moves slowly through the sandstone and arrives already filtered.","cn":"水缓慢穿过砂岩，到达时已被过滤。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「三德斯通」——沙子被压成石头 → 砂岩","word":"sandstone"},"root":"英语 sand「沙」来自古英语 sand、原始日耳曼语 sandam，其原始印欧语形式通常重构为 samh2dhos「被磨碎之物」+ stone「石头」来自古英语 stan、原始日耳曼语 stainaz。属英语本族复合词。","sensesIntro":{"en":"Nine senses read the rock as material, bed, building stone, reservoir, filter, environmental record, coloured beds, eroding mass, and finally as an image of loose cohesion.","cn":"九个义项把这种岩石依次读作材料、层位、建筑石材、储层、过滤器、环境记录、彩色层、易蚀岩体，最后读作松散凝聚的意象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a warm red cliff whose face still shows the individual sand grains.","cn":"核心意象：暖红色崖壁，表面仍能看出一颗颗砂粒。"},"chain":["CEMENTED GRAINS","WORKABLE STONE","LAYERED BED","POROUS RESERVOIR","ANCIENT ENVIRONMENT","LOOSE COHESION"],"branches":[{"senses":"S1 · S3","en":"MATERIAL AND LAYER: grains make the substance, and one bed makes a countable unit.","cn":"材料与层位：颗粒构成物质，一层则构成可数单位。"},{"senses":"S2 · S8","en":"SOFT AND WEAK: easy to carve when fresh, easy to erode where cement is thin.","cn":"软与弱：新鲜时易雕，胶结薄处易蚀。"},{"senses":"S4 · S5","en":"PORES: the gaps between grains store water and oil and slow their flow.","cn":"孔隙：颗粒间的空隙储存水油，并拖慢其流动。"},{"senses":"S6 · S7","en":"FINGERPRINT: grain sorting and iron colour record how and where the sand travelled.","cn":"指纹：分选与铁染记录砂的搬运方式与地点。"},{"senses":"S9","en":"METAPHOR: many small grains can hold a whole together, but only as long as the cement lasts.","cn":"比喻：许多小颗粒能维系整体，但只在胶结尚存时成立。"}]},"affixes":{"intro":{"en":"The compound is transparent, and the technical vocabulary adds a Latin adjective for sandy rock.","cn":"这个复合词是透明的，技术词汇另加一个表示砂质岩石的拉丁语形容词。"},"latinIntro":{"en":"Latin arena 'sand' supplies arenaceous and arenite; the compound sandstone itself is native English.","cn":"拉丁语 arena「沙」提供 arenaceous 与 arenite；复合词 sandstone 本身是英语本族语。"},"items":[{"word":"sand","structure":"Old English sand (sand, gravel)","meaning":"loose granular material","meaningCN":"松散的颗粒材料；沙","example":"The sand was sorted by the wind.","exampleCN":"沙被风分选。"},{"word":"stone","structure":"Old English stan (stone, rock)","meaning":"hard consolidated rock","meaningCN":"坚硬的固结岩石","example":"The stone splits along the bedding.","exampleCN":"石头沿层理裂开。"},{"word":"sandstone","structure":"sand + stone","meaning":"cemented sand rock","meaningCN":"砂粒胶结成的岩石","example":"The sandstone is soft enough to carve.","exampleCN":"这种砂岩软得可以雕凿。"},{"word":"sandy","structure":"sand + -y (full of, like)","meaning":"containing sand","meaningCN":"含沙的；沙质的","example":"The sandy layer grades into silt.","exampleCN":"含沙层逐渐过渡为粉砂。"},{"word":"arenaceous","structure":"Latin arenaceus (sandy) + -ous","meaning":"sandy; of sand grains","meaningCN":"砂质的；由砂粒构成的","example":"Arenaceous rocks include sandstone and gritstone.","exampleCN":"砂质岩包括砂岩与粗砂岩。"},{"word":"arenite","structure":"Latin arena (sand) + -ite (rock)","meaning":"a clean sandstone","meaningCN":"洁净砂岩","example":"The arenite contains little clay matrix.","exampleCN":"这块洁净砂岩含黏土基质很少。"},{"word":"siltstone","structure":"silt + stone","meaning":"rock of silt grains","meaningCN":"粉砂岩","example":"Siltstone feels smoother than sandstone.","exampleCN":"粉砂岩手感比砂岩更光滑。"},{"word":"quartzite","structure":"quartz + -ite (rock)","meaning":"metamorphosed sandstone","meaningCN":"变质砂岩；石英岩","example":"Quartzite breaks across the old grains.","exampleCN":"石英岩断裂穿过旧颗粒。"},{"word":"gritstone","structure":"grit + stone","meaning":"coarse sandstone","meaningCN":"粗砂岩","example":"Gritstone was used for millstones.","exampleCN":"粗砂岩曾被用作磨石。"}],"latinEntries":[{"word":"arena","structure":"Latin arena (f., first declension)","meaning":"sand, sandy place","meaningCN":"沙；沙地"},{"word":"arenaceus","structure":"arenaceus, arenacea, arenaceum (adj.)","meaning":"sandy, of sand","meaningCN":"砂质的；含沙的"},{"word":"sabulum","structure":"Latin sabulum (n., second declension)","meaning":"coarse sand, gravel","meaningCN":"粗砂；砾石"}]}},{"word":"granite","ipa_uk":"/ˈɡrænɪt/","ipa_us":"/ˈɡrænɪt/","definition_zh":"花岗岩；由石英、长石与云母等矿物结晶而成的粗粒酸性侵入岩","definition_en":"a coarse-grained intrusive igneous rock made mainly of quartz, feldspar, and mica","core_image":"海边灰白色崖壁上散布着黑色与白色矿物颗粒","scene":"海边悬崖被浪切成陡壁，灰白色岩石里闪着黑色与白色的颗粒： The sea cliff is solid granite speckled with dark and pale crystals.","sceneCN":"这里 granite 指「粗粒的酸性侵入岩」（第 1 个义项：由石英、长石与云母结晶成的深成岩）；句意为海边崖壁是坚实的花岗岩，上面布满深浅色晶体颗粒。","pos":[{"tag":"n.","zh":"花岗岩（物质名词；指多种花岗岩时复数为 granites）"}],"collocations":[{"phrase":"grey granite","zh":"灰色花岗岩"},{"phrase":"granite cliff","zh":"花岗岩崖壁"},{"phrase":"granite quarry","zh":"花岗岩采石场"},{"phrase":"polished granite","zh":"抛光花岗岩"},{"phrase":"granite outcrop","zh":"花岗岩露头"},{"phrase":"a block of granite","zh":"一块花岗岩"}],"forms":[{"label":"复数（指多种花岗岩）","form":"granites"},{"label":"形容词（花岗质的）","form":"granitic"},{"label":"核心动词（成粒）","form":"granulate"},{"label":"核心名词（颗粒）","form":"grain"},{"label":"相关岩石（闪长岩）","form":"diorite"}],"derivatives":[{"word":"granitic","pos":"adj.","zh":"花岗质的；花岗岩的"},{"word":"graniteware","pos":"n.","zh":"花岗岩纹搪瓷器具"},{"word":"granulate","pos":"v.","zh":"使成粒状"},{"word":"granular","pos":"adj.","zh":"颗粒状的"},{"word":"grain","pos":"n.","zh":"颗粒；谷粒"}],"senses":[{"no":"01","title":"Coarse-grained intrusive igneous rock","titleCN":"粗粒侵入岩","definition":"an igneous rock that cooled slowly deep underground, allowing large crystals of quartz, feldspar, and mica to grow","definitionCN":"在地下深处缓慢冷却、因而长出大颗石英、长石与云母晶体的火成岩","example":"The sea cliff is solid granite speckled with dark and pale crystals.","exampleCN":"海边崖壁是坚实的 granite，布满深浅色晶体颗粒。","why":"Slow cooling gives crystals time to grow, and the visible speckle is the signature of that slow history.","whyCN":"缓慢冷却给晶体生长的时间，肉眼可见的斑点正是这段缓慢历史的标志。"},{"no":"02","title":"The stone as a building material","titleCN":"作为建筑石材","definition":"the rock cut and polished for countertops, paving, walls, and monuments","definitionCN":"被切割抛光用于台面、铺地、墙体与纪念碑的该种岩石","example":"The kitchen counter is polished granite.","exampleCN":"厨房台面是抛光花岗岩。","why":"Hard, acid-resistant, and polishable, granite moved from cliffs into kitchens and bank lobbies.","whyCN":"坚硬、耐酸且可抛光，使花岗岩从崖壁走进厨房与银行大厅。"},{"no":"03","title":"A large intrusive body","titleCN":"大型侵入体","definition":"a batholith or stock of granite covering many square kilometres underground","definitionCN":"覆盖地下许多平方公里的大型岩基或岩株","example":"The mountain range sits on a granite batholith.","exampleCN":"这条山脉坐落在一处花岗岩岩基上。","why":"At depth, many granite intrusions merge into one enormous body that only erosion later reveals.","whyCN":"在地下深处，许多花岗岩侵入体合并成一个巨大岩体，只有侵蚀才后来将其揭示。"},{"no":"04","title":"A tor or weathered upland","titleCN":"风化成形的高地岩丘","definition":"granite that weathering has shaped into tors, rounded boulders, and bare uplands","definitionCN":"被风化塑造成岩丘、浑圆巨砾与裸露高地的花岗岩","example":"Granite tors crown the moor.","exampleCN":"花岗岩岩丘耸立在荒原上。","why":"Granite fractures along joints and decays into rounded blocks, leaving towers where the rock was jointed least.","whyCN":"花岗岩沿节理裂开并风化成浑圆石块，在节理最少处留下塔状岩丘。"},{"no":"05","title":"Monument and memorial stone","titleCN":"纪念碑用石","definition":"granite valued for monuments because it resists weather and takes a sharp edge","definitionCN":"因耐风化且能磨出锋利边缘而用于纪念碑的花岗岩","example":"Names were cut deep into the granite obelisk.","exampleCN":"名字被深深刻入花岗岩方尖碑。","why":"A memorial must outlast the memory it serves, and granite is chosen for exactly that durability.","whyCN":"纪念碑必须比它所承载的记忆更长久，花岗岩正因这种耐久性被选中。"},{"no":"06","title":"Continental crust material","titleCN":"大陆地壳的组成物质","definition":"the granitic rock that makes up much of the continental crust, lighter than oceanic basalt","definitionCN":"构成大陆地壳大部分的花岗质岩石，比大洋玄武岩轻","example":"Granite floats the continents higher than the ocean floor.","exampleCN":"花岗岩使大陆浮得比洋底更高。","why":"Because it is less dense than basalt, continental crust rises and stands above the oceans.","whyCN":"由于密度低于玄武岩，大陆地壳抬升并高出海面。"},{"no":"07","title":"A dimension stone trade name","titleCN":"石材商品名","definition":"any hard speckled stone sold under the commercial label granite, even when it is not true granite","definitionCN":"商业上以花岗岩为标签销售的硬质斑点石材，即使并非真正花岗岩","example":"The showroom sells black granite that is really gabbro.","exampleCN":"展厅卖的黑色花岗岩其实是辉长岩。","why":"Trade names follow appearance and durability rather than petrology, so the market's granite is wider than the geologist's.","whyCN":"商品名依据外观与耐久性而非岩石学，因此市场上的花岗岩比地质学家的定义更宽。"},{"no":"08","title":"Abstract: unyielding hardness","titleCN":"抽象义：坚硬不屈的性质","definition":"a quality of stubborn strength and resistance to change","definitionCN":"固执坚强、抗拒改变的性质","example":"She met the criticism with granite calm.","exampleCN":"她以花岗岩般的镇定面对批评。","why":"The metaphor takes the rock's most obvious property, hardness, and applies it to character.","whyCN":"这一比喻取岩石最明显的属性——坚硬，并将其用于性格。"}],"etymology":{"intro":{"en":"Granite is an Italian coinage from the Latin word for grain, named for its visible crystals. The origin of the base word is well attested. Dates are approximate.","cn":"granite 是意大利语造词，来自拉丁语「谷粒」，因肉眼可见的晶体而得名。词根书证充分。年代均为约数。"},"items":[{"era":"LATIN GRANUM","en":"Latin granum meant 'grain, seed', from Proto-Indo-European gerh2- 'grain'. The root is widely attested in grain, granary, and granular.","cn":"拉丁语 granum 意为「谷粒、种子」，来自原始印欧语 gerh2-「谷粒」。该词根广见于 grain、granary 与 granular。"},{"era":"ITALIAN GRANITO","en":"Italian stonecutters called the speckled rock granito, literally 'grained stone', from granire 'to produce grains'.","cn":"意大利石匠把这种带斑点的岩石称作 granito，字面是「有颗粒的石头」，来自 granire「使成粒」。"},{"era":"ENGLISH BORROWING","en":"English adopted granite in the eighteenth century as the geological classification of rocks developed.","cn":"随着岩石地质分类的发展，英语在 18 世纪借入 granite。"},{"era":"PETROLOGICAL DEFINITION","en":"Later petrology narrowed granite to a specific plutonic rock of quartz, alkali feldspar, and mica, excluding similar-looking stones.","cn":"后来的岩石学把 granite 收窄为一种由石英、碱性长石与云母组成的具体深成岩，排除外观相似的石材。"},{"era":"COMMERCIAL SENSE","en":"The building trade kept the older, looser sense, so commercial granite includes rocks that petrology would call something else. The exact date of this split is uncertain.","cn":"建筑行业保留了更早、更宽松的含义，因此商业花岗岩包括岩石学会另作定名的石材。这一分野的确切年代不确定。"}]},"similar":{"note":{"en":"Group one holds igneous rock names that are easily confused with granite; group two holds stones that look similar in use.","cn":"第一组是易与花岗岩混淆的火成岩名称；第二组是用途上外观相近的石材。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"granitic","ipa":"/ɡræˈnɪtɪk/","tag":"adjective","definition":"The adjective meaning 'of granite'; it describes the rock rather than naming it.","definitionCN":"意为「花岗岩的」的形容词；它描述该岩石，而不是命名它。"},{"word":"granulate","ipa":"/ˈɡrænjuleɪt/","tag":"verb, same root","definition":"To make into grains; it shares the Latin grain root but has nothing to do with igneous rock.","definitionCN":"使成颗粒；与花岗岩共享拉丁语「谷粒」词根，但与火成岩无关。"},{"word":"gabbro","ipa":"/ˈɡæbrəʊ/","tag":"dark cousin","definition":"A coarse-grained intrusive rock rich in dark minerals; commercial 'black granite' is often gabbro.","definitionCN":"富含暗色矿物的粗粒侵入岩；商业上的「黑色花岗岩」常是辉长岩。"},{"word":"diorite","ipa":"/daɪˈɒraɪt/","tag":"intermediate","definition":"An intrusive rock between granite and gabbro in composition, with little quartz.","definitionCN":"成分介于花岗岩与辉长岩之间的侵入岩，石英很少。"}]},{"heading":"NEAR MEANING","entries":[{"word":"marble","ipa":"/ˈmɑːbl/","tag":"metamorphic stone","definition":"Recrystallized limestone used for carving and polish; it is softer and reacts with acid.","definitionCN":"重结晶的石灰岩，用于雕刻与抛光；它更软且遇酸反应。"},{"word":"quartzite","ipa":"/ˈkwɔːtsaɪt/","tag":"metamorphic look-alike","definition":"Metamorphosed sandstone, hard and granular but without feldspar's cleavage faces.","definitionCN":"变质的砂岩，坚硬且具颗粒感，但没有长石的解理面。"},{"word":"basalt","ipa":"/ˈbæsɔːlt/","tag":"dark volcanic","definition":"A fine-grained volcanic rock, denser and darker than granite, forming the ocean floor.","definitionCN":"细粒火山岩，比花岗岩更致密更深色，构成洋底。"},{"word":"gneiss","ipa":"/ɡnaɪs/","tag":"banded metamorphic","definition":"A high-grade metamorphic rock with light and dark bands, often derived from granite.","definitionCN":"具深浅条带的高级变质岩，常由花岗岩变质而来。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin roots, real rock names and real collocations, not invented rhymes.","cn":"正常联想：真实拉丁词根、真实岩石名称与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Granite is named for its grains: granum is Latin for grain.","cn":"花岗岩因颗粒得名：granum 是拉丁语「谷粒」。"},{"en":"Visible crystals mean slow cooling deep underground.","cn":"可见晶体意味着在地下深处缓慢冷却。"},{"en":"Its family runs granite, granitic, granular, granulate, grain.","cn":"同族词包括 granite、granitic、granular、granulate 与 grain。"},{"en":"Granite is continental; basalt is oceanic. Density explains the difference.","cn":"花岗岩属大陆，玄武岩属大洋；密度解释了这一差别。"},{"en":"Commercial granite is broader than geological granite.","cn":"商业花岗岩比地质学定义的花岗岩更宽泛。"}],"abstract":[{"en":"Picture a stone made of many tiny mirrors, each catching light at a different angle.","cn":"想象一块由许多小镜子组成的石头，每面镜子以不同角度反光。"},{"en":"Picture a cliff that refuses to soften even after a thousand winters.","cn":"想象一面崖壁，历经千个冬天仍不肯变软。"},{"en":"Picture a person whose calm looks carved rather than practised.","cn":"想象一个人的镇定像是被凿出来的，而不是练出来的。"}]},"examples":[{"en":"The sea cliff is solid granite speckled with dark and pale crystals.","cn":"海边崖壁是坚实的花岗岩岩体，布满深浅色晶体颗粒。"},{"en":"The counter is polished granite, cold even in summer.","cn":"台面是抛光花岗岩，夏天摸着也是凉的。"},{"en":"Weathering splits granite into rounded blocks that pile up as tors.","cn":"风化把花岗岩裂成浑圆石块，堆成岩丘。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「格拉尼特」——布满彩色颗粒的硬石头 → 花岗岩","word":"granite"},"root":"意大利语 granito「有颗粒的石头」，源自 granire「使成粒」与 grano「谷粒」，再上溯拉丁语 granum「谷粒」，原始印欧语词根 gerh2-「谷粒」。","sensesIntro":{"en":"Eight senses run from the rock's cooling history to its uses, its landforms, its crustal role, its trade name, and finally to hardness as a human image.","cn":"八个义项从冷却历史走到用途、地貌、地壳角色、商品名，最后落到作为人性意象的坚硬。"},"semanticMap":{"core":{"en":"CORE IMAGE: a grey cliff surface speckled with black and white crystals, each large enough to see.","cn":"核心意象：布满黑白晶体的灰色崖面，每颗晶体都大到肉眼可见。"},"chain":["SLOW CRYSTALS","HARD STONE","DEEP BODY","WEATHERED TOR","CONTINENTAL CRUST","HARDNESS IMAGE"],"branches":[{"senses":"S1 · S3","en":"CRYSTALS AND BODY: visible grains are the small signature of a very large slow-cooled mass.","cn":"晶体与岩体：可见颗粒是巨大慢冷岩体的小小标志。"},{"senses":"S2 · S5","en":"DURABLE USE: hardness and polish make it a kitchen surface and a memorial stone.","cn":"耐久用途：硬度与可抛光使它成为台面与纪念碑。"},{"senses":"S4","en":"LANDSCAPE: jointing and weathering turn the mass into tors and rounded boulders.","cn":"地貌：节理与风化把岩体变成岩丘与浑圆巨砾。"},{"senses":"S6","en":"CRUST: low density keeps the continents standing above the ocean floor.","cn":"地壳：低密度让大陆高出洋底。"},{"senses":"S7 · S8","en":"NAME AND METAPHOR: the market stretches the word, and the language borrows its hardness.","cn":"名称与比喻：市场扩大了词义，语言则借用了它的坚硬。"}]},"affixes":{"intro":{"en":"Granite's family is built on the Latin grain root, which is unusually productive in English.","cn":"花岗岩的词族建立在拉丁语「谷粒」词根上，这一词根在英语中格外多产。"},"latinIntro":{"en":"Latin granum and the Italian derivative granito stand behind granite; granum also gives grain, granary, and granular.","cn":"拉丁语 granum 与意大利语派生词 granito 支撑 granite；granum 还给出 grain、granary 与 granular。"},"items":[{"word":"granum","structure":"Latin granum (n., second declension)","meaning":"grain, seed","meaningCN":"谷粒；种子","example":"Granum is the source of several English grain words.","exampleCN":"granum 是若干英语「颗粒」词的来源。"},{"word":"granito","structure":"Italian granito (grained stone)","meaning":"speckled crystalline rock","meaningCN":"带斑点的结晶岩石","example":"Italian masons named the rock granito.","exampleCN":"意大利石匠把这种岩石称作 granito。"},{"word":"granite","structure":"granito, from granire (to grain)","meaning":"coarse-grained igneous rock","meaningCN":"粗粒火成岩；花岗岩","example":"Granite cools slowly and grows large crystals.","exampleCN":"花岗岩缓慢冷却，长出大晶体。"},{"word":"granitic","structure":"granite + -ic (relating to)","meaning":"of granite","meaningCN":"花岗岩的；花岗质的","example":"The granitic intrusion extends for many kilometres.","exampleCN":"这处花岗质侵入体延伸许多公里。"},{"word":"granular","structure":"Latin granulum (small grain) + -ar","meaning":"made of grains","meaningCN":"颗粒状的","example":"Granular texture is typical of slow cooling.","exampleCN":"颗粒状结构是缓慢冷却的典型特征。"},{"word":"granulate","structure":"Latin granulum + -ate (to make)","meaning":"to form into grains","meaningCN":"使成颗粒","example":"The machine granulates the slag.","exampleCN":"机器把矿渣造粒。"},{"word":"grain","structure":"Latin granum through Old French","meaning":"a seed or small particle","meaningCN":"谷粒；小颗粒","example":"The rock's grain size is easy to see.","exampleCN":"这块岩石的粒径很容易看清。"},{"word":"granary","structure":"Latin granarium (storehouse for grain)","meaning":"a storehouse for grain","meaningCN":"谷仓","example":"Granary and granite share the same Latin root.","exampleCN":"granary 与 granite 共享同一拉丁词根。"},{"word":"gneiss","structure":"German Gneis, probably from a mining term","meaning":"banded metamorphic rock","meaningCN":"片麻岩","example":"Gneiss often forms from granite under pressure.","exampleCN":"片麻岩常由花岗岩在压力下形成。"}],"latinEntries":[{"word":"granum","structure":"granum, grani (n., second declension)","meaning":"grain, seed","meaningCN":"谷粒；种子"},{"word":"granulum","structure":"granulum, granuli (n., second declension)","meaning":"a small grain","meaningCN":"小颗粒"},{"word":"granarium","structure":"granarium, granarii (n., second declension)","meaning":"granary","meaningCN":"谷仓"}]}},{"word":"basalt","ipa_uk":"/ˈbæsɔːlt/","ipa_us":"/bəˈsɔːlt/","definition_zh":"玄武岩；深色细粒的基性火山岩","definition_en":"a dark, fine-grained volcanic rock rich in iron and magnesium, forming much of the ocean floor","core_image":"火山口旁一排黑色六棱石柱并肩而立","scene":"火山口附近的黑色岩壁呈柱状节理，像一排排石柱并立： The cliff was built of basalt that cooled into tall columns.","sceneCN":"这里 basalt 指「深色细粒的基性火山岩」（第 1 个义项：富铁镁、快速冷却的火山岩）；句意为这面崖壁由冷却成高柱的玄武岩构成。","pos":[{"tag":"n.","zh":"玄武岩（物质名词；指多种玄武岩时复数为 basalts）"}],"collocations":[{"phrase":"black basalt","zh":"黑色玄武岩"},{"phrase":"basalt columns","zh":"玄武岩柱"},{"phrase":"basalt lava","zh":"玄武岩熔岩"},{"phrase":"basalt quarry","zh":"玄武岩采石场"},{"phrase":"flood basalt","zh":"溢流玄武岩"},{"phrase":"basalt pavement","zh":"玄武岩石板路"}],"forms":[{"label":"复数（指多种玄武岩）","form":"basalts"},{"label":"形容词（玄武质的）","form":"basaltic"},{"label":"相关岩石（辉长岩）","form":"gabbro"},{"label":"相关岩石（安山岩）","form":"andesite"},{"label":"核心名词（熔岩）","form":"lava"}],"derivatives":[{"word":"basaltic","pos":"adj.","zh":"玄武质的；玄武岩的"},{"word":"basaltware","pos":"n.","zh":"黑色玄武岩陶器"},{"word":"gabbro","pos":"n.","zh":"辉长岩（同成分的粗粒侵入岩）"},{"word":"lava","pos":"n.","zh":"熔岩"},{"word":"columnar","pos":"adj.","zh":"柱状的"}],"senses":[{"no":"01","title":"Dark fine-grained volcanic rock","titleCN":"深色细粒火山岩","definition":"a mafic volcanic rock that cooled quickly at or near the surface, giving tiny crystals","definitionCN":"在地表或近地表快速冷却、因而晶体细小的镁铁质火山岩","example":"The cliff was built of basalt that cooled into tall columns.","exampleCN":"这面崖壁由冷却成高柱的玄武岩构成。","why":"Fast cooling leaves no time for large crystals, so basalt is dark and fine rather than speckled like granite.","whyCN":"快速冷却来不及长出大晶体，因此玄武岩深色细粒，不像花岗岩那样布满斑点。"},{"no":"02","title":"A lava-flow rock","titleCN":"熔岩流形成的岩石","definition":"rock formed from low-viscosity lava that spread in thin sheets before solidifying","definitionCN":"由低黏度熔岩在凝固前铺成薄层而形成的岩石","example":"The basalt flow reached the sea in a single afternoon.","exampleCN":"这股玄武岩熔岩流在一个下午内抵达海边。","why":"Basalt lava runs easily, so it travels far and builds broad sheets rather than steep cones.","whyCN":"玄武岩熔岩流动性强，因此流得远，形成宽广岩席而非陡峭锥体。"},{"no":"03","title":"Ocean-floor bedrock","titleCN":"洋底基岩","definition":"the rock that makes up most of the oceanic crust","definitionCN":"构成大洋地壳大部分的岩石","example":"New basalt forms along the mid-ocean ridge.","exampleCN":"新的玄武岩沿大洋中脊形成。","why":"Because oceanic crust is created at spreading ridges, basalt is the planet's most abundant surface rock.","whyCN":"由于大洋地壳在扩张脊处生成，玄武岩是地球表面最丰富的岩石。"},{"no":"04","title":"Columnar jointing","titleCN":"柱状节理","definition":"basalt that shrank on cooling and split into polygonal columns","definitionCN":"冷却收缩并裂成多边形石柱的玄武岩","example":"The basalt columns form a natural staircase to the sea.","exampleCN":"这些玄武岩柱构成通往海边的天然阶梯。","why":"Cooling contracts the rock; contraction centres at points, and the cracks between them make columns.","whyCN":"冷却使岩石收缩；收缩以点为中心，点之间的裂缝便形成石柱。"},{"no":"05","title":"Aggregate and road stone","titleCN":"骨料与筑路石","definition":"crushed basalt used for roads, concrete aggregate, and railway ballast","definitionCN":"用于道路、混凝土骨料与铁路道砟的碎玄武岩","example":"The roadbed is packed with crushed basalt.","exampleCN":"路基用碎玄武岩填压。","why":"Hard, angular, and tough, crushed basalt locks together and resists wear.","whyCN":"坚硬、棱角分明且耐磨，碎玄武岩彼此咬合且抗磨损。"},{"no":"06","title":"Flood-basalt province","titleCN":"溢流玄武岩区","definition":"vast stacked flows erupted over a short geological interval","definitionCN":"在短暂地质时期内喷发堆积的巨厚熔岩流","example":"The plateau is a flood basalt thousands of metres thick.","exampleCN":"这片高原是厚达数千米的溢流玄武岩。","why":"Repeated low-viscosity eruptions stack sheet upon sheet, building provinces large enough to affect climate.","whyCN":"低黏度熔岩反复喷发，一层层叠加，形成足以影响气候的玄武岩区。"},{"no":"07","title":"Weathered basalt soil","titleCN":"玄武岩风化土壤","definition":"fertile clay-rich soil developed on weathered basalt","definitionCN":"在风化玄武岩上发育的肥沃富黏土土壤","example":"Farmers prize the dark soil formed on old basalt.","exampleCN":"农民珍视由古老玄武岩形成的深色土壤。","why":"Basalt weathers into clay minerals and iron oxides, producing soils that hold water and nutrients.","whyCN":"玄武岩风化成黏土矿物与铁氧化物，形成保水保肥的土壤。"},{"no":"08","title":"A record of volcanic history","titleCN":"火山历史的记录","definition":"layers of basalt whose age and chemistry record eruptions and the state of the mantle","definitionCN":"其年龄与化学成分记录喷发事件与地幔状态的玄武岩层","example":"Each basalt layer marks a separate eruption.","exampleCN":"每一层玄武岩标记一次独立的喷发。","why":"Successive flows are laid down in order, so the stack is a dated diary of volcanic activity.","whyCN":"接连的熔岩流按顺序堆积，因此整个层序是一部带年代的火山活动日记。"},{"no":"09","title":"Abstract: a dark, hard foundation","titleCN":"抽象义：深色坚硬的基础","definition":"something dark, heavy, and unglamorous that underlies a visible structure","definitionCN":"深色、沉重、不起眼却支撑可见结构的底层事物","example":"The whole project rested on basalt: unglamorous, heavy, and strong.","exampleCN":"整个项目建立在玄武岩般的基础之上：不起眼、沉重而坚固。","why":"The ocean floor is hidden under water yet supports continents, so the rock becomes an image of unnoticed foundations.","whyCN":"洋底藏于水下却支撑大陆，因此这种岩石成为不被注意的地基的意象。"}],"etymology":{"intro":{"en":"Basalt came into English through Latin from Greek, where it named a dark touchstone. The deeper origin is disputed. Dates are approximate.","cn":"basalt 经拉丁语从希腊语进入英语，原指一种深色试金石。更深的来源有争议。年代均为约数。"},"items":[{"era":"GREEK BASANOS","en":"Greek basanos meant a touchstone used to test gold, and also 'test, examination'. The stone sense came first; the abstract sense followed.","cn":"希腊语 basanos 指用来检验黄金的试金石，也指「检验、考验」。石头义在先，抽象义随后。"},{"era":"GREEK BASANITES","en":"Basanites lithos was the dark stone itself, probably named from its use as a test stone rather than from a place.","cn":"basanites lithos 指这种深色石头本身，其名可能来自用途（试金石），而非地名。"},{"era":"LATIN BASALTES","en":"Latin basaltes borrowed the Greek word for a hard dark stone; English took it in the sixteenth century.","cn":"拉丁语 basaltes 借入希腊语这个词，指坚硬深色石头；英语在 16 世纪借入。"},{"era":"ORIGIN UNCERTAIN","en":"Source uncertain: the Greek word may itself come from an Egyptian word for a dark sandstone, but this is a hypothesis rather than a demonstrated derivation. No Indo-European root is established.","cn":"来源不确定：这个希腊词本身可能来自埃及语中一个指深色砂岩的词，但这只是假说，并非已证实的派生。尚无确立的印欧词根。"},{"era":"GEOLOGICAL SENSE","en":"In the eighteenth century basalt was applied to the dark columnar rock of volcanic regions, and the modern petrological sense followed.","cn":"18 世纪 basalt 被用于火山地区的深色柱状岩石，现代岩石学含义随后确立。"}]},"similar":{"note":{"en":"Group one holds volcanic and intrusive rocks that share basalt's chemistry but differ in grain size; group two holds dark stones often mistaken for it.","cn":"第一组是化学成分与玄武岩相同、但粒径不同的火山岩与侵入岩；第二组是常被误认的深色石材。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"basaltic","ipa":"/bəˈsɔːltɪk/","tag":"adjective","definition":"The adjective meaning 'of basalt'; it describes the rock or a magma type rather than naming a specimen.","definitionCN":"意为「玄武质的」的形容词；它描述岩石或岩浆类型，而非命名标本。"},{"word":"gabbro","ipa":"/ˈɡæbrəʊ/","tag":"coarse equivalent","definition":"The same mafic composition cooled slowly underground, so its crystals are large; basalt is its fine-grained surface twin.","definitionCN":"同成分的镁铁质岩浆在地下缓慢冷却，晶体粗大；玄武岩是它细粒的地表孪生体。"},{"word":"andesite","ipa":"/ænˈdiːzaɪt/","tag":"intermediate","definition":"A volcanic rock between basalt and rhyolite in silica content, usually lighter in colour.","definitionCN":"二氧化硅含量介于玄武岩与流纹岩之间的火山岩，颜色通常较浅。"},{"word":"rhyolite","ipa":"/ˈraɪəlaɪt/","tag":"silica-rich","definition":"A pale volcanic rock rich in silica, the volcanic counterpart of granite.","definitionCN":"富含二氧化硅的浅色火山岩，是花岗岩的火山对应物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"lava","ipa":"/ˈlɑːvə/","tag":"molten material","definition":"Molten rock at the surface; basalt is what it becomes after cooling.","definitionCN":"地表的熔融岩石；玄武岩是它冷却后的产物。"},{"word":"obsidian","ipa":"/əbˈsɪdiən/","tag":"glassy volcanic","definition":"Volcanic glass formed from quickly chilled lava, usually richer in silica and shiny rather than granular.","definitionCN":"快速冷却的熔岩形成的火山玻璃，通常硅含量更高，光亮而非颗粒状。"},{"word":"tuff","ipa":"/tʌf/","tag":"volcanic ash","definition":"Rock made of consolidated volcanic ash, softer and lighter than basalt.","definitionCN":"由固结火山灰构成的岩石，比玄武岩更软更轻。"},{"word":"granite","ipa":"/ˈɡrænɪt/","tag":"continental counterpart","definition":"A coarse, pale, silica-rich intrusive rock; basalt is dark, fine, and silica-poor.","definitionCN":"粗粒、浅色、富硅的侵入岩；玄武岩深色、细粒、贫硅。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real etymology notes, real rock names and real collocations, not invented rhymes.","cn":"正常联想：真实词源注记、真实岩石名称与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Basalt is the fine-grained twin of gabbro: same chemistry, different cooling speed.","cn":"玄武岩是辉长岩的细粒孪生体：成分相同，冷却速度不同。"},{"en":"Columnar basalt records contraction on cooling.","cn":"柱状玄武岩记录冷却时的收缩。"},{"en":"The ocean floor is basalt; the continents are granite.","cn":"洋底是玄武岩，大陆是花岗岩。"},{"en":"Basalt weathers into fertile dark soil.","cn":"玄武岩风化成肥沃的深色土壤。"},{"en":"Greek basanos was a touchstone, which links the rock's name to testing.","cn":"希腊语 basanos 是试金石，这把岩石的名字与「检验」联系起来。"}],"abstract":[{"en":"Picture a black floor hidden under every ocean, holding the continents up.","cn":"想象一片黑色地板藏在所有海洋之下，托着大陆。"},{"en":"Picture a column of cooled wax that split into neat hexagonal posts.","cn":"想象一根冷却的蜡柱裂成整齐的六棱柱。"},{"en":"Picture a foundation nobody photographs but everything stands on.","cn":"想象一个无人拍照、却承载一切的地基。"}]},"examples":[{"en":"The cliff was built of basalt that cooled into tall columns.","cn":"这面崖壁由冷却成高柱的玄武岩构成。"},{"en":"Basalt lava flows far because it is low in silica and runs easily.","cn":"玄武岩熔岩因硅含量低、流动性好而流得很远。"},{"en":"Crushed basalt makes a hard, angular road aggregate.","cn":"碎玄武岩可制成坚硬、棱角分明的筑路骨料。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「巴索特」——火山口边黑得发亮的柱子 → 玄武岩","word":"basalt"},"root":"拉丁语 basaltes 借自希腊语 basanites（lithos），源自 basanos「试金石、检验」；其更深来源不确定，或与埃及语中表示深色砂岩的词有关，仅为假说，无确立的印欧词根。","sensesIntro":{"en":"Nine senses follow the rock from eruption to ocean floor, columns, roads, plateaus, soils, history, and finally to the image of a hidden foundation.","cn":"九个义项让这种岩石从喷发走到洋底、石柱、道路、高原、土壤、历史，最后成为隐藏地基的意象。"},"semanticMap":{"core":{"en":"CORE IMAGE: black hexagonal columns standing side by side at the edge of a volcano.","cn":"核心意象：火山口边缘并立的一排黑色六棱石柱。"},"chain":["DARK VOLCANIC ROCK","FAST-COOLED LAVA","OCEAN FLOOR","COLUMNAR JOINTING","HARD AGGREGATE","HIDDEN FOUNDATION"],"branches":[{"senses":"S1 · S2","en":"ROCK AND FLOW: the stone is the cooled end of a lava that once ran like liquid.","cn":"岩石与熔岩流：石头是曾经流动如液的熔岩冷却后的一端。"},{"senses":"S3 · S8","en":"OCEAN AND RECORD: ocean-floor basalt is also a dated diary of eruptions.","cn":"洋底与记录：洋底玄武岩同时也是带年代的喷发日记。"},{"senses":"S4","en":"CONTRACTION: cooling shrinks the mass and cracks it into columns.","cn":"收缩：冷却使岩体缩小，并裂成石柱。"},{"senses":"S5 · S6","en":"USE AND SCALE: crushed stone builds roads, while stacked flows build provinces.","cn":"用途与规模：碎石筑路，叠置的熔岩流则造出玄武岩区。"},{"senses":"S7 · S9","en":"SOIL AND SYMBOL: weathering makes fertile ground, and the hidden floor becomes a metaphor.","cn":"土壤与象征：风化造出沃土，隐藏的地板则成为比喻。"}]},"affixes":{"intro":{"en":"Basalt has few English relatives, but its technical family is stable and useful.","cn":"basalt 的英语同族词不多，但其技术词族稳定而实用。"},"latinIntro":{"en":"Latin basaltes and Greek basanites are the recorded forms; the deeper source is disputed, so no further root is offered.","cn":"有书证的形式是拉丁语 basaltes 与希腊语 basanites；更深来源有争议，因此不再往上给出词根。"},"items":[{"word":"basanos","structure":"Greek basanos (touchstone, test)","meaning":"a stone for testing gold","meaningCN":"检验黄金的试金石","example":"Basanos meant both the stone and the test.","exampleCN":"basanos 既指石头，也指检验。"},{"word":"basanites","structure":"Greek basanites lithos (touchstone rock)","meaning":"dark touchstone","meaningCN":"深色试金石","example":"Basanites named the dark stone before it named the rock type.","exampleCN":"basanites 先指深色石头，后指岩石类型。"},{"word":"basaltes","structure":"Latin basaltes, from Greek","meaning":"hard dark stone","meaningCN":"坚硬深色石头","example":"Latin kept the Greek stone name.","exampleCN":"拉丁语保留了希腊语的石名。"},{"word":"basalt","structure":"basaltes, shortened in English","meaning":"dark volcanic rock","meaningCN":"深色火山岩；玄武岩","example":"Basalt forms when mafic lava cools fast.","exampleCN":"镁铁质熔岩快速冷却时形成玄武岩。"},{"word":"basaltic","structure":"basalt + -ic (relating to)","meaning":"of basalt","meaningCN":"玄武质的","example":"Basaltic magma is low in silica.","exampleCN":"玄武质岩浆的硅含量低。"},{"word":"basaltware","structure":"basalt + ware (manufactured goods)","meaning":"black stoneware imitating basalt","meaningCN":"仿玄武岩的黑色炻器","example":"Basaltware was popular for teapots.","exampleCN":"仿玄武岩炻器曾流行于茶壶制作。"},{"word":"gabbro","structure":"Italian gabbro, a local rock name","meaning":"coarse-grained mafic rock","meaningCN":"粗粒镁铁质岩石；辉长岩","example":"Gabbro is the slow-cooled equivalent of basalt.","exampleCN":"辉长岩是玄武岩的慢冷对应物。"},{"word":"lava","structure":"Italian lava, probably from Latin labes (a fall)","meaning":"molten rock at the surface","meaningCN":"地表的熔融岩石","example":"Basalt lava spreads in thin sheets.","exampleCN":"玄武岩熔岩铺成薄层。"},{"word":"columnar","structure":"column + -ar (like, relating to)","meaning":"shaped like columns","meaningCN":"柱状的","example":"Columnar jointing is common in thick basalt flows.","exampleCN":"柱状节理在厚层玄武岩流中很常见。"}],"latinEntries":[{"word":"basaltes","structure":"basaltes, basaltis (m., third declension)","meaning":"hard dark stone","meaningCN":"坚硬深色的石头"},{"word":"basanites","structure":"Greek basanites (lithos), borrowed into Latin","meaning":"touchstone","meaningCN":"试金石"},{"word":"basanos","structure":"Greek basanos (f.)","meaning":"touchstone; test","meaningCN":"试金石；检验"}]}},{"word":"shale","ipa_uk":"/ʃeɪl/","ipa_us":"/ʃeɪl/","definition_zh":"页岩；由黏土与粉砂固结而成、沿薄层易裂的细粒沉积岩","definition_en":"a fine-grained sedimentary rock made of hardened clay and silt that splits into thin layers","core_image":"河岸剖面像一叠薄纸，用手一掰便沿层面裂开","scene":"河岸的剖面像一叠薄纸，用手一掰就沿层面裂开： The river bank exposes shale that splits along thin layers.","sceneCN":"这里 shale 指「沿薄层易裂的细粒沉积岩」（第 1 个义项：由黏土与粉砂固结成的细粒岩石）；句意为河岸剖面露出可沿薄层裂开的页岩。","pos":[{"tag":"n.","zh":"页岩（物质名词；指多种页岩时复数为 shales）"}],"collocations":[{"phrase":"shale gas","zh":"页岩气"},{"phrase":"shale oil","zh":"页岩油"},{"phrase":"shale bed","zh":"页岩层"},{"phrase":"black shale","zh":"黑色页岩"},{"phrase":"shale quarry","zh":"页岩采石场"},{"phrase":"a layer of shale","zh":"一层页岩"}],"forms":[{"label":"复数（指多种页岩）","form":"shales"},{"label":"形容词（页岩质的）","form":"shaly"},{"label":"相关岩石（泥岩）","form":"mudstone"},{"label":"相关岩石（板岩）","form":"slate"},{"label":"核心动词（裂开）","form":"split"}],"derivatives":[{"word":"shaly","pos":"adj.","zh":"页岩质的；含页岩的"},{"word":"shale gas","pos":"n.","zh":"页岩气"},{"word":"shale oil","pos":"n.","zh":"页岩油"},{"word":"mudstone","pos":"n.","zh":"泥岩（不具薄层裂理的对应岩石）"},{"word":"slate","pos":"n.","zh":"板岩（页岩变质而成）"}],"senses":[{"no":"01","title":"Fine-grained rock that splits into sheets","titleCN":"沿薄层裂开的细粒岩石","definition":"a sedimentary rock of compacted clay and silt whose parallel layers part easily","definitionCN":"由压实黏土与粉砂构成、平行层理易于分开的沉积岩","example":"The river bank exposes shale that splits along thin layers.","exampleCN":"河岸剖面露出可沿薄层裂开的页岩。","why":"Clay flakes settle flat, so the rock inherits a grain that makes it part along sheets.","whyCN":"黏土片平铺沉降，岩石继承这种排列，因而沿薄片分开。"},{"no":"02","title":"The source rock for oil and gas","titleCN":"油气烃源岩","definition":"organic-rich shale that generated petroleum when buried and heated","definitionCN":"富含有机质、被埋藏加热后生成石油的页岩","example":"The black shale is the source of the oil in the sandstone above.","exampleCN":"黑色页岩是上方砂岩中石油的来源。","why":"Fine mud preserves organic matter, and burial cooks it into oil and gas; the rock is the kitchen, not the reservoir.","whyCN":"细泥能保存有机质，埋藏加热则把它烹成油气；这种岩石是厨房，不是储层。"},{"no":"03","title":"Shale gas and shale oil resources","titleCN":"页岩气与页岩油资源","definition":"hydrocarbons extracted directly from low-permeability shale by fracturing","definitionCN":"通过压裂直接从低渗透页岩中采出的碳氢化合物","example":"Shale gas changed the energy map of the region.","exampleCN":"页岩气改变了该地区的能源格局。","why":"The rock holds the fuel but barely lets it flow, so production depends on opening cracks.","whyCN":"岩石含燃料却几乎不让它流动，因此开采依赖开凿裂缝。"},{"no":"04","title":"Raw material for bricks and cement","titleCN":"制砖与水泥原料","definition":"clay-rich shale mined and fired for bricks, tiles, and cement","definitionCN":"开采并烧制砖、瓦与水泥的富黏土页岩","example":"The brickyard fires shale from the hill behind it.","exampleCN":"砖厂烧制厂后山开采的页岩。","why":"Shale is clay already hardened; grinding and firing it returns it to a workable ceramic material.","whyCN":"页岩是已经硬化的黏土；磨碎再烧制便恢复为可加工的陶瓷原料。"},{"no":"05","title":"A weak rock on slopes","titleCN":"坡面上的软弱岩体","definition":"shale that weathers quickly and contributes to landslides and muddy runoff","definitionCN":"风化迅速、易引发滑坡与泥流的页岩","example":"The road failed where shale had weathered to clay.","exampleCN":"道路在页岩风化成黏土处塌毁。","why":"Its layers let water in and its clay softens when wet, so shale is a notorious slope material.","whyCN":"层理让水进入，黏土遇水变软，因此页岩是出了名的易滑坡体。"},{"no":"06","title":"A fossil-bearing deposit","titleCN":"含化石的页岩层","definition":"shale that preserves soft-bodied fossils because fine mud sealed them from oxygen","definitionCN":"因细泥隔绝氧气而保存软躯体化石的页岩","example":"The Burgess Shale preserves animals without shells.","exampleCN":"伯吉斯页岩保存了没有壳的动物。","why":"Fine particles and low oxygen slow decay, which is why the best soft-tissue fossils come from shale.","whyCN":"细颗粒与低氧减缓腐烂，因此最好的软躯体化石多出自页岩。"},{"no":"07","title":"Thin laminations","titleCN":"薄层层理","definition":"the millimetre-scale layers that give shale its fissile character","definitionCN":"赋予页岩易裂性的毫米级薄层","example":"Each shale lamination marks a quiet episode of settling.","exampleCN":"每一层页岩薄层都标记一次平静的沉降。","why":"Season by season, the finest particles settle, and the record is written in sheets too thin to see at a glance.","whyCN":"一季又一季，最细的颗粒沉降，记录写在薄得一眼看不清的层片里。"},{"no":"08","title":"Abstract: material that splits into thin sheets","titleCN":"抽象义：易裂成薄片之物","definition":"anything that separates into thin, flat pieces along parallel planes","definitionCN":"沿平行面裂成薄而平的片状物的任何东西","example":"The argument split like shale along its weakest plane.","exampleCN":"这场争论沿最薄弱的层面像页岩一样裂开。","why":"The metaphor borrows fissility: strength in one direction and easy parting in another.","whyCN":"这一比喻借用了易裂性：一个方向坚固，另一个方向却容易分开。"}],"etymology":{"intro":{"en":"Shale is an English word from the same Germanic stock as shell and scale. The rock sense is early modern. Dates are approximate.","cn":"shale 是英语词，与 shell、scale 同出日耳曼语族。岩石义形成于近代早期。年代均为约数。"},"items":[{"era":"OLD ENGLISH SCEALU","en":"Scealu meant 'shell, husk, scale', from Proto-Germanic skaljo, from a root meaning 'to divide or split'.","cn":"scealu 意为「壳、外皮、鳞片」，来自原始日耳曼语 skaljo，其词根意为「分开、裂开」。"},{"era":"ROCK SENSE","en":"By the seventeenth century shale named a rock that splits into thin sheets, echoing the older sense of a flaky covering.","cn":"到 17 世纪，shale 指一种裂成薄片的岩石，呼应了「片状外壳」的旧义。"},{"era":"RELATED WORDS","en":"Shell, scale, and shale descend from the same splitting image, though their later forms diverged.","cn":"shell、scale 与 shale 都源自同一「裂开」意象，尽管后来形式分化。"},{"era":"INDUSTRIAL SENSE","en":"Nineteenth-century industry used shale for brick clay and for the oil distilled from it; the resource sense expanded in the twentieth century.","cn":"19 世纪工业用页岩制砖并从其中蒸馏油，资源义在 20 世纪扩展。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English use of shale for the rock is not precisely recorded, and the pre-Germanic root is a reconstruction.","cn":"来源不确定（首见年代）：shale 指这种岩石的最早英语书证没有精确记载，其前日耳曼语词根属重构形式。"}]},"similar":{"note":{"en":"Group one holds fine-grained sedimentary names that differ by fissility; group two holds rocks and products confused with shale.","cn":"第一组是按易裂性区分的细粒沉积岩名称；第二组是易与页岩混淆的岩石与产物。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"slate","ipa":"/sleɪt/","tag":"metamorphic","definition":"Shale transformed by low-grade metamorphism, harder and with a stronger cleavage used for roofing.","definitionCN":"经低级变质作用的页岩，更硬，具更强的板理，可用于屋顶。"},{"word":"mudstone","ipa":"/ˈmʌdstəʊn/","tag":"no fissility","definition":"Fine-grained rock of mud that breaks in blocks rather than parting into thin sheets.","definitionCN":"由泥构成的细粒岩石，裂成块状而非分成薄片。"},{"word":"siltstone","ipa":"/ˈsɪltstəʊn/","tag":"coarser grains","definition":"Rock of silt-sized particles, coarser than shale and usually less fissile.","definitionCN":"由粉砂级颗粒构成的岩石，比页岩粗，通常不易裂成薄片。"},{"word":"schist","ipa":"/ʃɪst/","tag":"metamorphic cousin","definition":"A metamorphic rock with visible mica flakes and strong foliation, formed at higher grade than slate.","definitionCN":"具可见云母片与强叶理的变质岩，变质程度高于板岩。"}]},{"heading":"NEAR MEANING","entries":[{"word":"clay","ipa":"/kleɪ/","tag":"soft material","definition":"Soft, fine particles that become shale when compacted and cemented.","definitionCN":"柔软细小的颗粒，压实胶结后成为页岩。"},{"word":"oil shale","ipa":"/ɔɪl ʃeɪl/","tag":"fuel rock","definition":"Shale rich in kerogen that yields oil when heated; it is a resource label rather than a rock type.","definitionCN":"富含干酪根、加热可产油的页岩；这是资源标签而非岩石类型名。"},{"word":"marl","ipa":"/mɑːl/","tag":"lime-rich mud","definition":"A soft mixture of clay and calcium carbonate, often forming under water; it is not true shale.","definitionCN":"黏土与碳酸钙的松软混合物，常在水下形成；并非真正的页岩。"},{"word":"schiefer","ipa":"/ˈʃiːfə/","tag":"German synonym","definition":"A German term for fissile rock, used in some English geological names but not as a general word.","definitionCN":"德语中表示易裂岩石的术语，见于部分英语地质名称，但非通用词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Germanic roots, real rock names and real collocations, not invented rhymes.","cn":"正常联想：真实日耳曼语词根、真实岩石名称与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Shale shares a root image with shell and scale: thin plates that part.","cn":"shale 与 shell、scale 共享词根意象：会分开的薄片。"},{"en":"Shale splits; mudstone blocks; slate is its metamorphic upgrade.","cn":"页岩裂成片，泥岩裂成块，板岩是它的变质升级版。"},{"en":"Black shale is a kitchen for oil, not a reservoir for it.","cn":"黑色页岩是生成石油的厨房，而非储存石油的储层。"},{"en":"The Burgess Shale is famous for soft-bodied fossils.","cn":"伯吉斯页岩以软躯体化石闻名。"},{"en":"Shale is weak on slopes because water enters along its layers.","cn":"页岩在坡面上不稳，因为水沿层理进入。"}],"abstract":[{"en":"Picture a book whose pages separate at the slightest pull.","cn":"想象一本书，轻轻一拉书页就分开。"},{"en":"Picture a stone that is strong across and weak along.","cn":"想象一块横向坚固、纵向薄弱的石头。"},{"en":"Picture an old dispute splitting along the one seam nobody repaired.","cn":"想象一桩旧争执沿唯一没修补的接缝裂开。"}]},"examples":[{"en":"The river bank exposes shale that splits along thin layers.","cn":"河岸剖面露出可沿薄层裂开的页岩。"},{"en":"Black shale generated the oil now trapped in the sandstone above.","cn":"黑色页岩生成了如今困在上方砂岩中的石油。"},{"en":"Rainwater enters the shale along its laminations and softens the slope.","cn":"雨水沿页岩薄层进入，使坡体变软。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「谢尔」——一掰就裂成薄片的石头 → 页岩","word":"shale"},"root":"古英语 scealu「壳、外皮、鳞片」，来自原始日耳曼语 skaljo，词根意为「分开、裂开」，与 shell、scale 同源；前日耳曼语词根属重构形式。","sensesIntro":{"en":"Eight senses follow fissile mud from its layering to its role as source rock, fuel, brick clay, weak slope, fossil vault, and finally to a metaphor for easy parting.","cn":"八个义项让易裂的泥质岩从层理走到烃源岩、燃料、砖料、软弱坡体、化石宝库，最后成为易于分开的比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bank of rock that looks like a stack of thin paper and parts along the sheets.","cn":"核心意象：一段像薄纸叠成的岩壁，沿层片分开。"},"chain":["FISSILE MUD ROCK","ORGANIC KITCHEN","UNCONVENTIONAL FUEL","BRICK CLAY","WEAK SLOPE","PARTING IMAGE"],"branches":[{"senses":"S1 · S7","en":"LAYERS: the millimetre sheets are both the rock's definition and its visible record.","cn":"层理：毫米薄层既是岩石的定义，也是它可见的记录。"},{"senses":"S2 · S3","en":"KITCHEN AND FUEL: the rock cooks hydrocarbons, and industry cracks it open to retrieve them.","cn":"厨房与燃料：岩石烹出碳氢化合物，工业则压裂它来取出。"},{"senses":"S4","en":"CLAY USE: hardened clay can be ground and fired back into brick and cement.","cn":"黏土用途：硬化的黏土可磨碎重烧为砖与水泥。"},{"senses":"S5","en":"WEAKNESS: water follows the layers, and the slope fails where the clay softens.","cn":"软弱：水沿层理进入，黏土变软处坡体失稳。"},{"senses":"S6 · S8","en":"PRESERVATION AND METAPHOR: fine mud seals fossils, and the same easy parting becomes an image of division.","cn":"保存与比喻：细泥封存化石，同样的易裂性又成为分裂的意象。"}]},"affixes":{"intro":{"en":"Shale has few modern affixes, but its Germanic relatives and technical derivatives are worth reading as a family.","cn":"shale 的现代词缀不多，但其日耳曼语同族与技术派生词值得作为一个词族来读。"},"latinIntro":{"en":"Shale is native English and has no Latin source; the technical vocabulary instead borrows Latin and Greek roots for related rocks.","cn":"shale 是英语本族词，没有拉丁语源；相关岩石的技术词汇转而借用拉丁与希腊词根。"},"items":[{"word":"scealu","structure":"Old English scealu (shell, husk, scale)","meaning":"a thin covering that parts","meaningCN":"会分开的薄覆盖层","example":"Scealu named a shell or husk before it named a rock.","exampleCN":"scealu 先指壳或外皮，后来才指岩石。"},{"word":"shale","structure":"scealu, with the rock sense added","meaning":"fissile mud rock","meaningCN":"易裂的泥质岩；页岩","example":"Shale parts along its bedding planes.","exampleCN":"页岩沿层理面分开。"},{"word":"shaly","structure":"shale + -y (having the quality of)","meaning":"containing or like shale","meaningCN":"含页岩的；页岩质的","example":"The shaly interval breaks into chips.","exampleCN":"页岩质层段裂成碎屑。"},{"word":"shell","structure":"Old English scell (shell)","meaning":"a hard outer covering","meaningCN":"坚硬的外壳","example":"Shell and shale share the splitting image.","exampleCN":"shell 与 shale 共享「裂开」的意象。"},{"word":"scale","structure":"Old French escale, of Germanic origin","meaning":"a thin plate or flake","meaningCN":"薄片；鳞片","example":"Scale also names a thin, parting plate.","exampleCN":"scale 也指会脱落的薄片。"},{"word":"mudstone","structure":"mud + stone","meaning":"fine-grained rock without fissility","meaningCN":"不具易裂性的细粒岩石；泥岩","example":"Mudstone breaks in blocks, shale in sheets.","exampleCN":"泥岩裂成块，页岩裂成片。"},{"word":"slate","structure":"Old French esclate (a splinter)","meaning":"metamorphosed shale","meaningCN":"变质页岩；板岩","example":"Slate splits into roof tiles.","exampleCN":"板岩裂成屋瓦。"},{"word":"siltstone","structure":"silt + stone","meaning":"rock of silt grains","meaningCN":"粉砂岩","example":"Siltstone is coarser than shale.","exampleCN":"粉砂岩比页岩粗。"},{"word":"schist","structure":"Greek schistos (split), through German","meaning":"strongly foliated metamorphic rock","meaningCN":"强叶理变质岩；片岩","example":"Schist is named from its splitting habit.","exampleCN":"schist 因其易裂习性得名。"}],"latinEntries":[]}},{"word":"quartz","ipa_uk":"/kwɔːts/","ipa_us":"/kwɔːrts/","definition_zh":"石英；由二氧化硅结晶而成的常见矿物","definition_en":"a hard mineral made of silicon dioxide, common in rocks, sand, and gem varieties","core_image":"河床白色卵石间一颗透明六棱晶体在阳光下闪光","scene":"河床的白色卵石里混着透明的小晶体，棱角在阳光下闪亮： A clear quartz crystal glittered among the river pebbles.","sceneCN":"这里 quartz 指「二氧化硅结晶成的矿物」（第 1 个义项：化学成分与晶体结构明确的矿物）；句意为一颗透明石英晶体在河卵石间闪光。","pos":[{"tag":"n.","zh":"石英（物质名词；指多种石英时复数为 quartzes）"}],"collocations":[{"phrase":"quartz crystal","zh":"石英晶体"},{"phrase":"quartz sand","zh":"石英砂"},{"phrase":"quartz vein","zh":"石英脉"},{"phrase":"rose quartz","zh":"粉晶；蔷薇石英"},{"phrase":"quartz watch","zh":"石英表"},{"phrase":"a grain of quartz","zh":"一粒石英"}],"forms":[{"label":"复数（指多种石英）","form":"quartzes"},{"label":"形容词（石英质的）","form":"quartzose"},{"label":"相关岩石（石英岩）","form":"quartzite"},{"label":"矿物变种（紫水晶）","form":"amethyst"},{"label":"化学成分名","form":"silica"}],"derivatives":[{"word":"quartzose","pos":"adj.","zh":"石英质的；富含石英的"},{"word":"quartzite","pos":"n.","zh":"石英岩"},{"word":"quartziferous","pos":"adj.","zh":"含石英的"},{"word":"silica","pos":"n.","zh":"二氧化硅"},{"word":"amethyst","pos":"n.","zh":"紫水晶（石英变种）"}],"senses":[{"no":"01","title":"The mineral silicon dioxide","titleCN":"二氧化硅矿物","definition":"a hard, chemically simple mineral of silicon and oxygen, stable across a wide range of conditions","definitionCN":"由硅与氧构成、化学组成简单、在很宽条件下稳定的坚硬矿物","example":"A clear quartz crystal glittered among the river pebbles.","exampleCN":"一颗透明石英晶体在河卵石间闪光。","why":"Quartz is defined by its composition and lattice, not by colour or shape; those vary while the mineral stays the same.","whyCN":"石英由成分与晶格定义，而非颜色或形状；后者会变，矿物本身不变。"},{"no":"02","title":"A crystal with six-sided prisms","titleCN":"六棱柱状晶体","definition":"a quartz crystal showing hexagonal prisms and pointed terminations","definitionCN":"呈六棱柱与尖顶形态的石英晶体","example":"The quartz grew as a six-sided prism in the cavity.","exampleCN":"石英在晶洞中长成六棱柱。","why":"Its lattice repeats in six-fold symmetry, so a freely grown crystal takes a hexagonal outline.","whyCN":"其晶格以六重对称重复，因此自由生长的晶体呈六边形轮廓。"},{"no":"03","title":"The main component of sand","titleCN":"砂的主要成分","definition":"quartz grains that survive weathering and make up most sand and sandstone","definitionCN":"经风化残留、构成大部分砂与砂岩的石英颗粒","example":"Most beach sand is quartz that rivers carried to the sea.","exampleCN":"多数海滩砂是河流带到海边的石英。","why":"Quartz resists chemical weathering, so it outlasts other minerals and accumulates as sand.","whyCN":"石英抗化学风化，因此比其它矿物存留更久，堆积成砂。"},{"no":"04","title":"A piezoelectric material","titleCN":"压电材料","definition":"quartz used in watches, radios, and sensors because it generates charge when squeezed","definitionCN":"因受压产生电荷而用于钟表、无线电与传感器的石英","example":"The quartz in the watch vibrates at a precise frequency.","exampleCN":"手表中的石英以精确频率振动。","why":"Its regular lattice converts mechanical stress into electrical signal, which is why clocks can count it.","whyCN":"其规整晶格把机械应力转为电信号，因此钟表可以「数」它。"},{"no":"05","title":"A gem and ornamental stone","titleCN":"宝石与观赏石","definition":"clear or coloured quartz varieties valued as gems and carvings","definitionCN":"作为宝石与雕刻材料而受珍视的透明或彩色石英变种","example":"Rose quartz is carved into small figures.","exampleCN":"粉晶被雕成小摆件。","why":"Impurities add colour while the hard lattice takes a polish, turning a common mineral into a gem.","whyCN":"杂质带来颜色，坚硬晶格又能抛光，于是常见矿物变成宝石。"},{"no":"06","title":"A vein in hydrothermal deposits","titleCN":"热液矿脉中的石英","definition":"quartz filling cracks where hot mineral-rich water deposited silica","definitionCN":"富含矿物的热水沉淀二氧化硅、充填裂缝形成的石英","example":"Gold often sits in quartz veins.","exampleCN":"黄金常赋存于石英脉中。","why":"Hot fluids carry silica and metals together; when they cool, quartz seals the crack and traps the ore.","whyCN":"热液同时携带硅与金属；冷却时石英封住裂缝并圈闭矿石。"},{"no":"07","title":"A dust hazard","titleCN":"粉尘危害","definition":"fine quartz dust that damages lungs when inhaled over years","definitionCN":"长期吸入会损伤肺部的细石英粉尘","example":"Cutting stone without water raises quartz dust.","exampleCN":"无水切割石材会产生石英粉尘。","why":"Hardness makes the mineral useful, and the same hardness makes its dust cut lung tissue.","whyCN":"硬度使矿物有用，同样的硬度又使粉尘割伤肺组织。"},{"no":"08","title":"An industrial raw material","titleCN":"工业原料","definition":"quartz sand and crushed quartz used in glass, ceramics, and foundry moulds","definitionCN":"用于玻璃、陶瓷与铸造砂型的石英砂与碎石英","example":"The glassworks buys pure quartz sand by the tonne.","exampleCN":"玻璃厂成吨购买纯石英砂。","why":"Silica is the backbone of glass, so a cheap, pure source of quartz is an industrial necessity.","whyCN":"二氧化硅是玻璃的骨架，因此廉价纯净的石英来源是工业必需品。"},{"no":"09","title":"Abstract: clear, hard, and unchanging","titleCN":"抽象义：清澈、坚硬、不变","definition":"a quality of transparency combined with stubborn constancy","definitionCN":"透明与固执恒常相结合的性质","example":"Her quartz clarity hid a very hard will.","exampleCN":"她水晶般的清澈之下藏着极硬的意志。","why":"The metaphor joins two properties of the mineral: you can see through it, yet it yields to almost nothing.","whyCN":"这一比喻结合矿物的两种属性：看得透，却几乎不为外物所动。"}],"etymology":{"intro":{"en":"Quartz entered English from German in the sixteenth century, probably from a Slavic word for hard. The deeper origin is uncertain. Dates are approximate.","cn":"quartz 在 16 世纪从德语进入英语，可能来自斯拉夫语中表示「坚硬」的词。更深来源不确定。年代均为约数。"},"items":[{"era":"GERMAN QUARZ","en":"German miners called the mineral Quarz; Middle High German forms include twarc and quarc, showing that the word was still unsettled.","cn":"德国矿工把这种矿物称作 Quarz；中古高地德语形式包括 twarc 与 quarc，说明词形当时尚未固定。"},{"era":"SLAVIC SOURCE","en":"The German word is generally thought to come from a Slavic adjective meaning 'hard', represented by Czech tvrdy and Polish twardy.","cn":"一般认为这个德语词来自斯拉夫语中意为「坚硬」的形容词，如捷克语 tvrdy 与波兰语 twardy。"},{"era":"DEEPER ORIGIN","en":"Source uncertain: the Slavic adjective goes back to a reconstructed Proto-Slavic form, and its earlier Indo-European history is debated.","cn":"来源不确定：这个斯拉夫语形容词可上溯到一个重构的原始斯拉夫语形式，其更早的印欧语历史仍有争议。"},{"era":"ENGLISH BORROWING","en":"English adopted quartz in the sixteenth century, when mineralogy was beginning to name substances systematically.","cn":"英语在 16 世纪借入 quartz，当时矿物学正开始系统地为物质命名。"},{"era":"MODERN USES","en":"Piezoelectric and optical uses developed in the nineteenth and twentieth centuries, adding technical senses to the mineral name.","cn":"压电与光学用途在 19、20 世纪发展起来，为这一矿物名增添了技术含义。"}]},"similar":{"note":{"en":"Group one holds minerals and varieties that are chemically close to quartz; group two holds materials often confused with it.","cn":"第一组是化学上与石英接近的矿物与变种；第二组是常与石英混淆的材料。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"quartzite","ipa":"/ˈkwɔːtsaɪt/","tag":"rock, not mineral","definition":"A metamorphic rock made almost entirely of quartz grains; quartz is the mineral, quartzite the rock.","definitionCN":"几乎全由石英颗粒构成的变质岩；石英是矿物，石英岩是岩石。"},{"word":"quartzose","ipa":"/ˈkwɔːtsəʊs/","tag":"adjective","definition":"Meaning rich in quartz; it describes a rock's composition rather than naming the mineral.","definitionCN":"意为「富含石英的」；它描述岩石成分，而非命名矿物。"},{"word":"silica","ipa":"/ˈsɪlɪkə/","tag":"chemical name","definition":"Silicon dioxide as a substance, including its non-crystalline forms; quartz is its crystalline mineral form.","definitionCN":"作为物质的二氧化硅，包括非晶形态；石英是它的结晶矿物形态。"},{"word":"calcite","ipa":"/ˈkælsaɪt/","tag":"carbonate look-alike","definition":"Calcium carbonate, softer than quartz and reacting with acid; it is easily mistaken in the field.","definitionCN":"碳酸钙，比石英软且遇酸反应；野外容易误认。"}]},{"heading":"NEAR MEANING","entries":[{"word":"amethyst","ipa":"/ˈæməθɪst/","tag":"purple variety","definition":"Purple quartz coloured by iron and radiation; it is quartz with a gem variety name.","definitionCN":"由铁与辐射致色的紫色石英；它是带宝石变种名的石英。"},{"word":"rock crystal","ipa":"/rɒk ˈkrɪstl/","tag":"clear variety","definition":"Clear, colourless quartz; the old name distinguishes the gem form from ordinary grains.","definitionCN":"透明无色的石英；这一旧名把宝石形态与普通颗粒区分开。"},{"word":"chert","ipa":"/tʃɜːt/","tag":"microcrystalline silica","definition":"A hard, fine-grained silica rock; it is chemically like quartz but lacks visible crystals.","definitionCN":"坚硬细粒的二氧化硅岩石；化学成分似石英，但无可见晶体。"},{"word":"fused quartz","ipa":"/fjuːzd kwɔːts/","tag":"manufactured glass","definition":"Glass made by melting quartz; it keeps silica's properties without a crystal lattice.","definitionCN":"熔融石英制成的玻璃；保留二氧化硅性质，但没有晶格。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real etymology notes, real mineral names and real collocations, not invented rhymes.","cn":"正常联想：真实词源注记、真实矿物名称与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Quartz is silicon dioxide; hardness and acid resistance follow from that chemistry.","cn":"石英是二氧化硅；硬度与耐酸性都由此化学性质而来。"},{"en":"Six-sided prisms grow because the lattice repeats in six-fold symmetry.","cn":"六棱柱源于晶格的六重对称重复。"},{"en":"Most sand is quartz that outlasted everything else.","cn":"多数砂是熬过其它矿物的石英。"},{"en":"Quartz watches count the vibration of a quartz plate.","cn":"石英表数的是石英片的振动。"},{"en":"Quartz, quartzite, quartzose, silica, amethyst form one family.","cn":"quartz、quartzite、quartzose、silica、amethyst 构成一个词族。"}],"abstract":[{"en":"Picture a window that is also a stone.","cn":"想象一扇同时是石头的窗。"},{"en":"Picture a tuning fork made of rock, humming at one exact pitch.","cn":"想象一把石头做的音叉，以某个精确音高嗡鸣。"},{"en":"Picture a person you can see through but cannot move.","cn":"想象一个人，你看得透，却推不动。"}]},"examples":[{"en":"A clear quartz crystal glittered among the river pebbles.","cn":"一颗透明石英晶体在河卵石间闪光。"},{"en":"Quartz resists weathering, so it survives as sand long after other minerals decay.","cn":"石英抗风化，因此在其它矿物分解后仍以砂的形式存留。"},{"en":"The vein of quartz carries tiny amounts of gold.","cn":"这条石英脉含有微量黄金。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「夸兹」——透明、坚硬、能报时的石头 → 石英","word":"quartz"},"root":"德语 Quarz，可能来自斯拉夫语表示「坚硬」的形容词（捷克语 tvrdy、波兰语 twardy），再上溯重构的原始斯拉夫语形式；更深印欧语来源有争议。化学成分二氧化硅。","sensesIntro":{"en":"Nine senses move from the mineral's composition to its crystal shape, its sand, its technical uses, its gem forms, its veins, its dust, its industry, and finally to clarity as a character image.","cn":"九个义项从矿物成分走到晶体形态、砂粒、技术用途、宝石形态、矿脉、粉尘、工业，最后落到作为性格意象的清澈。"},"semanticMap":{"core":{"en":"CORE IMAGE: a transparent six-sided crystal catching light among ordinary river pebbles.","cn":"核心意象：一颗透明六棱晶体在普通河卵石之间反光。"},"chain":["SILICA MINERAL","HEXAGONAL CRYSTAL","SAND GRAIN","PIEZOELECTRIC PLATE","GEM VARIETY","CLARITY IMAGE"],"branches":[{"senses":"S1 · S2","en":"COMPOSITION AND FORM: the same silica lattice explains both the mineral's identity and its six-sided shape.","cn":"成分与形态：同一二氧化硅晶格既解释矿物身份，也解释六棱外形。"},{"senses":"S3","en":"SURVIVOR: hardness and acid resistance let quartz outlast other minerals as sand.","cn":"幸存者：硬度与耐酸性让石英以砂的形式熬过其它矿物。"},{"senses":"S4 · S6","en":"SIGNAL AND VEIN: the lattice converts stress into charge, and hot fluids deposit quartz in cracks.","cn":"信号与矿脉：晶格把应力转为电荷，热液则在裂缝中沉淀石英。"},{"senses":"S5 · S8","en":"BEAUTY AND USE: impurities make gems, while cheap pure grains make glass and moulds.","cn":"美与用：杂质造宝石，廉价纯净颗粒则造玻璃与砂型。"},{"senses":"S7 · S9","en":"HARDNESS TWO WAYS: dust cuts lungs, and the same unyielding clarity becomes a human metaphor.","cn":"坚硬的两种方向：粉尘割肺，同样的不屈清澈又成为人的比喻。"}]},"affixes":{"intro":{"en":"Quartz has a small but clear family of mineral and technical derivatives.","cn":"quartz 的词族不大，但矿物与技术派生词脉络清楚。"},"latinIntro":{"en":"Quartz is not Latin in origin; the related technical vocabulary uses Latin silica and Greek krystallos.","cn":"quartz 并非拉丁语来源；相关技术词汇使用拉丁语 silica 与希腊语 krystallos。"},"items":[{"word":"Quarz","structure":"German Quarz, from Middle High German twarc","meaning":"the mineral name","meaningCN":"矿物名","example":"German miners spread the name Quarz.","exampleCN":"德国矿工传播了 Quarz 这个名称。"},{"word":"quartz","structure":"Quarz, borrowed into English","meaning":"silicon dioxide mineral","meaningCN":"二氧化硅矿物；石英","example":"Quartz is hard and resists acid.","exampleCN":"石英坚硬且耐酸。"},{"word":"quartzose","structure":"quartz + -ose (full of)","meaning":"rich in quartz","meaningCN":"富含石英的","example":"The quartzose sandstone is very hard.","exampleCN":"这块石英质砂岩非常坚硬。"},{"word":"quartzite","structure":"quartz + -ite (rock)","meaning":"metamorphic quartz rock","meaningCN":"石英岩","example":"Quartzite forms when sandstone recrystallizes.","exampleCN":"砂岩重结晶时形成石英岩。"},{"word":"quartziferous","structure":"quartz + -ferous (bearing)","meaning":"bearing quartz","meaningCN":"含石英的","example":"A quartziferous vein cuts the limestone.","exampleCN":"一条含石英矿脉切穿石灰岩。"},{"word":"silica","structure":"Latin silex (flint) + -a","meaning":"silicon dioxide","meaningCN":"二氧化硅","example":"Silica is the chemical backbone of quartz.","exampleCN":"二氧化硅是石英的化学骨架。"},{"word":"amethyst","structure":"Greek amethystos (not intoxicated)","meaning":"purple quartz","meaningCN":"紫水晶；紫色石英","example":"Amethyst is quartz with iron colouring.","exampleCN":"紫水晶是含铁致色的石英。"},{"word":"chert","structure":"origin uncertain, perhaps from flint terminology","meaning":"microcrystalline silica rock","meaningCN":"隐晶质二氧化硅岩石；燧石类","example":"Chert has the chemistry of quartz without visible crystals.","exampleCN":"燧石具石英的化学性质，却无可见晶体。"},{"word":"crystal","structure":"Greek krystallos (ice), through Latin","meaning":"a solid with a regular lattice","meaningCN":"具规则晶格的固体；晶体","example":"A quartz crystal has six-fold symmetry.","exampleCN":"石英晶体具六重对称。"}],"latinEntries":[{"word":"silex","structure":"silex, silicis (m./f., third declension)","meaning":"flint, hard stone","meaningCN":"燧石；坚硬石头"},{"word":"silica","structure":"Modern Latin silica, from silex","meaning":"silicon dioxide","meaningCN":"二氧化硅"},{"word":"krystallos","structure":"Greek krystallos (ice, crystal), borrowed into Latin","meaning":"clear crystal","meaningCN":"透明晶体"}]}},{"word":"geography","ipa_uk":"/dʒiˈɒɡrəfi/","ipa_us":"/dʒiˈɑːɡrəfi/","definition_zh":"地理学；某地区的地形与地理状况","definition_en":"the study of the earth's places, environments, and spatial patterns, or the arrangement of features in a region","core_image":"一张铺开的世界地图，山脉、河流与城市以符号标出","scene":"课堂上，老师把一张世界地图展开，让学生找山脉与河流的位置： She studied geography to understand why cities grow along rivers.","sceneCN":"这里 geography 指「研究地表与空间格局的学科」（第 1 个义项：以地球表面、环境与空间分布为对象的学科）；句意为她学地理，是为了理解城市为何沿河生长。","pos":[{"tag":"n.","zh":"地理学；地理状况（学科义不可数，地区状况义可数）"}],"collocations":[{"phrase":"human geography","zh":"人文地理学"},{"phrase":"physical geography","zh":"自然地理学"},{"phrase":"economic geography","zh":"经济地理学"},{"phrase":"a geography lesson","zh":"一堂地理课"},{"phrase":"the geography of the region","zh":"该地区的地理状况"},{"phrase":"study geography","zh":"学习地理"}],"forms":[{"label":"复数（指不同地区的地理状况）","form":"geographies"},{"label":"形容词","form":"geographic"},{"label":"形容词（英式变体）","form":"geographical"},{"label":"从事者","form":"geographer"},{"label":"副词","form":"geographically"}],"derivatives":[{"word":"geographer","pos":"n.","zh":"地理学家"},{"word":"geographic","pos":"adj.","zh":"地理的；地理学的"},{"word":"geographical","pos":"adj.","zh":"地理的（英式常用变体）"},{"word":"geographically","pos":"adv.","zh":"在地理上"},{"word":"geopolitics","pos":"n.","zh":"地缘政治"}],"senses":[{"no":"01","title":"The academic study of places","titleCN":"研究地方与空间的学科","definition":"the discipline that studies the earth's surface, environments, and the spatial organization of human and natural features","definitionCN":"研究地球表面、环境以及人类与自然要素空间组织的学科","example":"She studied geography to understand why cities grow along rivers.","exampleCN":"她学地理，是为了理解城市为何沿河生长。","why":"Geo- means earth and -graphy means writing or description; the subject began as a written account of the known world.","whyCN":"geo- 意为「大地」，-graphy 意为「书写、描述」；这门学科最初是对已知世界的书面记述。"},{"no":"02","title":"The physical arrangement of a region","titleCN":"某地区的地形与地理状况","definition":"the actual layout of landforms, water, climate, and settlement in a particular area","definitionCN":"某一地区地貌、水体、气候与聚落的具体布局","example":"The geography of the valley made the road expensive to build.","exampleCN":"这条山谷的地理状况使修路成本高昂。","why":"The subject and its object share a name: what geography studies is also called its geography.","whyCN":"学科与其对象同名：地理学研究的东西也被称作它的「地理状况」。"},{"no":"03","title":"A school subject","titleCN":"学校课程","definition":"the school subject that teaches maps, places, climates, and peoples","definitionCN":"教授地图、地方、气候与人群的学校科目","example":"Geography was his favourite class because of the maps.","exampleCN":"地理是他最喜欢的课，因为有很多地图。","why":"Once a research field enters the classroom, its name names the lesson as well as the discipline.","whyCN":"研究领域进入课堂后，其名称既指学科，也指课程。"},{"no":"04","title":"Human geography","titleCN":"人文地理","definition":"the branch that studies people, economies, cities, and cultures in space","definitionCN":"研究人、经济、城市与文化在空间中分布的分支","example":"Human geography explains why the border town grew so fast.","exampleCN":"人文地理解释了这座边贸城镇为何发展如此快。","why":"The field split into natural and human halves, and each half keeps the parent name with a qualifier.","whyCN":"该领域分为自然与人文两半，每一半都保留母名并加上限定词。"},{"no":"05","title":"Physical geography","titleCN":"自然地理","definition":"the branch that studies landforms, climate, water, soils, and ecosystems","definitionCN":"研究地貌、气候、水、土壤与生态系统的分支","example":"Physical geography links the mountain range to the rainfall pattern.","exampleCN":"自然地理把山脉与降水格局联系起来。","why":"The physical half keeps the older earth-description tradition, measuring what can be mapped.","whyCN":"自然地理一半延续较早的地表描述传统，测量可被制图的东西。"},{"no":"06","title":"Economic and commercial geography","titleCN":"经济与商业地理","definition":"the study of where production, trade, and markets are located and why","definitionCN":"研究生产、贸易与市场位于何处及其原因","example":"The company hired a specialist in economic geography.","exampleCN":"公司聘请了一位经济地理专家。","why":"Location is a cost, so business needs a map of advantages; geography supplies that map.","whyCN":"位置即成本，企业需要一张优势地图，而地理学提供这张图。"},{"no":"07","title":"The spatial pattern of anything","titleCN":"任何事物的空间格局","definition":"the distribution and arrangement of a phenomenon across space, used figuratively","definitionCN":"某一现象在空间中的分布与排列，作比喻使用","example":"The geography of the market changed when the highway opened.","exampleCN":"高速公路开通后，市场的空间格局改变了。","why":"The metaphor treats abstract advantages as terrain: some places are close, some are distant, and the shape matters.","whyCN":"这一比喻把抽象优势当作地形：有的地方近，有的地方远，形状很重要。"},{"no":"08","title":"A written description of the earth","titleCN":"对地球的书面描述（历史义）","definition":"the older sense of a written account of lands, peoples, and natural features","definitionCN":"较古老的含义：对土地、民族与自然特征的书面记述","example":"The old geography described coasts the author had never seen.","exampleCN":"那部旧地理志描述了作者从未见过的海岸。","why":"-Graphy is 'writing', so geography first meant earth-writing before it meant earth-science.","whyCN":"-graphy 是「书写」，因此 geography 先指「书写大地」，后指「地球科学」。"},{"no":"09","title":"Abstract: the lay of the land","titleCN":"抽象义：局势的地形","definition":"the overall shape of a situation, including its high ground and obstacles","definitionCN":"某一局势的整体形状，包括其高地与障碍","example":"Before the negotiation, they studied the geography of the room.","exampleCN":"谈判前，他们研究了这间屋子里的局势地形。","why":"Politics borrows terrain words because advantage depends on position; the metaphor turns interests into landscape.","whyCN":"政治借用 terrain 类词，因为优势取决于位置；比喻把利益关系变成地貌。"}],"etymology":{"intro":{"en":"Geography comes from Greek through Latin, literally 'earth-writing'. The Greek elements are clear; the origin of ge is not. Dates are approximate.","cn":"geography 经拉丁语来自希腊语，字面是「书写大地」。希腊语素清楚，但 ge 的来源不明。年代均为约数。"},"items":[{"era":"GREEK GE","en":"Ge meant 'earth, land'. Its origin is uncertain and it is often treated as a pre-Greek word, so proposed Indo-European roots are reconstructions.","cn":"ge 意为「大地、土地」。其来源不确定，常被视为前希腊语词，因此为它提出的印欧词根都属重构形式。"},{"era":"GREEK GRAPHEIN","en":"Graphein meant 'to write, draw, scratch'. Geography is earth-writing, a description rather than an experiment.","cn":"graphein 意为「写、画、刻」。geography 就是「书写大地」，是描述而非实验。"},{"era":"GREEK GEOGRAPHIA","en":"Geographia named a written description of the inhabited world, as in the title of Ptolemy's work.","cn":"geographia 指对已知有人居住世界的书面描述，托勒密著作的标题即用此词。"},{"era":"LATIN GEOGRAPHIA","en":"Latin kept the Greek word, and English borrowed it in the fifteenth century for descriptions of lands and peoples.","cn":"拉丁语保留了这个希腊词，英语在 15 世纪借入，用于描述土地与民族。"},{"era":"MODERN DISCIPLINE","en":"In the nineteenth century geography became a university discipline with physical and human branches; the exact founding date varies by country.","cn":"19 世纪地理学成为设有自然与人文分支的大学学科，其确切创立年代因国而异。"}]},"similar":{"note":{"en":"Group one holds forms and near-spellings from the same Greek stock; group two holds fields and words often confused with geography.","cn":"第一组是同出希腊语词干的形式与近拼写词；第二组是常与地理学混淆的学科与词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geographic","ipa":"/dʒiəˈɡræfɪk/","tag":"adjective","definition":"Relating to geography; it describes a distribution or feature rather than naming the discipline.","definitionCN":"与地理学相关的；它描述分布或特征，而非命名学科。"},{"word":"geographer","ipa":"/dʒiˈɒɡrəfə/","tag":"person","definition":"A person who studies geography; the -er ending marks the practitioner.","definitionCN":"研究地理学的人；-er 结尾标记从业者。"},{"word":"geology","ipa":"/dʒiˈɒlədʒi/","tag":"different suffix","definition":"The study of rocks and the earth's interior; geography studies surface places, not deep structure.","definitionCN":"研究岩石与地球内部的学科；地理学研究地表地方，而非深部结构。"},{"word":"geography","ipa":"/dʒiˈɒɡrəfi/","tag":"the discipline","definition":"The subject itself; the ending -graphy marks description, while -logy would mark reasoned study.","definitionCN":"学科本身；-graphy 结尾标记「描述」，而 -logy 标记「理性研究」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"topography","ipa":"/təˈpɒɡrəfi/","tag":"surface relief","definition":"The detailed arrangement of surface features, especially elevation; geography is the broader study.","definitionCN":"地表特征尤其是高程的细致排列；地理学是更广的研究。"},{"word":"cartography","ipa":"/kɑːˈtɒɡrəfi/","tag":"map-making","definition":"The art and science of making maps; it is a tool of geography, not the whole field.","definitionCN":"制作地图的艺术与科学；它是地理学的工具，而非整个领域。"},{"word":"geopolitics","ipa":"/ˌdʒiːəˈpɒlətɪks/","tag":"political field","definition":"The study of how location and resources shape politics; it applies geography to power.","definitionCN":"研究位置与资源如何塑造政治；它把地理学应用于权力。"},{"word":"environmental science","ipa":"/ɪnˌvaɪrənˈmentl ˈsaɪəns/","tag":"neighbouring field","definition":"An interdisciplinary study of ecosystems and pollution; geography overlaps it but keeps space central.","definitionCN":"研究生态系统与污染的交叉学科；地理学与之重叠，但始终以空间为中心。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek morphemes, real academic terms and real collocations, not invented rhymes.","cn":"正常联想：真实希腊语素、真实学科术语与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Geo- is earth; -graphy is writing: geography is earth-writing.","cn":"geo- 是大地，-graphy 是书写：geography 就是书写大地。"},{"en":"The family runs geography, geographer, geographic, geographical, geographically.","cn":"词族包括 geography、geographer、geographic、geographical、geographically。"},{"en":"Geography splits into physical and human halves.","cn":"地理学分为自然与人文两半。"},{"en":"Maps are its signature tool, but spatial reasoning is its method.","cn":"地图是它的标志工具，空间推理则是它的方法。"},{"en":"Geography and geology differ: surface places versus deep rocks.","cn":"geography 与 geology 不同：前者管地表地方，后者管深部岩石。"}],"abstract":[{"en":"Picture a chessboard where the squares themselves change shape.","cn":"想象一张棋盘，格子本身还会改变形状。"},{"en":"Picture a room whose walls decide who can hear whom.","cn":"想象一间屋子，墙壁决定谁能听见谁。"},{"en":"Picture a market drawn as a landscape of hills and rivers.","cn":"想象一个市场被画成山丘与河流构成的地貌。"}]},"examples":[{"en":"She studied geography to understand why cities grow along rivers.","cn":"她学地理，是为了理解城市为何沿河生长。"},{"en":"The geography of the island keeps its villages close to the coast.","cn":"这座岛的地理状况使村庄都靠近海岸。"},{"en":"Economic geography explains where factories cluster.","cn":"经济地理解释工厂为何聚集在某些地方。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「geo（大地）+ graphy（书写）」——把大地的样子写下来 → 地理学","word":"geography"},"root":"拉丁语 geographia，来自希腊语 geographia = ge「大地」+ graphein「书写、描画」。ge 的来源不确定，常视为前希腊语词；graphein 的词根清楚。","sensesIntro":{"en":"Nine senses move from the discipline to its object, its classroom, its branches, its business use, its spatial metaphor, its old descriptive sense, and finally to the shape of any situation.","cn":"九个义项从学科走到其对象、课堂、分支、商业用途、空间比喻、古老描述义，最后落到任何局势的形状。"},"semanticMap":{"core":{"en":"CORE IMAGE: a world map spread open, its mountains, rivers and cities marked with symbols.","cn":"核心意象：一张铺开的世界地图，山脉、河流与城市用符号标出。"},"chain":["EARTH-WRITING","ACADEMIC FIELD","REGIONAL LAYOUT","SCHOOL SUBJECT","SPATIAL PATTERN","LAY OF THE LAND"],"branches":[{"senses":"S1 · S8","en":"WRITING AND STUDY: description of the earth grew into a disciplined study of it.","cn":"书写与研究：对地球的描述发展为对它的系统研究。"},{"senses":"S2 · S3","en":"FIELD AND CLASSROOM: the same name covers the researcher's object and the pupil's lesson.","cn":"研究对象与课堂：同一名称既指研究者的对象，也指学生的课程。"},{"senses":"S4 · S5","en":"TWO HALVES: human and physical branches divide the field without replacing its name.","cn":"两半：人文与自然分支把领域分开，却未取代其名称。"},{"senses":"S6 · S7","en":"LOCATION AS VALUE: business and metaphor both read space as advantage and cost.","cn":"位置即价值：商业与比喻都把空间读作优势与成本。"},{"senses":"S9","en":"ROOM AS TERRAIN: a situation acquires high ground, obstacles and distance.","cn":"房间即地形：局势也有了高地、障碍与距离。"}]},"affixes":{"intro":{"en":"Geography is built from two productive Greek elements, and its derivatives fill out a whole academic family.","cn":"geography 由两个多产的希腊语素构成，其派生词撑起整个学术词族。"},"latinIntro":{"en":"Latin geographia is the borrowed form; Greek ge and graphein are the ultimate elements.","cn":"拉丁语 geographia 是借入形式；希腊语 ge 与 graphein 是最终语素。"},"items":[{"word":"ge-","structure":"Greek ge (earth, land)","meaning":"earth","meaningCN":"大地","example":"Ge- opens geography, geology and geometry.","exampleCN":"ge- 出现在 geography、geology 与 geometry 开头。"},{"word":"-graphy","structure":"Greek graphein (to write, draw) + -ia","meaning":"writing, description","meaningCN":"书写；描述","example":"-Graphy appears in biography and cartography.","exampleCN":"-graphy 见于 biography 与 cartography。"},{"word":"geography","structure":"geo- + -graphy","meaning":"earth description","meaningCN":"对地球的描述；地理学","example":"Geography studies places and spatial patterns.","exampleCN":"地理学研究地方与空间格局。"},{"word":"geographer","structure":"geography + -er (person who)","meaning":"a person who studies places","meaningCN":"研究地方的人；地理学家","example":"The geographer mapped the flood plain.","exampleCN":"地理学家绘制了洪泛区地图。"},{"word":"geographic","structure":"geography + -ic (relating to)","meaning":"relating to geography","meaningCN":"地理的；地理学的","example":"The two towns show a sharp geographic contrast.","exampleCN":"两座城镇呈现鲜明的地理对比。"},{"word":"geographical","structure":"geographic + -al (relating to)","meaning":"the fuller adjective form","meaningCN":"较完整的地理形容词形式","example":"The society publishes geographical surveys.","exampleCN":"该学会出版地理调查报告。"},{"word":"geographically","structure":"geographical + -ly (in a manner)","meaning":"in geographical terms","meaningCN":"在地理上","example":"The country is geographically isolated.","exampleCN":"这个国家在地理上很孤立。"},{"word":"geology","structure":"geo- + -logy (study of)","meaning":"study of the earth's rocks","meaningCN":"研究地球岩石的学科；地质学","example":"Geology studies the deep structure, not just the surface.","exampleCN":"地质学研究深部结构，而不只是地表。"},{"word":"geopolitics","structure":"geo- + politics","meaning":"politics shaped by location","meaningCN":"受位置塑造的政治；地缘政治","example":"Geopolitics treats borders as geography.","exampleCN":"地缘政治把边界当作地理。"}],"latinEntries":[{"word":"geographia","structure":"geographia (f., first declension), from Greek","meaning":"description of the earth","meaningCN":"对地球的描述；地理志"},{"word":"ge","structure":"Greek ge (f.)","meaning":"earth, land","meaningCN":"大地；土地"},{"word":"graphein","structure":"Greek graphein (verb)","meaning":"to write, draw","meaningCN":"书写；描画"}]}},{"word":"geographic","ipa_uk":"/dʒiəˈɡræfɪk/","ipa_us":"/dʒiəˈɡræfɪk/","definition_zh":"地理的；与地理学或地理位置有关的","definition_en":"relating to geography, or to the physical location and distribution of places and features","core_image":"同一张地图上，两片相距很远的区域被同一种颜色标出","scene":"考察队把不同地点的气温与降水标在同一张表上，比较南北差异： The team compared the crop yields of two geographic regions.","sceneCN":"这里 geographic 指「地理上的、与地理位置有关的」（第 3 个义项：分布在不同地域的）；句意为考察队比较了两个地理区域的作物产量。","pos":[{"tag":"adj.","zh":"地理的；地理学的；地理位置的"}],"collocations":[{"phrase":"geographic region","zh":"地理区域"},{"phrase":"geographic distribution","zh":"地理分布"},{"phrase":"geographic information system","zh":"地理信息系统"},{"phrase":"geographic variation","zh":"地理变异"},{"phrase":"geographic isolation","zh":"地理隔离"},{"phrase":"geographic coordinates","zh":"地理坐标"}],"forms":[{"label":"副词","form":"geographically"},{"label":"名词（学科）","form":"geography"},{"label":"名词（从业者）","form":"geographer"},{"label":"形容词（完整变体）","form":"geographical"},{"label":"比较级（较少用）","form":"more geographic"}],"derivatives":[{"word":"geography","pos":"n.","zh":"地理学；地理状况"},{"word":"geographer","pos":"n.","zh":"地理学家"},{"word":"geographical","pos":"adj.","zh":"地理的（完整变体）"},{"word":"geographically","pos":"adv.","zh":"在地理上"},{"word":"geospatial","pos":"adj.","zh":"地理空间的"}],"senses":[{"no":"01","title":"Relating to the discipline of geography","titleCN":"与地理学科有关的","definition":"belonging to geography as a field of study, including its methods and concepts","definitionCN":"属于作为研究领域的地理学，包括其方法与概念","example":"The paper applies geographic methods to the study of migration.","exampleCN":"这篇论文把地理学方法用于移民研究。","why":"The adjective simply attaches the discipline to a noun: geographic methods are the methods geography uses.","whyCN":"这个形容词只是把学科附着到名词上：地理方法就是地理学所用的方法。"},{"no":"02","title":"Relating to physical location","titleCN":"与地理位置有关的","definition":"concerning where a place or feature actually lies on the earth","definitionCN":"关于某地或某要素在地球上的实际位置","example":"The two factories have the same geographic position but different markets.","exampleCN":"两家工厂地理位置相同，市场却不同。","why":"Location is the field's most basic variable, so the adjective often answers the question 'where exactly?'","whyCN":"位置是该学科最基本的变量，因此这个形容词常回答「究竟在哪里」。"},{"no":"03","title":"Spread across regions","titleCN":"分布于不同地域的","definition":"distributed or varying across a territory rather than confined to one point","definitionCN":"在一整片地域内分布或变化，而非局限于一点","example":"The team compared the crop yields of two geographic regions.","exampleCN":"考察队比较了两个地理区域的作物产量。","why":"Once a phenomenon is mapped, it becomes a geographic pattern: differences arranged in space.","whyCN":"一旦某现象被制图，它就成了地理格局：差异在空间中的排列。"},{"no":"04","title":"Of coordinates and map systems","titleCN":"地理坐标与地图系统的","definition":"describing positions by latitude, longitude, or another earth-referenced grid","definitionCN":"以纬度、经度或其它地球参照网格描述位置","example":"Geographic coordinates place the wreck within a few metres.","exampleCN":"地理坐标把沉船位置精确到几米之内。","why":"A map needs a grid tied to the earth itself, and the adjective marks that earth-referenced system.","whyCN":"地图需要一套绑定地球本身的网格，这个形容词标记的正是这种地球参照系统。"},{"no":"05","title":"Regional biological variation","titleCN":"生物的地理变异","definition":"differences among populations that arise from their separation in space","definitionCN":"种群因空间分隔而产生的差异","example":"Geographic variation in wing length follows the winter temperature.","exampleCN":"翅长的地理变异与冬季温度相关。","why":"Distance limits interbreeding, so space becomes a cause of biological difference.","whyCN":"距离限制交配，因此空间本身成为生物差异的原因。"},{"no":"06","title":"Geographic isolation in evolution","titleCN":"进化中的地理隔离","definition":"separation of populations by distance, mountains, or water that blocks gene flow","definitionCN":"因距离、山脉或水域阻断基因流而造成的种群分隔","example":"Geographic isolation split the bird into two species.","exampleCN":"地理隔离把这种鸟分成两个物种。","why":"Speciation needs interrupted gene flow, and geography is the most common interruption.","whyCN":"物种形成需要被中断的基因流，而地理是最常见的中断者。"},{"no":"07","title":"Commercial regional segmentation","titleCN":"商业上的区域划分","definition":"relating to a market or service area defined by location","definitionCN":"与按位置划定的市场或服务区域有关","example":"The company treats each province as a separate geographic market.","exampleCN":"公司把每个省视为独立的地理市场。","why":"Business borrows the map to divide customers, so 'geographic' becomes a management category.","whyCN":"企业借用地图来划分客户，于是「地理的」成为管理类别。"},{"no":"08","title":"Abstract: spatially organized","titleCN":"抽象义：按空间组织起来的","definition":"arranged according to relative position, distance, or neighbourhood rather than by list order","definitionCN":"按相对位置、距离或邻近关系而非列表顺序组织","example":"The archive is organized on a geographic principle, shelf by shelf.","exampleCN":"档案按地理原则逐架排列。","why":"The metaphor extends the adjective from earth-space to any space in which nearness matters.","whyCN":"这一比喻把形容词从地球空间扩展到任何「远近有意义」的空间。"}],"etymology":{"intro":{"en":"Geographic comes from Greek through Latin, the adjective of geography. Its elements are well recorded. Dates are approximate.","cn":"geographic 经拉丁语来自希腊语，是 geography 的形容词。其语素书证充分。年代均为约数。"},"items":[{"era":"GREEK GE","en":"Ge meant 'earth'. Its deeper origin is uncertain and often treated as pre-Greek, so proposed roots are reconstructions.","cn":"ge 意为「大地」。其更深来源不确定，常被视为前希腊语词，因此所提词根均属重构形式。"},{"era":"GREEK GRAPHIKOS","en":"Graphikos meant 'of writing or drawing', from graphein 'to write'. Geographikos described what belongs to earth-writing.","cn":"graphikos 意为「书写或描画的」，来自 graphein「写」。geographikos 指属于「书写大地」之物。"},{"era":"LATIN GEOGRAPHICUS","en":"Late Latin geographicus borrowed the Greek adjective, and English took it as geographic.","cn":"晚期拉丁语 geographicus 借入这个希腊形容词，英语再借为 geographic。"},{"era":"SCIENTIFIC USE","en":"The adjective expanded with exploration and cartography, attaching to maps, coordinates, and distributions.","cn":"这个形容词随探险与制图扩展，附着于地图、坐标与分布。"},{"era":"MODERN FIELDS","en":"Twentieth-century terms such as geographic information system gave the word new technical homes; first dates for these compounds vary.","cn":"20 世纪的地理信息系统等术语为这个词提供了新的技术落点，这些复合词的首见年代各不相同。"}]},"similar":{"note":{"en":"Group one holds adjectives and nouns from the same Greek stock that are easily swapped; group two holds spatial adjectives with a different scope.","cn":"第一组是同出希腊语词干、极易互换的形容词与名词；第二组是范围不同的空间形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geographical","ipa":"/ˌdʒiəˈɡræfɪkl/","tag":"fuller variant","definition":"The longer adjective with the same meaning; British usage often prefers it, while American usage shortens it.","definitionCN":"意义相同的较长形容词；英式常用它，美式则常用较短形式。"},{"word":"geography","ipa":"/dʒiˈɒɡrəfi/","tag":"noun","definition":"The discipline or a region's layout; geographic is the adjective that points back to it.","definitionCN":"学科或地区布局；geographic 是指回它的形容词。"},{"word":"geographer","ipa":"/dʒiˈɒɡrəfə/","tag":"person","definition":"A person who practises geography; it is a noun, so it cannot modify another noun the way geographic does.","definitionCN":"从事地理学的人；它是名词，不能像 geographic 那样修饰另一名词。"},{"word":"geologic","ipa":"/dʒiəˈlɒdʒɪk/","tag":"one letter away","definition":"Relating to geology, the study of rocks; the ending -logic replaces -graphic and changes the field.","definitionCN":"与地质学相关的；结尾 -logic 替换 -graphic，学科随之改变。"}]},{"heading":"NEAR MEANING","entries":[{"word":"spatial","ipa":"/ˈspeɪʃl/","tag":"broader","definition":"Relating to space in general, including rooms and layouts; geographic is tied specifically to the earth's surface.","definitionCN":"泛指空间，包括房间与布局；geographic 特指地球表面。"},{"word":"regional","ipa":"/ˈriːdʒənl/","tag":"area-based","definition":"Relating to a named region; it need not involve geographic analysis or coordinates.","definitionCN":"与某一命名区域相关；不必涉及地理分析或坐标。"},{"word":"territorial","ipa":"/ˌterɪˈtɔːriəl/","tag":"political","definition":"Relating to territory claimed or controlled by a state; it adds political control to mere location.","definitionCN":"与国家主张或控制的领土有关；在单纯位置上叠加政治控制。"},{"word":"topographic","ipa":"/təˈpɒɡræfɪk/","tag":"surface detail","definition":"Relating to the detailed shape and elevation of the surface; geographic is wider and includes human patterns.","definitionCN":"与地表详细形状和高程有关；geographic 范围更广，还包括人类格局。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek morphemes, real technical terms and real collocations, not invented rhymes.","cn":"正常联想：真实希腊语素、真实技术术语与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Geography is the noun; geographic is the adjective; geographically is the adverb.","cn":"geography 是名词，geographic 是形容词，geographically 是副词。"},{"en":"Geographic distribution is the standard phrase for where a species occurs.","cn":"geographic distribution 是描述物种分布范围的标准短语。"},{"en":"Geographic isolation is a standard cause of speciation.","cn":"地理隔离是物种形成的标准成因。"},{"en":"A geographic information system links data to coordinates.","cn":"地理信息系统把数据与坐标关联起来。"},{"en":"Do not confuse geographic with geologic: surface places versus deep rocks.","cn":"不要把 geographic 与 geologic 混淆：前者是地表地方，后者是深部岩石。"}],"abstract":[{"en":"Picture a colour that changes the moment you cross a border line.","cn":"想象一种颜色，越过边界线的瞬间就改变。"},{"en":"Picture two identical houses that behave differently because of where they stand.","cn":"想象两栋一模一样的房子，因所处位置不同而表现不同。"},{"en":"Picture a library shelved by distance instead of by title.","cn":"想象一座按距离而非书名排列的图书馆。"}]},"examples":[{"en":"The team compared the crop yields of two geographic regions.","cn":"考察队比较了两个地理区域的作物产量。"},{"en":"Geographic isolation allowed the island population to diverge.","cn":"地理隔离使岛上种群得以分化。"},{"en":"The map stores every record with geographic coordinates.","cn":"地图用地理坐标存储每一条记录。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「geo（大地）+ graphic（描绘的）」——描绘大地的 → 地理的","word":"geographic"},"root":"拉丁语 geographicus，来自希腊语 geographikos = ge「大地」+ graphein「书写、描画」+ -ikos「……的」。ge 更深来源不确定；graphein 词根清楚。","sensesIntro":{"en":"Eight senses spread from the academic field to location, regional distribution, coordinates, biological variation, isolation, market segmentation, and to any space-based order.","cn":"八个义项从学术领域扩展到位置、区域分布、坐标、生物变异、隔离、市场划分，最后到任何以空间为依据的秩序。"},"semanticMap":{"core":{"en":"CORE IMAGE: one map on which two distant regions are marked with the same symbol.","cn":"核心意象：同一张地图上，两个相距很远的区域被标以相同符号。"},"chain":["OF GEOGRAPHY","OF LOCATION","REGIONAL SPREAD","COORDINATE SYSTEM","BIOLOGICAL VARIATION","SPATIAL ORDER"],"branches":[{"senses":"S1 · S2","en":"FIELD AND POSITION: the adjective can point to the discipline or to the simple fact of where something lies.","cn":"学科与位置：这个形容词既可指学科，也可指某物所在的位置这一简单事实。"},{"senses":"S3 · S7","en":"DISTRIBUTION AND MARKET: mapping a phenomenon and dividing a market both turn space into a category.","cn":"分布与市场：给现象制图与划分市场，都把空间变成分类依据。"},{"senses":"S4","en":"GRID: latitude and longitude tie every place to a common reference frame.","cn":"网格：经纬度把每个地点绑定到共同参照系。"},{"senses":"S5 · S6","en":"DISTANCE AS CAUSE: separation produces variation and, eventually, new species.","cn":"距离即原因：分隔产生变异，最终产生新物种。"},{"senses":"S8","en":"NEARNESS AS ORDER: any arrangement in which proximity matters can be called geographic.","cn":"邻近即秩序：任何以远近为要义的排列都可称作地理的。"}]},"affixes":{"intro":{"en":"The adjective is assembled from the same two Greek elements as the noun, plus an adjective ending.","cn":"这个形容词由与名词相同的两个希腊语素加形容词词尾构成。"},"latinIntro":{"en":"Latin geographicus and Greek geographikos stand behind the English adjective; ge and graphein are the ultimate elements.","cn":"拉丁语 geographicus 与希腊语 geographikos 支撑这个英语形容词；ge 与 graphein 是最终语素。"},"items":[{"word":"ge-","structure":"Greek ge (earth)","meaning":"earth","meaningCN":"大地","example":"Ge- marks earth-based sciences.","exampleCN":"ge- 标记以大地为基础的科学。"},{"word":"-graphic","structure":"Greek graphein (write) + -ikos","meaning":"relating to writing or drawing","meaningCN":"与书写或描画有关的","example":"-Graphic appears in geographic and photographic.","exampleCN":"-graphic 见于 geographic 与 photographic。"},{"word":"geography","structure":"geo- + -graphy","meaning":"earth description","meaningCN":"对地球的描述；地理学","example":"Geography is the noun behind the adjective.","exampleCN":"geography 是这个形容词背后的名词。"},{"word":"geographic","structure":"geo- + -graphic","meaning":"relating to geography","meaningCN":"地理的；地理学的","example":"The study covers a wide geographic range.","exampleCN":"这项研究覆盖很广的地理范围。"},{"word":"geographical","structure":"geographic + -al (relating to)","meaning":"the longer adjective","meaningCN":"较长的形容词形式","example":"Geographical names often preserve older languages.","exampleCN":"地名常保存更古老的语言。"},{"word":"geographically","structure":"geographical + -ly (in a manner)","meaning":"in spatial terms","meaningCN":"在地理上；从空间角度","example":"The species is geographically split into two groups.","exampleCN":"该物种在地理上分为两个群体。"},{"word":"geographer","structure":"geography + -er (person who)","meaning":"a student of places","meaningCN":"研究地方的人；地理学家","example":"A geographer prepared the regional atlas.","exampleCN":"一位地理学家编制了区域图集。"},{"word":"geospatial","structure":"geo- + spatial","meaning":"relating to geographic space and data","meaningCN":"地理空间的；与空间数据有关的","example":"Geospatial data combine maps with statistics.","exampleCN":"地理空间数据把地图与统计结合。"}],"latinEntries":[{"word":"geographia","structure":"geographia (f., first declension), from Greek","meaning":"description of the earth","meaningCN":"对地球的描述"},{"word":"geographicus","structure":"Late Latin geographicus, from Greek geographikos","meaning":"of earth-description","meaningCN":"属于描述大地的"},{"word":"graphein","structure":"Greek graphein (verb)","meaning":"to write, draw","meaningCN":"书写；描画"}]}},{"word":"geographer","ipa_uk":"/dʒiˈɒɡrəfə/","ipa_us":"/dʒiˈɑːɡrəfər/","definition_zh":"地理学家；研究地理的人","definition_en":"a person who studies geography, especially its spatial patterns, environments, or maps","core_image":"一位背着测量仪的人沿河谷行走，边看地形边记录","scene":"一位研究者背着测量仪沿河谷行走，每到一处就记录河道宽度与坡度： A geographer walked the valley, recording the width and slope of the river.","sceneCN":"这里 geographer 指「研究地理的人；地理学家」（第 1 个义项：以地理学为业的人）；句意为一位地理学家沿河谷行走，记录河宽与坡度。","pos":[{"tag":"n.","zh":"地理学家；地理研究者（可数，复数为 geographers）"}],"collocations":[{"phrase":"a physical geographer","zh":"自然地理学家"},{"phrase":"a human geographer","zh":"人文地理学家"},{"phrase":"an economic geographer","zh":"经济地理学家"},{"phrase":"geographer and mapmaker","zh":"地理学家兼制图者"},{"phrase":"a team of geographers","zh":"一组地理学家"},{"phrase":"the geographer's field notes","zh":"地理学家的野外笔记"}],"forms":[{"label":"复数","form":"geographers"},{"label":"名词（学科）","form":"geography"},{"label":"形容词","form":"geographic"},{"label":"形容词（变体）","form":"geographical"},{"label":"副词（由形容词派生）","form":"geographically"}],"derivatives":[{"word":"geography","pos":"n.","zh":"地理学；地理状况"},{"word":"geographic","pos":"adj.","zh":"地理的"},{"word":"geographical","pos":"adj.","zh":"地理的（变体）"},{"word":"geographically","pos":"adv.","zh":"在地理上"},{"word":"geocartography","pos":"n.","zh":"地理制图"}],"senses":[{"no":"01","title":"A person who studies geography","titleCN":"研究地理学的人","definition":"a scholar or professional whose field is the study of places, environments, and spatial patterns","definitionCN":"以地方、环境与空间格局为研究领域的学者或专业人员","example":"A geographer walked the valley, recording the width and slope of the river.","exampleCN":"一位地理学家沿河谷行走，记录河宽与坡度。","why":"The -er ending marks the practitioner, so geographer is simply 'one who does geography'.","whyCN":"-er 结尾标记从业者，因此 geographer 就是「做地理学的人」。"},{"no":"02","title":"A physical geographer","titleCN":"自然地理学家","definition":"a geographer who studies landforms, climate, water, soils, or ecosystems","definitionCN":"研究地貌、气候、水、土壤或生态系统的地理学家","example":"The physical geographer measured how the glacier had retreated.","exampleCN":"这位自然地理学家测量了冰川退缩的距离。","why":"The field divides, and each specialist carries the parent job title with an adjective.","whyCN":"学科分支化后，每位专家都在母职称前加一个形容词。"},{"no":"03","title":"A historical mapmaker","titleCN":"历史上的制图者","definition":"an early geographer whose work was chiefly describing coasts and drawing maps","definitionCN":"工作主要是描述海岸与绘制地图的早期地理工作者","example":"The geographer drew a coast that later explorers corrected.","exampleCN":"这位地理学家画出的海岸线后来被探险者修正。","why":"Before geography became a university science, its practitioners were often mapmakers and compilers.","whyCN":"在地理学成为大学科学之前，其实践者往往是制图者与编纂者。"},{"no":"04","title":"A human geographer","titleCN":"人文地理学家","definition":"a geographer who studies cities, economies, cultures, or migration","definitionCN":"研究城市、经济、文化或迁移的地理学家","example":"The human geographer interviewed families who had moved inland.","exampleCN":"这位人文地理学家访谈了迁往内陆的家庭。","why":"People also make spatial patterns, so the same job title covers the study of settlements and movement.","whyCN":"人同样制造空间格局，因此同一职称也涵盖聚落与迁移研究。"},{"no":"05","title":"A regional describer","titleCN":"区域描述者","definition":"someone who systematically describes the lands, peoples, and resources of a region","definitionCN":"系统描述某一地区土地、人群与资源的人","example":"The geographer wrote a full account of the province's rivers.","exampleCN":"这位地理学家写下了该省河流的完整记述。","why":"The oldest sense is descriptive: to write down what is there, region by region.","whyCN":"最古老的含义是描述性的：一个地区一个地区地写下那里有什么。"},{"no":"06","title":"A geography teacher","titleCN":"地理教师","definition":"a teacher who instructs students in geography","definitionCN":"向学生教授地理学的教师","example":"The geographer at the school ran the map club.","exampleCN":"学校里的地理老师负责地图社团。","why":"A discipline's name plus -er can also name the person who teaches it, especially in school usage.","whyCN":"学科名加 -er 也可指教授它的人，尤其在学校语境中。"},{"no":"07","title":"A GIS or remote-sensing specialist","titleCN":"地理信息系统或遥感专业人员","definition":"a geographer whose work uses satellite data, digital maps, and spatial analysis","definitionCN":"使用卫星数据、数字地图与空间分析工作的地理学家","example":"The geographer turned satellite images into a flood-risk map.","exampleCN":"这位地理学家把卫星影像转成洪水风险图。","why":"New instruments change the job while the old title stays, so geographer now includes digital mapping.","whyCN":"新工具改变工作内容，旧职称却保留，因此地理学家如今也包括数字制图。"},{"no":"08","title":"Figurative: a person who knows a place","titleCN":"抽象义：熟悉某地格局的人","definition":"someone who understands the layout and social map of a place very well","definitionCN":"非常了解某地布局与社会地图的人","example":"As a geographer of the city, she knew every shortcut and every border.","exampleCN":"作为熟悉这座城市的人，她知道每条捷径与每条边界。","why":"The metaphor promotes anyone with deep spatial knowledge to the rank of a geographer.","whyCN":"这一比喻把任何具备深厚空间知识的人提升到「地理学家」的位置。"}],"etymology":{"intro":{"en":"Geographer comes from Greek through Latin, meaning 'one who writes about the earth'. The elements are clear; the deeper origin of ge is not. Dates are approximate.","cn":"geographer 经拉丁语来自希腊语，意为「书写大地的人」。语素清楚，但 ge 的更深来源不明。年代均为约数。"},"items":[{"era":"GREEK GEOGRAPHOS","en":"Geographos meant 'one who describes the earth', built on ge 'earth' and graphein 'to write'.","cn":"geographos 意为「描述大地的人」，由 ge「大地」与 graphein「书写」构成。"},{"era":"GREEK GE","en":"The element ge is of uncertain origin and is often regarded as pre-Greek; any Indo-European root offered for it is a reconstruction.","cn":"语素 ge 来源不确定，常被视为前希腊语词；为它提出的任何印欧词根都属重构形式。"},{"era":"LATIN GEOGRAPHUS","en":"Latin borrowed geographus for a writer on geography, and English took the word through French in the sixteenth century.","cn":"拉丁语借入 geographus 指地理著述者，英语在 16 世纪经法语借入。"},{"era":"PROFESSIONAL SENSE","en":"As geography became a university subject, geographer shifted from a writer of descriptions to a trained researcher.","cn":"随着地理学成为大学学科，geographer 从描述写作者转为受过训练的研究者。"},{"era":"TECHNICAL SENSE","en":"Satellite and digital mapping added new roles in the twentieth century; the first use of geographer for these specialists is not precisely dated.","cn":"卫星与数字制图在 20 世纪增添了新角色，地理学家用于指这些专家的最早年代没有精确记载。"}]},"similar":{"note":{"en":"Group one holds job and subject words from the same Greek stock; group two holds specialists in neighbouring fields.","cn":"第一组是同出希腊语词干的职业与学科词；第二组是相邻领域的专家。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geography","ipa":"/dʒiˈɒɡrəfi/","tag":"the subject","definition":"The field itself; geographer is the person who practises it.","definitionCN":"学科本身；geographer 是从事它的人。"},{"word":"geographic","ipa":"/dʒiəˈɡræfɪk/","tag":"adjective","definition":"Relating to geography; it modifies nouns but does not name a person.","definitionCN":"与地理学有关；它修饰名词，但不指人。"},{"word":"geographical","ipa":"/ˌdʒiəˈɡræfɪkl/","tag":"longer adjective","definition":"The fuller adjective variant; it never replaces the noun for a person.","definitionCN":"较长的形容词变体；它不能替代指人的名词。"},{"word":"geology","ipa":"/dʒiˈɒlədʒi/","tag":"different field","definition":"The study of rocks and earth structure; its practitioner is a geologist, not a geographer.","definitionCN":"研究岩石与地球结构的学科；其从业者是 geologist，而非 geographer。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cartographer","ipa":"/kɑːˈtɒɡrəfə/","tag":"map specialist","definition":"A person who designs and draws maps; many geographers map, but cartography is a distinct skill.","definitionCN":"设计并绘制地图的人；许多地理学家会制图，但制图是一门独立技能。"},{"word":"geologist","ipa":"/dʒiˈɒlədʒɪst/","tag":"rock specialist","definition":"A person who studies rocks, minerals, and the earth's interior rather than surface places.","definitionCN":"研究岩石、矿物与地球内部而非地表地方的人。"},{"word":"surveyor","ipa":"/səˈveɪə/","tag":"measurement","definition":"A person who measures land boundaries and elevations; the work supplies data that geographers use.","definitionCN":"测量土地边界与高程的人；其工作为地理学家提供数据。"},{"word":"explorer","ipa":"/ɪkˈsplɔːrə/","tag":"travel and record","definition":"A person who travels into unknown regions; early explorers often supplied geography with its descriptions.","definitionCN":"进入未知地区旅行的人；早期探险者常为地理学提供描述材料。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek morphemes, real professions and real collocations, not invented rhymes.","cn":"正常联想：真实希腊语素、真实职业与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Geography is the field; geographer is the person; geographic is the adjective.","cn":"geography 是学科，geographer 是人，geographic 是形容词。"},{"en":"The -er ending marks the practitioner, as in teacher and mapper.","cn":"-er 结尾标记从业者，如 teacher 与 mapper。"},{"en":"A geographer may be physical, human, economic, or digital.","cn":"地理学家可以是自然的、人文的、经济的或数字的。"},{"en":"Early geographers were often mapmakers and regional describers.","cn":"早期地理学家往往是制图者与区域描述者。"},{"en":"The Greek source geographos literally means earth-writer.","cn":"希腊语来源 geographos 字面就是「书写大地的人」。"}],"abstract":[{"en":"Picture a person who carries a map in the head instead of the hand.","cn":"想象一个人把地图装在心里，而不是拿在手上。"},{"en":"Picture someone who can feel a border before seeing it.","cn":"想象一个人还没看见边界，就能感觉到它。"},{"en":"Picture a guide whose directions are really a description of the land.","cn":"想象一位向导，他的指路其实是对大地的描述。"}]},"examples":[{"en":"A geographer walked the valley, recording the width and slope of the river.","cn":"一位地理学家沿河谷行走，记录河宽与坡度。"},{"en":"The geographer compared rainfall records from a hundred stations.","cn":"这位地理学家比较了一百个站点的降水记录。"},{"en":"A human geographer studied how the new road changed village life.","cn":"一位人文地理学家研究了新公路如何改变村庄生活。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「geo（大地）+ grapher（书写者）」——书写大地的人 → 地理学家","word":"geographer"},"root":"拉丁语 geographus，来自希腊语 geographos = ge「大地」+ graphein「书写」+ -os（人）。ge 更深来源不确定；graphein 词根清楚。","sensesIntro":{"en":"Eight senses move from the general practitioner to physical and human specialists, historical mapmakers, regional describers, teachers, digital specialists, and finally to anyone who knows a place deeply.","cn":"八个义项从一般从业者走到自然与人文专家、历史制图者、区域描述者、教师、数字专家，最后落到任何深谙某地的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person walking a valley with instruments, writing down what the land does.","cn":"核心意象：一个人带着仪器走在河谷里，记录大地的表现。"},"chain":["EARTH-WRITER","FIELD SCHOLAR","PHYSICAL SPECIALIST","HUMAN SPECIALIST","MAPMAKER","PLACE KNOWLEDGE"],"branches":[{"senses":"S1 · S6","en":"RESEARCHER AND TEACHER: the same title covers those who advance the field and those who teach it.","cn":"研究者与教师：同一职称既指推进学科的人，也指教授它的人。"},{"senses":"S2 · S4","en":"TWO BRANCHES: physical and human geographers split the living surface between them.","cn":"两个分支：自然与人文地理学家把活的地表一分为二。"},{"senses":"S3 · S5","en":"DESCRIPTION AND MAP: the oldest tasks were writing down regions and drawing their coasts.","cn":"描述与地图：最古老的任务是记述区域与描画海岸。"},{"senses":"S7","en":"NEW INSTRUMENTS: satellites and digital maps extend the craft without renaming it.","cn":"新工具：卫星与数字地图扩展了技艺，却未改变职称。"},{"senses":"S8","en":"METAPHOR: deep knowledge of a place is treated as a professional qualification.","cn":"比喻：对某地的深刻了解被当作一种专业资格。"}]},"affixes":{"intro":{"en":"Geographer is a Greek compound plus the English agent suffix -er, so its structure is easy to read.","cn":"geographer 是希腊语复合词加英语施事后缀 -er，结构容易读出。"},"latinIntro":{"en":"Latin geographus is the borrowed intermediate; Greek ge and graphein are the ultimate elements.","cn":"拉丁语 geographus 是借入的中间形式；希腊语 ge 与 graphein 是最终语素。"},"items":[{"word":"ge-","structure":"Greek ge (earth)","meaning":"earth","meaningCN":"大地","example":"Ge- marks earth sciences.","exampleCN":"ge- 标记地球科学。"},{"word":"-grapher","structure":"Greek graphein (write) + -er (person)","meaning":"one who writes or draws","meaningCN":"书写或描画的人","example":"-Grapher appears in geographer and photographer.","exampleCN":"-grapher 见于 geographer 与 photographer。"},{"word":"geography","structure":"geo- + -graphy","meaning":"earth description","meaningCN":"对地球的描述；地理学","example":"Geography is what the geographer practises.","exampleCN":"地理学是地理学家从事的学问。"},{"word":"geographer","structure":"geography + -er","meaning":"a practitioner of geography","meaningCN":"地理学的从业者","example":"The geographer mapped the old river channels.","exampleCN":"这位地理学家标绘了古河道。"},{"word":"geographic","structure":"geo- + -graphic","meaning":"relating to geography","meaningCN":"地理的","example":"The geographer used geographic data.","exampleCN":"这位地理学家使用了地理数据。"},{"word":"geographical","structure":"geographic + -al","meaning":"the longer adjective","meaningCN":"较长的形容词形式","example":"The society publishes geographical research.","exampleCN":"该学会出版地理研究。"},{"word":"geographically","structure":"geographical + -ly","meaning":"in spatial terms","meaningCN":"在地理上","example":"The two sites are geographically close.","exampleCN":"两处地点在地理上很近。"},{"word":"geology","structure":"geo- + -logy","meaning":"study of rocks","meaningCN":"研究岩石的学科；地质学","example":"A geologist, not a geographer, studies deep rock.","exampleCN":"研究深部岩石的是地质学家，而非地理学家。"},{"word":"cartographer","structure":"Greek chartes (map) + graphein + -er","meaning":"a mapmaker","meaningCN":"制图者","example":"Cartographers turn survey data into maps.","exampleCN":"制图者把测量数据变成地图。"}],"latinEntries":[{"word":"geographus","structure":"geographus, geographi (m., second declension), from Greek","meaning":"writer on geography","meaningCN":"地理著述者"},{"word":"geographia","structure":"geographia (f., first declension), from Greek","meaning":"description of the earth","meaningCN":"对地球的描述"},{"word":"graphein","structure":"Greek graphein (verb)","meaning":"to write, draw","meaningCN":"书写；描画"}]}},{"word":"terrain","ipa_uk":"/təˈreɪn/","ipa_us":"/təˈreɪn/","definition_zh":"地形；地势；一片土地的自然特征","definition_en":"the physical features and surface of a tract of land, especially as they affect movement or use","core_image":"越野车在碎石坡上颠簸前行，车轮下是坑洼与松石","scene":"越野车驶上碎石坡，车身随坑洼剧烈起伏，司机不断换挡： The jeep struggled over rough terrain full of loose stones.","sceneCN":"这里 terrain 指「一片土地的地形与地表状况」（第 1 个义项：土地的自然起伏与表面特征）；句意为越野车在遍布松石的崎岖地形中艰难前行。","pos":[{"tag":"n.","zh":"地形；地势；地带（可数或不可数，复数为 terrains）"}],"collocations":[{"phrase":"rough terrain","zh":"崎岖地形"},{"phrase":"difficult terrain","zh":"难行的地形"},{"phrase":"mountainous terrain","zh":"山地地形"},{"phrase":"open terrain","zh":"开阔地带"},{"phrase":"terrain map","zh":"地形图"},{"phrase":"cross the terrain","zh":"穿越这片地形"}],"forms":[{"label":"复数（指不同地带）","form":"terrains"},{"label":"形容词（地形的）","form":"terrain-related"},{"label":"同义名词（地形学）","form":"topography"},{"label":"相关形容词（地表的）","form":"terrestrial"},{"label":"核心名词（土地）","form":"territory"}],"derivatives":[{"word":"terrestrial","pos":"adj.","zh":"陆地的；地球的"},{"word":"territory","pos":"n.","zh":"领土；地域"},{"word":"terraineous","pos":"adj.","zh":"地形的（罕用）"},{"word":"topography","pos":"n.","zh":"地形学；地形"},{"word":"terrain park","pos":"n.","zh":"滑雪地形公园"}],"senses":[{"no":"01","title":"The physical features of land","titleCN":"土地的自然起伏与表面特征","definition":"the shape, slope, and surface of a piece of land, including hills, rocks, and gullies","definitionCN":"一片土地的形状、坡度与表面，包括山丘、岩石与冲沟","example":"The jeep struggled over rough terrain full of loose stones.","exampleCN":"越野车在遍布松石的崎岖地形中艰难前行。","why":"Terrain comes from Latin terra 'earth', so it names the earth as something you must cross rather than something you own.","whyCN":"terrain 来自拉丁语 terra「土地」，因此它把土地命名为需要穿越的东西，而非拥有的东西。"},{"no":"02","title":"A tract of land for a purpose","titleCN":"供某种用途的一片土地","definition":"an area of land considered as a unit for building, farming, or military use","definitionCN":"作为建设、耕作或军事用途单位来考虑的一片土地","example":"The engineers surveyed the terrain before laying the foundation.","exampleCN":"工程师在打地基前勘测了这片土地。","why":"A tract becomes terrain when its physical character matters to what you plan to do on it.","whyCN":"当一片土地的自然特征影响你打算做的事时，它就成为 terrain。"},{"no":"03","title":"Ground that affects movement","titleCN":"影响行进的地面","definition":"the surface conditions that help or hinder travel, especially for vehicles and troops","definitionCN":"帮助或阻碍通行、尤其影响车辆与部队行动的地面状况","example":"The tanks slowed in the soft terrain near the river.","exampleCN":"坦克在河边的松软地形中减速。","why":"Military usage made terrain a technical term: what the ground does to movement, not how it looks in a picture.","whyCN":"军事用法使 terrain 成为技术术语：地面如何影响行动，而非照片上好不好看。"},{"no":"04","title":"Rough and difficult country","titleCN":"崎岖难行的地带","definition":"land that is broken, steep, or obstructed enough to make travel slow and dangerous","definitionCN":"破碎、陡峭或受阻到使行进缓慢危险的土地","example":"Rescuers carried the injured climber across difficult terrain.","exampleCN":"救援者抬着受伤的攀登者穿越难行地形。","why":"The word often carries an adjective of difficulty because terrain is defined by resistance to movement.","whyCN":"这个词常与「困难」类形容词连用，因为 terrain 的定义就与对移动的阻力有关。"},{"no":"05","title":"Land represented in a model","titleCN":"模型或地图中的地形","definition":"a digital or physical representation of the land surface used in planning, games, or simulation","definitionCN":"用于规划、游戏或仿真的地表数字或实体再现","example":"The game renders terrain down to individual boulders.","exampleCN":"游戏把地形渲染到每一块巨石。","why":"Once land is data, terrain means the surface mesh: elevation, slope, and texture stored in a file.","whyCN":"当土地变成数据，terrain 就指表面网格：存于文件中的高程、坡度与纹理。"},{"no":"06","title":"Habitat defined by ground features","titleCN":"由地面特征定义的栖息地","definition":"the physical ground conditions that determine which species can live in an area","definitionCN":"决定哪些物种能在某地生存的地面物理条件","example":"The lizard prefers rocky terrain with deep crevices.","exampleCN":"这种蜥蜴偏好有深裂缝的岩石地形。","why":"For a small animal, slope and rock size are not scenery but shelter, so terrain becomes habitat.","whyCN":"对小动物而言，坡度与石块大小不是风景，而是庇护所，因此地形成为栖息地。"},{"no":"07","title":"Abstract: an unfamiliar field","titleCN":"抽象义：陌生的领域","definition":"a field of knowledge or activity, pictured as ground to be crossed","definitionCN":"被想象成需要穿越的地面的知识或活动领域","example":"The book leads readers through uncharted terrain in philosophy.","exampleCN":"这本书带读者穿越哲学中未标注的领域。","why":"The metaphor treats knowledge as landscape: some parts are mapped, others are rough and unknown.","whyCN":"这一比喻把知识当作地貌：有些部分已测绘，另一些则崎岖未知。"},{"no":"08","title":"Ski and outdoor park terrain","titleCN":"滑雪与户外公园地形","definition":"constructed or natural ground features used for skiing, biking, or off-road recreation","definitionCN":"用于滑雪、骑行或越野休闲的人工或天然地面特征","example":"The resort opened a new terrain park for beginners.","exampleCN":"度假村为初学者新开了一座地形公园。","why":"Recreation borrows the word for shaped ground: jumps, rails, and slopes are terrain made on purpose.","whyCN":"休闲领域借这个词指被塑形的地面：跳台、栏杆与坡面都是刻意造出的地形。"}],"etymology":{"intro":{"en":"Terrain comes from French, from Latin terrenum 'earth, ground', built on terra. The Latin root is well attested. Dates are approximate.","cn":"terrain 经法语来自拉丁语 terrenum「土地、地面」，由 terra 构成。拉丁词根书证充分。年代均为约数。"},"items":[{"era":"LATIN TERRA","en":"Terra meant 'earth, land, ground'. It goes back to a reconstructed root for dry land, seen also in territory and terrestrial.","cn":"terra 意为「土地、陆地、地面」。它可上溯到一个表示干地的重构词根，亦见于 territory 与 terrestrial。"},{"era":"LATIN TERRENUM","en":"Terrenum meant 'earthly ground, land', the neuter form of terrenus 'of earth'.","cn":"terrenum 意为「地上的土地」，是 terrenus「土地的」的中性形式。"},{"era":"FRENCH TERRAIN","en":"French terrain carried the sense of ground considered for its surface and quality, especially in hunting and military writing.","cn":"法语 terrain 带有「就表面与性质而言的地面」之义，尤其见于狩猎与军事文献。"},{"era":"ENGLISH BORROWING","en":"English borrowed terrain in the eighteenth century, chiefly in military and surveying contexts.","cn":"英语在 18 世纪借入 terrain，主要用于军事与测量语境。"},{"era":"MODERN EXTENSIONS","en":"Modeling, gaming, and recreation added new senses in the twentieth century; their first dates are not precisely recorded.","cn":"建模、游戏与休闲在 20 世纪增添新义，其最早年代没有精确记载。"}]},"similar":{"note":{"en":"Group one holds land-description words that are easily confused with terrain; group two holds words for land as property, surface, or setting.","cn":"第一组是易与 terrain 混淆的土地描述词；第二组是把土地视为财产、表面或环境的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"territory","ipa":"/ˈterɪtəri/","tag":"political area","definition":"An area under a state's control; it stresses ownership and boundaries rather than surface shape.","definitionCN":"受国家控制的区域；强调所有权与边界，而非地表形状。"},{"word":"terrestrial","ipa":"/təˈrestriəl/","tag":"adjective","definition":"Relating to the earth or to land as opposed to water; it describes a realm, not a surface.","definitionCN":"与地球或陆地（相对于水）有关；它描述领域，而非地表。"},{"word":"terra","ipa":"/ˈterə/","tag":"Latin source","definition":"The Latin word for earth, used in scientific compounds such as terra incognita.","definitionCN":"拉丁语「土地」一词，用于 terra incognita 等学术短语。"},{"word":"terrain","ipa":"/təˈreɪn/","tag":"the surface itself","definition":"The ground's physical character; the word is French in form and is not interchangeable with territory.","definitionCN":"地面的自然特征；其形式来自法语，不能与 territory 互换。"}]},{"heading":"NEAR MEANING","entries":[{"word":"topography","ipa":"/təˈpɒɡrəfi/","tag":"measured relief","definition":"The systematic description of surface features and elevations; terrain is the ground as experienced, topography as measured.","definitionCN":"对地表特征与高程的系统描述；terrain 是体验到的地面，topography 是测量出的地形。"},{"word":"landscape","ipa":"/ˈlændskeɪp/","tag":"visual scene","definition":"The visible appearance of an area, including vegetation and human features; it is what you see, not what you cross.","definitionCN":"一个地区的可见外观，包括植被与人工要素；它是你看到的，而非你穿越的。"},{"word":"ground","ipa":"/ɡraʊnd/","tag":"everyday word","definition":"The surface you stand on; it is neutral and lacks terrain's implication of difficulty.","definitionCN":"你站立其上的表面；它是中性的，不含 terrain 那种困难意味。"},{"word":"relief","ipa":"/rɪˈliːf/","tag":"elevation difference","definition":"The difference in height across an area; it is one measurable property of terrain.","definitionCN":"一个地区内的高度差；它是地形的一项可测属性。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin roots, real land terms and real collocations, not invented rhymes.","cn":"正常联想：真实拉丁词根、真实土地术语与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Terrain and territory share Latin terra, but one is surface and the other is ownership.","cn":"terrain 与 territory 共享拉丁语 terra，但一个指表面，一个指所有权。"},{"en":"Rough terrain is the standard phrase for ground that slows you down.","cn":"rough terrain 是描述拖慢行进的地面的标准短语。"},{"en":"Terrain is what vehicles and troops must cross; landscape is what tourists photograph.","cn":"terrain 是车辆与部队要穿越的，landscape 是游客拍照的。"},{"en":"A terrain map shows slope and elevation, not political borders.","cn":"地形图显示坡度与高程，而非政治边界。"},{"en":"The word entered English through French military vocabulary.","cn":"这个词经法语军事词汇进入英语。"}],"abstract":[{"en":"Picture a field of study with hills, swamps, and unmarked paths.","cn":"想象一个研究领域，里面有山丘、沼泽与没有标记的小路。"},{"en":"Picture a conversation whose ground shifts under every sentence.","cn":"想象一场谈话，每说一句地面都在移动。"},{"en":"Picture a plan that looks easy on paper and turns to loose stone underfoot.","cn":"想象一个计划，纸上容易，脚下却变成松石。"}]},"examples":[{"en":"The jeep struggled over rough terrain full of loose stones.","cn":"越野车在遍布松石的崎岖地形中艰难前行。"},{"en":"The map shows terrain, water, and roads in separate colours.","cn":"地图用不同颜色分别表示地形、水体与道路。"},{"en":"The lizards survive only on rocky terrain with deep cracks.","cn":"这些蜥蜴只在有深裂缝的岩石地形中存活。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「特雷恩」——车轮底下起伏不平的那片地 → 地形","word":"terrain"},"root":"法语 terrain，来自拉丁语 terrenum「土地、地面」，由 terra「土地」构成；terra 可上溯到表示干地的重构印欧语词根，亦见于 territory 与 terrestrial。","sensesIntro":{"en":"Eight senses follow ground as surface, tract, obstacle, difficult country, model, habitat, metaphor, and recreation space.","cn":"八个义项让地面依次成为表面、地块、障碍、难行地带、模型、栖息地、比喻与休闲空间。"},"semanticMap":{"core":{"en":"CORE IMAGE: a jeep pitching over loose stones on a steep, broken slope.","cn":"核心意象：一辆越野车在陡峭破碎的坡面上被松石颠得起伏。"},"chain":["LAND SURFACE","TRACT FOR USE","GROUND RESISTANCE","DIFFICULT COUNTRY","SURFACE MODEL","FAMILIARITY AND OBSTACLE"],"branches":[{"senses":"S1 · S2","en":"SURFACE AND TRACT: the same ground is both a physical texture and a unit someone plans to use.","cn":"表面与地块：同一片地既是物理质地，也是有人打算使用的单位。"},{"senses":"S3 · S4","en":"RESISTANCE: terrain becomes a technical word when the ground fights movement.","cn":"阻力：当地面与移动对抗时，terrain 成为技术词。"},{"senses":"S5","en":"DATA: the land is reduced to elevation, slope, and texture in a model.","cn":"数据：在模型中，土地被化简为高程、坡度与纹理。"},{"senses":"S6 · S8","en":"LIVING AND PLAYING: crevices are shelter for a lizard and features for a skier.","cn":"生存与游玩：裂缝对蜥蜴是庇护所，对滑雪者则是地形特征。"},{"senses":"S7","en":"METAPHOR: any unfamiliar field can be crossed like rough country.","cn":"比喻：任何陌生领域都能像崎岖地带一样被穿越。"}]},"affixes":{"intro":{"en":"Terrain's family is built on Latin terra, one of the most productive land roots in English.","cn":"terrain 的词族建立在拉丁语 terra 上，这是英语中最多产的土地词根之一。"},"latinIntro":{"en":"Latin terra and terrenum stand behind terrain; the same root gives territory, terrestrial, and terrace.","cn":"拉丁语 terra 与 terrenum 支撑 terrain；同一词根还给出 territory、terrestrial 与 terrace。"},"items":[{"word":"terra","structure":"Latin terra (f., first declension)","meaning":"earth, land","meaningCN":"土地；陆地","example":"Terra is the root of many English land words.","exampleCN":"terra 是许多英语土地词的词根。"},{"word":"terrenum","structure":"Latin terrenum (n., second declension)","meaning":"earthly ground","meaningCN":"地上的土地","example":"Terrenum passed through French as terrain.","exampleCN":"terrenum 经法语变为 terrain。"},{"word":"terrain","structure":"French terrain, from terrenum","meaning":"the surface of the land","meaningCN":"土地的地表；地形","example":"The terrain decides how fast a column can move.","exampleCN":"地形决定一队人马能走多快。"},{"word":"territory","structure":"Latin territorium (land around a town)","meaning":"an area under control","meaningCN":"受控制的区域；领土","example":"Territory stresses ownership, not slope.","exampleCN":"territory 强调所有权，而非坡度。"},{"word":"terrestrial","structure":"Latin terrestris + -al","meaning":"of the earth or land","meaningCN":"地球的；陆生的","example":"Terrestrial animals cross terrain; aquatic ones do not.","exampleCN":"陆生动物穿越地形，水生动物则不。"},{"word":"terrace","structure":"Old French terrace, from Latin terra","meaning":"a raised flat platform of earth","meaningCN":"高出地面的平台；梯田","example":"Farmers cut terraces into the hillside terrain.","exampleCN":"农民在山坡地形上开出梯田。"},{"word":"topography","structure":"Greek topos (place) + -graphy","meaning":"measured surface description","meaningCN":"对地表的测量描述；地形学","example":"Topography measures what terrain feels like.","exampleCN":"地形学测量 terrain 所感受到的东西。"},{"word":"landscape","structure":"land + -scape (shape, condition)","meaning":"the visible appearance of land","meaningCN":"土地的可见外观；景观","example":"Landscape is seen; terrain is crossed.","exampleCN":"landscape 被看见，terrain 被穿越。"},{"word":"relief","structure":"Italian rilievo, from Latin relevare (to raise)","meaning":"elevation difference","meaningCN":"高程差；起伏","example":"Relief is one property of terrain.","exampleCN":"起伏是地形的一项属性。"}],"latinEntries":[{"word":"terra","structure":"terra, terrae (f., first declension)","meaning":"earth, land","meaningCN":"土地；陆地"},{"word":"terrenum","structure":"terrenum, terreni (n., second declension)","meaning":"earthly ground, land","meaningCN":"地上的土地"},{"word":"territorium","structure":"territorium, territorii (n., second declension)","meaning":"territory","meaningCN":"领土；地域"}]}},{"word":"topography","ipa_uk":"/təˈpɒɡrəfi/","ipa_us":"/təˈpɑːɡrəfi/","definition_zh":"地形；地形学；地表起伏与特征的测绘描述","definition_en":"the detailed arrangement of surface features in an area, or the science of describing and mapping them","core_image":"测绘员站在山脊上，把周围山脊、谷地与村落逐一标到图上","scene":"测绘员站在山顶，把周围的山脊、谷地和村落位置逐一标在图上： The surveyor mapped the topography of the valley from the ridge.","sceneCN":"这里 topography 指「地表起伏与特征的测绘描述」（第 1 个义项：一个地区地表特征的整体排列）；句意为测绘员从山脊上测绘了山谷的地形。","pos":[{"tag":"n.","zh":"地形；地形学（学科义不可数，具体地形描述可数）"}],"collocations":[{"phrase":"the topography of the region","zh":"该地区的地形"},{"phrase":"rugged topography","zh":"崎岖地形"},{"phrase":"topography map","zh":"地形图"},{"phrase":"sea-floor topography","zh":"海底地形"},{"phrase":"surface topography","zh":"表面形貌"},{"phrase":"map the topography","zh":"测绘地形"}],"forms":[{"label":"复数（指不同地区的地形）","form":"topographies"},{"label":"形容词","form":"topographic"},{"label":"形容词（变体）","form":"topographical"},{"label":"副词","form":"topographically"},{"label":"从业者","form":"topographer"}],"derivatives":[{"word":"topographic","pos":"adj.","zh":"地形的；地形学的"},{"word":"topographical","pos":"adj.","zh":"地形的（变体）"},{"word":"topographer","pos":"n.","zh":"地形测绘者"},{"word":"topographically","pos":"adv.","zh":"在地形上"},{"word":"toponym","pos":"n.","zh":"地名"}],"senses":[{"no":"01","title":"The arrangement of surface features","titleCN":"地表特征的整体排列","definition":"the natural and built features of an area's surface, considered as a whole pattern","definitionCN":"一个地区地表的自然与人工特征，作为整体格局来考虑","example":"The surveyor mapped the topography of the valley from the ridge.","exampleCN":"测绘员从山脊上测绘了山谷的地形。","why":"Topos is 'place' and -graphy is 'writing', so topography is a written portrait of a place's surface.","whyCN":"topos 是「地方」，-graphy 是「书写」，因此 topography 是对某地表面的书面画像。"},{"no":"02","title":"The science of describing surfaces","titleCN":"描述与测绘地表特征的学科","definition":"the branch of knowledge that measures and represents surface features and elevations","definitionCN":"测量并再现地表特征与高程的知识分支","example":"Topography supplies the elevation data used by engineers.","exampleCN":"地形学提供工程师使用的高程数据。","why":"The word names both the object and the discipline, because the discipline began as systematic description.","whyCN":"这个词既指对象也指学科，因为该学科最初就是系统描述。"},{"no":"03","title":"Relief and elevation difference","titleCN":"地势起伏与高程差","definition":"the range of heights and slopes within an area","definitionCN":"一个地区内高度与坡度的变化范围","example":"The topography rises sharply behind the village.","exampleCN":"村庄背后的地势急剧升高。","why":"Relief is the measurable core of topography: how much the surface goes up and down.","whyCN":"起伏是地形可测量的核心：地表上下变化多少。"},{"no":"04","title":"A mapped representation","titleCN":"作为成果的地形图","definition":"a map or dataset that shows surface shape and elevation, usually with contours","definitionCN":"用等高线等符号显示地表形状与高程的地图或数据集","example":"The topography shows a steep scarp along the fault.","exampleCN":"地形图显示出沿断层的陡坎。","why":"By metonymy the word moves from the land to its representation, so a sheet of paper can be 'a topography'.","whyCN":"通过转喻，这个词从土地转向其再现，因此一张纸也可以被称为「一幅地形图」。"},{"no":"05","title":"Sea-floor topography","titleCN":"海底地形","definition":"the shape of the ocean floor, mapped by sonar and called bathymetry in technical use","definitionCN":"用声呐测绘的海底形状，技术语境中称 bathymetry","example":"The topography of the shelf controls how waves break.","exampleCN":"陆架地形控制波浪如何破碎。","why":"The same tools that map dry land can map the sea floor, so the word extends downward.","whyCN":"测绘陆地的方法也能测绘海底，因此这个词向下延伸。"},{"no":"06","title":"Micro-topography of a surface","titleCN":"材料表面的微观形貌","definition":"the small-scale roughness or pattern of a surface, measured in micrometres","definitionCN":"以微米计的表面微小粗糙度或图案","example":"The coating's topography affects how water drips away.","exampleCN":"涂层表面形貌影响水如何滴落。","why":"Scale shrinks, but the logic stays: the arrangement of highs and lows on a surface.","whyCN":"尺度缩小，逻辑不变：表面上高低点的排列。"},{"no":"07","title":"Corneal topography in medicine","titleCN":"医学中的角膜地形图","definition":"a mapped profile of the cornea's curvature used in eye examination","definitionCN":"用于眼科检查的角膜曲率测绘剖面","example":"Corneal topography revealed a slight cone shape.","exampleCN":"角膜地形图显示轻微的圆锥形。","why":"Medicine borrows the word for any curved surface whose shape must be measured precisely.","whyCN":"医学借用这个词指任何必须精确测量形状的曲面。"},{"no":"08","title":"Abstract: the shape of a field","titleCN":"抽象义：某一领域的格局","definition":"the overall configuration of a field of knowledge or activity, including its peaks and gaps","definitionCN":"某一知识或活动领域的整体构形，包括其高峰与空白","example":"The book maps the topography of modern poetry.","exampleCN":"这本书描绘了现代诗歌的地形。","why":"The metaphor treats ideas as terrain: some regions are crowded, others empty, and the shape guides exploration.","whyCN":"这一比喻把观念当作地貌：有的区域拥挤，有的空白，而形状指引探索。"}],"etymology":{"intro":{"en":"Topography is Greek for 'place-writing'. The second element is clear; the origin of topos is uncertain. Dates are approximate.","cn":"topography 是希腊语「书写地方」。第二个语素清楚，topos 的来源不确定。年代均为约数。"},"items":[{"era":"GREEK TOPOS","en":"Topos meant 'place, region'. Its deeper origin is unknown; suggested Indo-European links are reconstructions rather than established derivations.","cn":"topos 意为「地方、区域」。其更深来源不明；所提印欧语关联均属重构形式，而非已证实的派生。"},{"era":"GREEK TOPOGRAPHIA","en":"Topographia meant a written description of a place, listing its features rather than measuring them.","cn":"topographia 意为对某地的书面描述，罗列其特征而非测量它们。"},{"era":"LATIN TOPOGRAPHIA","en":"Latin borrowed the Greek term, and English took it in the sixteenth century for descriptions of particular places.","cn":"拉丁语借入这个希腊术语，英语在 16 世纪借入，用于描述特定地方。"},{"era":"SURVEYING SENSE","en":"With accurate instruments, topography shifted from description to measurement of elevation and slope.","cn":"随着精密仪器的出现，topography 从描述转向对高程与坡度的测量。"},{"era":"TECHNICAL EXTENSIONS","en":"Sea-floor, micro-surface, and medical uses developed in the nineteenth and twentieth centuries; exact first dates vary.","cn":"海底、微观表面与医学用途在 19、20 世纪发展，确切首见年代各不相同。"}]},"similar":{"note":{"en":"Group one holds place-description words from the same Greek stock; group two holds terms for land shape and mapping.","cn":"第一组是同出希腊语词干的地方描述词；第二组是地表形状与制图术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"topographic","ipa":"/təˈpɒɡræfɪk/","tag":"adjective","definition":"Relating to topography; it modifies maps and surveys rather than naming the subject.","definitionCN":"与地形有关的；它修饰地图与测量，而非命名学科。"},{"word":"topographer","ipa":"/təˈpɒɡrəfə/","tag":"person","definition":"A person who measures and describes surface features; the practitioner of topography.","definitionCN":"测量并描述地表特征的人；地形学的从业者。"},{"word":"toponym","ipa":"/ˈtɒpənɪm/","tag":"place name","definition":"A place name, from topos plus onyma 'name'; it is a different second element.","definitionCN":"地名，由 topos 加 onyma「名字」构成；第二个语素不同。"},{"word":"typography","ipa":"/taɪˈpɒɡrəfi/","tag":"spelling trap","definition":"The arrangement of printed letters, from typos 'impression' rather than topos 'place'.","definitionCN":"印刷字母的排布，来自 typos「印记」而非 topos「地方」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"terrain","ipa":"/təˈreɪn/","tag":"ground as crossed","definition":"The physical character of land as something to travel over; topography is its measured description.","definitionCN":"土地作为通行对象的自然特征；topography 是对它的测量描述。"},{"word":"relief","ipa":"/rɪˈliːf/","tag":"height variation","definition":"The difference between the highest and lowest points; it is one component of topography.","definitionCN":"最高点与最低点的高差；它是地形的一个组成部分。"},{"word":"bathymetry","ipa":"/bəˈθɪmətri/","tag":"underwater twin","definition":"The measurement of water depth and sea-floor shape, the marine counterpart of topography.","definitionCN":"水深与海底形状的测量，是地形学的海洋对应词。"},{"word":"cartography","ipa":"/kɑːˈtɒɡrəfi/","tag":"map-making","definition":"The craft of making maps; topography supplies the data that cartography displays.","definitionCN":"制作地图的技艺；地形学提供制图所显示的数据。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek morphemes, real survey terms and real collocations, not invented rhymes.","cn":"正常联想：真实希腊语素、真实测量术语与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Topos is place; -graphy is writing: topography is place-writing.","cn":"topos 是地方，-graphy 是书写：topography 就是书写地方。"},{"en":"Do not confuse topography with typography: place versus printed type.","cn":"不要把 topography 与 typography 混淆：一个是地方，一个是印刷字体。"},{"en":"The family runs topography, topographic, topographer, topographically.","cn":"词族包括 topography、topographic、topographer、topographically。"},{"en":"Contours on a map are the classic picture of topography.","cn":"地图上的等高线是地形的经典图像。"},{"en":"Sea-floor topography has its own name: bathymetry.","cn":"海底地形有专门名称：bathymetry。"}],"abstract":[{"en":"Picture an invisible landscape drawn only with lines of equal height.","cn":"想象一片看不见的风景，只用等高线画出来。"},{"en":"Picture a field of study with peaks, valleys, and empty basins.","cn":"想象一个研究领域，有山峰、谷地与空盆地。"},{"en":"Picture a surface so finely wrinkled that water chooses its own path.","cn":"想象一个表面皱得极细，水自己选择路径。"}]},"examples":[{"en":"The surveyor mapped the topography of the valley from the ridge.","cn":"测绘员从山脊上测绘了山谷的地形。"},{"en":"Rugged topography keeps the two villages separated in winter.","cn":"崎岖地形使两个村庄在冬季彼此隔绝。"},{"en":"Corneal topography is routine before laser eye surgery.","cn":"激光眼科手术前例行检查角膜地形。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「topo（地方）+ graphy（书写）」——把一个地方的高低起伏写下来 → 地形、地形学","word":"topography"},"root":"希腊语 topographia = topos「地方」+ graphein「书写」+ -ia；经拉丁语 topographia 进入英语。topos 更深来源不确定，所提印欧关联均属重构形式。","sensesIntro":{"en":"Eight senses move from surface arrangement to the science, relief, mapped output, sea floor, micro-surface, medical imaging, and finally to the shape of any field.","cn":"八个义项从地表排列走到学科、起伏、成图、海底、微观表面、医学成像，最后落到任何领域的格局。"},"semanticMap":{"core":{"en":"CORE IMAGE: a surveyor on a ridge marking every hill, valley and village onto one sheet.","cn":"核心意象：测绘员站在山脊上，把每座山、每条谷、每个村都标到同一张图上。"},"chain":["PLACE-WRITING","SURFACE ARRANGEMENT","MEASURED RELIEF","MAPPED SHEET","SUBMARINE TWIN","SHAPE OF A FIELD"],"branches":[{"senses":"S1 · S2","en":"OBJECT AND DISCIPLINE: the arrangement and the science of describing it share one name.","cn":"对象与学科：地表排列与描述它的学科共用一名。"},{"senses":"S3 · S4","en":"RELIEF AND MAP: elevation becomes lines, and the lines become a sheet you can carry.","cn":"起伏与地图：高程变成线条，线条又成为可携带的图纸。"},{"senses":"S5","en":"DOWNWARD: the same logic maps the sea floor under a different technical name.","cn":"向下延伸：同一逻辑以另一技术名测绘海底。"},{"senses":"S6 · S7","en":"SCALE SHIFT: micrometre roughness and the curve of an eye are both surfaces to be profiled.","cn":"尺度转换：微米级粗糙度与眼球曲面都是待测绘的表面。"},{"senses":"S8","en":"METAPHOR: knowledge has high ground and basins, and its shape can be mapped.","cn":"比喻：知识有高地与盆地，其形状可以被测绘。"}]},"affixes":{"intro":{"en":"Topography is built from two Greek elements and a noun ending, with a full family of derivatives.","cn":"topography 由两个希腊语素与一个名词词尾构成，并有一整族派生词。"},"latinIntro":{"en":"Latin topographia is the borrowed form; Greek topos and graphein are the ultimate elements.","cn":"拉丁语 topographia 是借入形式；希腊语 topos 与 graphein 是最终语素。"},"items":[{"word":"topos","structure":"Greek topos (place, region)","meaning":"place","meaningCN":"地方；区域","example":"Topos is the place element in topography.","exampleCN":"topos 是 topography 中的「地方」语素。"},{"word":"-graphy","structure":"Greek graphein (to write) + -ia","meaning":"writing, description","meaningCN":"书写；描述","example":"-Graphy also appears in geography and biography.","exampleCN":"-graphy 也见于 geography 与 biography。"},{"word":"topography","structure":"topos + -graphy","meaning":"description of a place's surface","meaningCN":"对某地表面的描述；地形学","example":"Topography records slopes and elevations.","exampleCN":"地形学记录坡度与高程。"},{"word":"topographic","structure":"topography + -ic","meaning":"relating to topography","meaningCN":"地形的；地形学的","example":"A topographic map uses contour lines.","exampleCN":"地形图使用等高线。"},{"word":"topographical","structure":"topographic + -al","meaning":"the longer adjective","meaningCN":"较长的形容词形式","example":"Topographical surveys guide road building.","exampleCN":"地形测量指导道路建设。"},{"word":"topographer","structure":"topography + -er (person)","meaning":"a surface surveyor","meaningCN":"地形测绘者","example":"The topographer fixed the height of each peak.","exampleCN":"地形测绘者测定了每座山峰的高度。"},{"word":"topographically","structure":"topographical + -ly","meaning":"in topographic terms","meaningCN":"从地形上","example":"The two sites are topographically similar.","exampleCN":"两处地点在地形上相似。"},{"word":"toponym","structure":"topos + Greek onyma (name)","meaning":"a place name","meaningCN":"地名","example":"Toponyms preserve the old topography.","exampleCN":"地名保存了旧时的地形信息。"},{"word":"bathymetry","structure":"Greek bathys (deep) + metron (measure)","meaning":"measurement of sea depth","meaningCN":"水深测量；海底地形测量","example":"Bathymetry is the ocean's topography.","exampleCN":"bathymetry 就是海洋的地形学。"}],"latinEntries":[{"word":"topographia","structure":"topographia (f., first declension), from Greek","meaning":"description of a place","meaningCN":"对某地的描述"},{"word":"topos","structure":"Greek topos (m.)","meaning":"place, region","meaningCN":"地方；区域"},{"word":"graphein","structure":"Greek graphein (verb)","meaning":"to write, draw","meaningCN":"书写；描画"}]}},{"word":"topographic","ipa_uk":"/təˈpɒɡræfɪk/","ipa_us":"/ˌtɒpəˈɡræfɪk/","definition_zh":"地形的；地形学的；与地表起伏测绘有关的","definition_en":"relating to the shape, elevation, and detailed description of a land surface","core_image":"一张布满等高线的图纸，密集线条标出陡坡","scene":"工程队摊开一张带等高线的图纸，沿着密集的线条判断坡度： Engineers read a topographic map before routing the new road.","sceneCN":"这里 topographic 指「与地表起伏测绘有关的」（第 2 个义项：以等高线等表示地形的地图）；句意为工程师在规划新路前阅读地形图。","pos":[{"tag":"adj.","zh":"地形的；地形学的；地形测绘的"}],"collocations":[{"phrase":"topographic map","zh":"地形图"},{"phrase":"topographic survey","zh":"地形测量"},{"phrase":"topographic relief","zh":"地形起伏"},{"phrase":"topographic feature","zh":"地形要素"},{"phrase":"topographic profile","zh":"地形剖面"},{"phrase":"topographic data","zh":"地形数据"}],"forms":[{"label":"副词","form":"topographically"},{"label":"名词（学科）","form":"topography"},{"label":"名词（从业者）","form":"topographer"},{"label":"形容词（完整变体）","form":"topographical"},{"label":"比较级（较少用）","form":"more topographic"}],"derivatives":[{"word":"topography","pos":"n.","zh":"地形；地形学"},{"word":"topographer","pos":"n.","zh":"地形测绘者"},{"word":"topographical","pos":"adj.","zh":"地形的（完整变体）"},{"word":"topographically","pos":"adv.","zh":"从地形上"},{"word":"toponym","pos":"n.","zh":"地名"}],"senses":[{"no":"01","title":"Relating to surface shape","titleCN":"与地表形状有关的","definition":"concerning the form, slope, and arrangement of features on a land surface","definitionCN":"关于陆地表面的形态、坡度与要素排列","example":"Topographic relief controls where water gathers.","exampleCN":"地形起伏决定水在哪里汇集。","why":"The adjective attaches the idea of place-description to any noun, so a feature becomes topographic when its shape matters.","whyCN":"这个形容词把「描述地方」的观念附着到任何名词上，因此当形状重要时，某要素就是地形的。"},{"no":"02","title":"Of a map with contours","titleCN":"以等高线表示地形的地图","definition":"describing a map that shows elevation and surface form, usually with contour lines","definitionCN":"描述以等高线等符号显示高程与地表形态的地图","example":"Engineers read a topographic map before routing the new road.","exampleCN":"工程师在规划新路前阅读地形图。","why":"A topographic map is the standard product of the discipline, so the adjective became part of the map's name.","whyCN":"地形图是该学科的标准产品，因此这个形容词成了地图名称的一部分。"},{"no":"03","title":"Of a survey or measurement","titleCN":"地形测量性质的","definition":"relating to the measurement of elevations and positions on the ground","definitionCN":"与地面高程与位置的测量有关","example":"The topographic survey fixed the height of every corner.","exampleCN":"地形测量确定了每个角点的高程。","why":"Surveying turns terrain into numbers, and the adjective marks that measured kind of work.","whyCN":"测量把地形变成数字，这个形容词标记的正是这种测量工作。"},{"no":"04","title":"Of differences in elevation","titleCN":"高程差异的","definition":"describing variation in height across an area that affects climate, drainage, or travel","definitionCN":"描述一个地区内影响气候、排水或通行的高度变化","example":"Topographic barriers keep the wet air on the coast.","exampleCN":"地形屏障把湿空气挡在海岸。","why":"Height difference is the most measurable part of surface shape, so it often takes the adjective.","whyCN":"高差是地表形状中最可测量的部分，因此常由这个形容词修饰。"},{"no":"05","title":"Of named surface features","titleCN":"地形要素的","definition":"relating to specific features such as ridges, valleys, and scarps shown on a survey","definitionCN":"与测量图上显示的山脊、谷地、陡坎等具体要素有关","example":"Each topographic feature was labelled with its elevation.","exampleCN":"每个地形要素都标注了高程。","why":"Once features are catalogued, the adjective distinguishes them from cultural or biological features.","whyCN":"要素被编目后，这个形容词把它们与文化或生物要素区分开。"},{"no":"06","title":"Of military ground advantage","titleCN":"军事地形优势的","definition":"describing ground features that give a tactical advantage, such as height or cover","definitionCN":"描述提供战术优势（如高度或掩蔽）的地面特征","example":"Topographic control decided the outcome of the skirmish.","exampleCN":"地形控制权决定了这场小规模交战的结果。","why":"Armies read ground as advantage, so topographic becomes a staff word for position and visibility.","whyCN":"军队把地面读作优势，因此 topographic 成为参谋用语，指位置与通视。"},{"no":"07","title":"Of medical surface profiling","titleCN":"医学表面测绘的","definition":"relating to the mapped curvature of a body surface, especially the cornea","definitionCN":"与体表（尤其角膜）曲率的测绘有关","example":"Topographic imaging showed the cornea's uneven curve.","exampleCN":"地形成像显示了角膜不平整的曲率。","why":"The adjective is generic enough to describe any surface whose highs and lows must be mapped.","whyCN":"这个形容词足够通用，可描述任何必须测绘高低起伏的表面。"},{"no":"08","title":"Abstract: structurally arranged","titleCN":"抽象义：按结构布局的","definition":"describing the overall structural layout of an idea, field, or system","definitionCN":"描述某一观念、领域或系统的整体结构布局","example":"The essay offers a topographic view of the novel's themes.","exampleCN":"这篇文章提供了小说主题的地形式视角。","why":"The metaphor treats abstract elements as features on a surface, with peaks, basins, and connections.","whyCN":"这一比喻把抽象要素当作地表上的特征，有峰、有盆、有连接。"}],"etymology":{"intro":{"en":"Topographic is the Greek-derived adjective of topography, formed with -ikos. The elements are recorded; the origin of topos is not. Dates are approximate.","cn":"topographic 是 topography 的希腊语来源形容词，由 -ikos 构成。语素有书证，topos 的来源不明。年代均为约数。"},"items":[{"era":"GREEK TOPOS","en":"Topos meant 'place'. Its deeper origin is uncertain; the Indo-European links sometimes proposed are reconstructions, not proved derivations.","cn":"topos 意为「地方」。其更深来源不确定；有时提出的印欧语关联是重构形式，而非已证实的派生。"},{"era":"GREEK TOPOGRAPHIKOS","en":"Topographikos meant 'of place-description', built on topographia with the adjective suffix -ikos.","cn":"topographikos 意为「属于地方描述的」，由 topographia 加形容词后缀 -ikos 构成。"},{"era":"LATIN TOPOGRAPHICUS","en":"Latin borrowed the Greek adjective as topographicus, and English shortened it to topographic.","cn":"拉丁语借入希腊形容词作 topographicus，英语再缩短为 topographic。"},{"era":"CARTOGRAPHIC USE","en":"From the eighteenth century the adjective attached to maps and surveys that showed elevation.","cn":"从 18 世纪起，这个形容词附着于显示高程的地图与测量。"},{"era":"SCIENTIFIC EXTENSIONS","en":"Medical and microscopic uses are modern; their exact first dates are not fixed.","cn":"医学与微观用途属现代用法，其确切首见年代未固定。"}]},"similar":{"note":{"en":"Group one holds forms from the same Greek stock that are easily swapped; group two holds adjectives for related kinds of shape and mapping.","cn":"第一组是同出希腊语词干、极易互换的形式；第二组是描述相关形状与制图的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"topographical","ipa":"/ˌtɒpəˈɡræfɪkl/","tag":"fuller variant","definition":"The longer adjective with the same meaning; British usage often prefers it in formal writing.","definitionCN":"意义相同的较长形容词；英式正式写作常用它。"},{"word":"topography","ipa":"/təˈpɒɡrəfi/","tag":"noun","definition":"The subject or the surface arrangement itself; topographic is the adjective that modifies other nouns.","definitionCN":"学科或地表排列本身；topographic 是修饰其它名词的形容词。"},{"word":"topographer","ipa":"/təˈpɒɡrəfə/","tag":"person","definition":"The person who measures surfaces; it cannot modify a noun such as map.","definitionCN":"测量地表的人；它不能修饰 map 之类的名词。"},{"word":"typographic","ipa":"/ˌtaɪpəˈɡræfɪk/","tag":"one letter away","definition":"Relating to printing and type design, from typos 'impression'; it has nothing to do with land.","definitionCN":"与印刷和字体设计有关，来自 typos「印记」；与土地无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"geographic","ipa":"/dʒiəˈɡræfɪk/","tag":"wider scope","definition":"Relating to geography as a whole, including human and regional patterns; topographic concerns surface shape.","definitionCN":"与整个地理学有关，包括人文与区域格局；topographic 关注地表形状。"},{"word":"cartographic","ipa":"/ˌkɑːtəˈɡræfɪk/","tag":"map-making","definition":"Relating to the design and production of maps rather than to the land's shape itself.","definitionCN":"与地图设计与制作有关，而非土地形状本身。"},{"word":"hypsometric","ipa":"/ˌhɪpsəˈmetrɪk/","tag":"elevation statistics","definition":"Relating to the measurement and statistical description of elevation; a narrower technical term.","definitionCN":"与高程测量及统计描述有关；范围更窄的技术术语。"},{"word":"geomorphic","ipa":"/ˌdʒiːəˈmɔːfɪk/","tag":"landform origin","definition":"Relating to the origin and development of landforms rather than to their mapped shape.","definitionCN":"与地貌的成因与发育有关，而非其测绘形状。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek morphemes, real mapping terms and real collocations, not invented rhymes.","cn":"正常联想：真实希腊语素、真实制图术语与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Topographic map is the fixed phrase; the adjective rarely appears alone in everyday speech.","cn":"topographic map 是固定短语；这个形容词在日常中很少单独出现。"},{"en":"Topography is the noun; topographer is the person; topographic is the adjective.","cn":"topography 是名词，topographer 是人，topographic 是形容词。"},{"en":"Contours are the signature of a topographic sheet.","cn":"等高线是地形图的标志。"},{"en":"Do not confuse topographic with typographic: land versus type.","cn":"不要把 topographic 与 typographic 混淆：一个是土地，一个是字体。"},{"en":"Topographic relief means the range of heights, not emotional relief.","cn":"topographic relief 指高度差，不是情绪上的宽慰。"}],"abstract":[{"en":"Picture a sheet of paper that tells you where the ground rises before you arrive.","cn":"想象一张纸，在你到达之前就告诉你地面哪里升高。"},{"en":"Picture a surface described entirely by lines that never cross.","cn":"想象一个表面完全由永不相交的线条描述。"},{"en":"Picture an argument drawn as a map of peaks and basins.","cn":"想象一场论证被画成有峰有盆的地图。"}]},"examples":[{"en":"Engineers read a topographic map before routing the new road.","cn":"工程师在规划新路前阅读地形图。"},{"en":"The topographic survey recorded a steep scarp behind the town.","cn":"地形测量记录了镇后的陡坎。"},{"en":"Topographic relief explains why the two valleys have different rainfall.","cn":"地形起伏解释了为什么两条谷地降水不同。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"「topo（地方）+ graphic（描绘的）」——描绘一个地方高低起伏的 → 地形的","word":"topographic"},"root":"拉丁语 topographicus，来自希腊语 topographikos = topos「地方」+ graphein「书写」+ -ikos「……的」。topos 更深来源不确定，所提印欧关联均属重构形式。","sensesIntro":{"en":"Eight senses run from surface shape to contour maps, surveys, elevation differences, named features, military ground, medical profiling, and finally abstract structure.","cn":"八个义项从地表形状走到等高线图、测量、高程差、命名要素、军事地形、医学测绘，最后落到抽象结构。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sheet full of contour lines, packed tightly where the slope is steep.","cn":"核心意象：一张布满等高线的图纸，坡陡处线条密集。"},"chain":["SURFACE SHAPE","CONTOUR MAP","MEASURED SURVEY","ELEVATION DIFFERENCE","TACTICAL GROUND","STRUCTURAL LAYOUT"],"branches":[{"senses":"S1 · S3","en":"SHAPE AND MEASUREMENT: the adjective covers both what the surface is and how it is measured.","cn":"形状与测量：这个形容词既指表面是什么样，也指如何测量它。"},{"senses":"S2 · S5","en":"MAP AND FEATURES: contours turn a surface into a sheet, and named features give it a vocabulary.","cn":"地图与要素：等高线把表面变成图纸，命名要素则给它一套词汇。"},{"senses":"S4 · S6","en":"HEIGHT AS POWER: the same elevation that controls drainage also controls visibility and defence.","cn":"高度即力量：控制排水的高程，也控制通视与防御。"},{"senses":"S7","en":"SCALE SHIFT: the cornea is mapped with the same logic as a mountain range.","cn":"尺度转换：角膜与山脉用同一逻辑测绘。"},{"senses":"S8","en":"METAPHOR: abstract ideas acquire peaks, basins, and connecting routes.","cn":"比喻：抽象观念获得山峰、盆地与连接路径。"}]},"affixes":{"intro":{"en":"The adjective is built from the topography stem plus the Greek adjective ending -ic.","cn":"这个形容词由 topography 词干加希腊形容词词尾 -ic 构成。"},"latinIntro":{"en":"Latin topographicus and Greek topographikos stand behind the word; topos and graphein are the ultimate elements.","cn":"拉丁语 topographicus 与希腊语 topographikos 支撑这个词；topos 与 graphein 是最终语素。"},"items":[{"word":"topos","structure":"Greek topos (place)","meaning":"place","meaningCN":"地方","example":"Topos supplies the place element.","exampleCN":"topos 提供「地方」语素。"},{"word":"-graphic","structure":"Greek graphein (write) + -ikos","meaning":"relating to drawing or description","meaningCN":"与描画或描述有关的","example":"-Graphic appears in geographic and topographic.","exampleCN":"-graphic 见于 geographic 与 topographic。"},{"word":"topography","structure":"topos + -graphy","meaning":"surface description","meaningCN":"对地表的描述；地形学","example":"Topography is the noun behind the adjective.","exampleCN":"topography 是这个形容词背后的名词。"},{"word":"topographic","structure":"topography + -ic","meaning":"relating to surface shape","meaningCN":"地形的；与地表形状有关的","example":"A topographic map shows elevation.","exampleCN":"地形图显示高程。"},{"word":"topographical","structure":"topographic + -al","meaning":"the longer adjective","meaningCN":"较长的形容词形式","example":"Topographical writing describes the ground in detail.","exampleCN":"地形描述文字详细描写地面。"},{"word":"topographically","structure":"topographical + -ly","meaning":"in surface terms","meaningCN":"从地形上","example":"The pass is topographically the lowest route.","exampleCN":"这个山口在地形上是最低的路线。"},{"word":"topographer","structure":"topography + -er","meaning":"a surface surveyor","meaningCN":"地形测绘者","example":"The topographer worked from the ridge.","exampleCN":"地形测绘者从山脊上作业。"},{"word":"bathymetric","structure":"Greek bathys (deep) + metron (measure) + -ic","meaning":"relating to sea-floor depth","meaningCN":"与海底深度有关的","example":"Bathymetric data mirror topographic data underwater.","exampleCN":"测深数据是地形数据在水下的对应物。"},{"word":"hypsometric","structure":"Greek hypsos (height) + metron + -ic","meaning":"relating to elevation measurement","meaningCN":"与高程测量有关的","example":"A hypsometric curve summarizes topographic relief.","exampleCN":"高程曲线概括了地形起伏。"}],"latinEntries":[{"word":"topographicus","structure":"Late Latin topographicus, from Greek topographikos","meaning":"of place-description","meaningCN":"属于地方描述的"},{"word":"topographia","structure":"topographia (f., first declension), from Greek","meaning":"description of a place","meaningCN":"对某地的描述"},{"word":"topos","structure":"Greek topos (m.)","meaning":"place","meaningCN":"地方"}]}}]);
